import spidev
import Adafruit_GPIO.SPI as Adafruit_SPI
import Adafruit_GPIO.digitalio as Adafruit_DigitalIO
from gpiozero import MCP3208

MIN_CHANNEL = 0
MAX_CHANNEL = 7
SPI_PORT = 0
SPI_DEVICE = 0
SPI_MAX_SPEED_HZ = 1_000_000


def read_mcp3208_gpiozero(channel):
    """Read MCP3208 channel via gpiozero; return normalized 0.0-1.0 or -1 on error."""
    if not MIN_CHANNEL <= channel <= MAX_CHANNEL:
        print(f"Error: channel {channel} out of range [{MIN_CHANNEL}, {MAX_CHANNEL}]")
        return -1
    try:
        adc = MCP3208(channel=channel, max_voltage=3.3, differential=False)
        value = adc.value
        adc.close()
        return value
    except Exception as e:
        print(f"Error reading MCP3208 via gpiozero: {e}")
        return -1


def read_mcp3208_spidev(channel):
    """Read MCP3208 channel via spidev; return raw 0-4095 or -1 on error."""
    if not MIN_CHANNEL <= channel <= MAX_CHANNEL:
        print(f"Error: channel {channel} out of range [{MIN_CHANNEL}, {MAX_CHANNEL}]")
        return -1
    spi = spidev.SpiDev()
    try:
        spi.open(SPI_PORT, SPI_DEVICE)
        spi.max_speed_hz = SPI_MAX_SPEED_HZ
        spi.mode = 0
        spi.lsbfirst = False
        spi.bits_per_word = 8
        cmd = [0x01, (0x08 | channel) << 4, 0x00]
        data = spi.xfer2(cmd)
        if len(data) < 3:
            print(f"Error: incomplete SPI response on channel {channel}")
            return -1
        return ((data[1] & 0x0F) << 8) | data[2]
    except Exception as e:
        print(f"Error reading MCP3208 via spidev: {e}")
        return -1
    finally:
        try:
            spi.close()
        except Exception:
            pass


def read_mcp3208_adafruit(channel):
    """Read MCP3208 channel via Adafruit_GPIO; return raw 0-4095 or -1 on error."""
    if not MIN_CHANNEL <= channel <= MAX_CHANNEL:
        print(f"Error: channel {channel} out of range [{MIN_CHANNEL}, {MAX_CHANNEL}]")
        return -1
    try:
        spi = Adafruit_SPI.SpiDev(SPI_PORT, SPI_DEVICE, max_speed_hz=SPI_MAX_SPEED_HZ)
        mosi = Adafruit_DigitalIO.DigitalIO(10)
        miso = Adafruit_DigitalIO.DigitalIO(9)
        sclk = Adafruit_DigitalIO.DigitalIO(11)
        adc = Adafruit_SPI.MCP3208(spi, mosi, miso, sclk)
        return adc.read(channel)
    except Exception as e:
        print(f"Error reading MCP3208 via Adafruit_GPIO: {e}")
        return -1
    finally:
        try:
            adc.close()
        except Exception:
            pass
        try:
            spi.close()
        except Exception:
            pass


def main():
    print("=== gpiozero test (channel 0) ===")
    val = read_mcp3208_gpiozero(0)
    if val == -1:
        print("gpiozero read failed")
    else:
        print(f"gpiozero raw: {val}")

    print("=== spidev test (channel 0) ===")
    val = read_mcp3208_spidev(0)
    if val == -1:
        print("spidev read failed")
    else:
        print(f"spidev raw: {val}")

    print("=== Adafruit_GPIO test (channel 0) ===")
    val = read_mcp3208_adafruit(0)
    if val == -1:
        print("Adafruit_GPIO read failed")
    else:
        print(f"Adafruit_GPIO raw: {val}")


if __name__ == "__main__":
    main()

