#!/usr/bin/env python3
"""
LoadCellReader.py

Reads analog data from an MCP3002 ADC over SPI0/CE0 on a Raspberry Pi 4
Model B and converts it to a weight value.

Wiring:
  MCP3002 VDD  -> 3.3 V (Pin 1)
  MCP3002 VREF -> 3.3 V (Pin 1)
  MCP3002 AGND -> GND  (Pin 6)
  MCP3002 DGND -> GND  (Pin 6)
  MCP3002 CLK  -> GPIO11 (SCLK, Pin 23)
  MCP3002 DOUT -> GPIO9  (MISO,  Pin 21)
  MCP3002 DIN  -> GPIO10 (MOSI, Pin 19)
  MCP3002 CS   -> GPIO8  (CE0,   Pin 24)
  Load cell analog out -> MCP3002 CH0

Dependencies:
  pip install spidev
"""

import signal
import sys
import time

import spidev


class LoadCellReader:
    """Reads and converts data from an MCP3002 ADC via SPI."""

    def __init__(self, bus=0, device=0, max_speed_hz=50000):
        self.spi = spidev.SpiDev()
        try:
            self.spi.open(bus, device)
        except OSError as exc:
            raise RuntimeError(
                f"Failed to open SPI bus {bus} device {device}: {exc}"
            ) from exc
        self.spi.max_speed_hz = max_speed_hz
        self.spi.mode = 0b00
        self.spi.bits_per_word = 8

    def send_spi_command(self, data):
        """Send a 3-byte command to the MCP3002 and return the response."""
        try:
            return self.spi.xfer2(data)
        except OSError as exc:
            raise RuntimeError(f"SPI transfer failed: {exc}") from exc

    def extract_10bit(self, response):
        """Extract a 10-bit value from the MCP3002 response bytes."""
        if response is None or len(response) < 3:
            raise RuntimeError("Invalid SPI response length")
        return ((response[1] & 0x03) << 8) | response[2]

    def convert_to_weight(self, raw_data):
        """Convert raw ADC data to a weight value in kilograms."""
        return float(raw_data) * (5.0 / 1023.0)

    def read_raw_data(self):
        """Read raw 10-bit data from the MCP3002 and return it."""
        command = [0x01, 0x80, 0x00]
        response = self.send_spi_command(command)
        return self.extract_10bit(response)

    def close(self):
        """Close the SPI connection."""
        try:
            self.spi.close()
        except OSError:
            pass


def main():
    reader = LoadCellReader(bus=0, device=0, max_speed_hz=50000)

    def shutdown(signum, frame):
        print("\nReceived termination signal, shutting down...")
        reader.close()
        sys.exit(0)

    signal.signal(signal.SIGTERM, shutdown)

    try:
        while True:
            raw_data = reader.read_raw_data()
            weight = reader.convert_to_weight(raw_data)
            print(f"Weight: {weight:.2f} kg")
            time.sleep(0.5)
    except KeyboardInterrupt:
        print("\nProgram stopped by user.")
    except RuntimeError as exc:
        print(f"Error: {exc}", file=sys.stderr)
    finally:
        reader.close()


if __name__ == "__main__":
    main()

