#!/usr/bin/env python3
"""Smart Irrigation System Controller for Raspberry Pi.

Controls a solenoid valve via gpiozero and reads soil moisture from an
MCP3008 ADC over SPI.  Exposes a JSON web API on port 8080 for remote
command and query.  All events are logged to irrigation.log.
"""

import argparse
import json
import logging
import os
import signal
import socket
import sys
import time

import spidev
from gpiozero import DigitalOutputDevice

# ---------------------------------------------------------------------------
# Globals
# ---------------------------------------------------------------------------
_running = True
_valve = None
_spi = None


def _signal_handler(signum, frame):
    """Graceful shutdown on SIGINT / SIGTERM."""
    global _running
    logging.info("Received signal %s – shutting down.", signum)
    _running = False


def _cleanup():
    """Release hardware resources."""
    global _valve, _spi
    if _valve is not None:
        try:
            _valve.off()
            _valve.close()
        except Exception:
            pass
        _valve = None
    if _spi is not None:
        try:
            _spi.close()
        except Exception:
            pass
        _spi = None


def _read_mcp3008(channel: int) -> int:
    """Read a single-ended channel (0-7) from the MCP3008.

    Returns a 10-bit value (0-1023) or raises RuntimeError on SPI failure.
    """
    if not 0 <= channel <= 7:
        raise ValueError(f"Invalid MCP3008 channel {channel}")
    if _spi is None:
        raise RuntimeError("SPI device not initialised")

    # MCP3008 single-ended read: start bit, config byte, channel bits
    cmd = 0b00001000 | (channel << 4)
    tx = [0x01, cmd, 0x00]
    rx = _spi.xfer2(tx)
    if len(rx) != 3:
        raise RuntimeError(f"Unexpected SPI response length {len(rx)}")
    return ((rx[1] & 0x03) << 8) | rx[2]


def _sensor_absent_check(value: int) -> bool:
    """Heuristic: treat a flat line as a sensor-absent indicator."""
    if value == 0 or value == 1023:
        return True
    return False


def _read_moisture() -> int:
    """Read soil moisture from the MCP3008 channel 0.

    Returns a 0-1023 value, or raises RuntimeError on failure.
    """
    raw = _read_mcp3008(0)
    if _sensor_absent_check(raw):
        raise RuntimeError("Sensor absent or wiring fault (read all-zeros or all-ones)")
    return raw


def _set_valve(state: bool):
    """Drive the solenoid valve.  gpiozero uses active_high=True by default."""
    if _valve is None:
        raise RuntimeError("Valve GPIO not initialised")
    _valve.value = 1 if state else 0


def _get_valve_state() -> bool:
    return bool(_valve.value)


def _parse_args():
    p = argparse.ArgumentParser(description="Smart Irrigation System Controller")
    p.add_argument("--moisture_threshold", type=int, default=30,
                   help="Moisture threshold (0-1023) to activate valve")
    p.add_argument("--web_port", type=int, default=8080,
                   help="Web server port (default 8080)")
    p.add_argument("--log_file", type=str, default="irrigation.log",
                   help="Log file path (default irrigation.log)")
    p.add_argument("--valve_pin", type=int, default=17,
                   help="BCM GPIO pin for solenoid valve (default 17)")
    p.add_argument("--spi_channel", type=int, default=0,
                   help="MCP3008 SPI channel (default 0)")
    return p.parse_args()


def _setup_logging(log_file: str):
    logging.basicConfig(
        filename=log_file,
        level=logging.INFO,
        format="%(asctime)s - %(levelname)s - %(message)s",
    )
    logging.info("Starting Smart Irrigation System Controller")


def _init_hardware(valve_pin: int, spi_channel: int):
    global _valve, _spi
    try:
        _valve = DigitalOutputDevice(valve_pin, active_high=True, initial_value=False)
    except Exception as exc:
        logging.error("Failed to initialise valve on GPIO %d: %s", valve_pin, exc)
        raise
    try:
        _spi = spidev.SpiDev()
        _spi.open(0, spi_channel)
        _spi.max_speed_hz = 1_000_000
        _spi.mode = 0
    except Exception as exc:
        logging.error("Failed to initialise SPI bus 0 device %d: %s", spi_channel, exc)
        _cleanup()
        raise


def _handle_command(cmd: dict) -> str:
    action = cmd.get("action")
    if action == "get_status":
        moisture = None
        valve_state = _get_valve_state()
        threshold = args.moisture_threshold
        try:
            moisture = _read_moisture()
        except RuntimeError as exc:
            logging.error("Sensor read failed: %s", exc)
        return json.dumps({
            "moisture": moisture,
            "valve_state": valve_state,
            "threshold": threshold,
        })
    elif action == "toggle_valve":
        new_state = not _get_valve_state()
        try:
            _set_valve(new_state)
        except RuntimeError as exc:
            logging.error("Valve control failed: %s", exc)
            return json.dumps({"error": str(exc)})
        return json.dumps({"valve_state": new_state})
    return json.dumps({"error": "Invalid or missing action"})


def _serve_web_socket(port: int):
    server = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    server.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
    server.bind(("", port))
    server.listen(1)
    server.settimeout(1.0)
    logging.info("Web server listening on port %d", port)
    try:
        while _running:
            try:
                conn, addr = server.accept()
            except socket.timeout:
                continue
            except OSError:
                break
            with conn:
                logging.info("Connection from %s", addr)
                try:
                    data = conn.recv(1024)
                    if not data:
                        continue
                    cmd = json.loads(data.decode("utf-8"))
                    resp = _handle_command(cmd)
                    conn.sendall(resp.encode("utf-8"))
                except json.JSONDecodeError:
                    conn.sendall(b"{}")
                except Exception as exc:
                    logging.error("Web request handling error: %s", exc)
    finally:
        server.close()


def main():
    global args
    args = _parse_args()
    _setup_logging(args.log_file)
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)
    try:
        _init_hardware(args.valve_pin, args.spi_channel)
    except Exception:
        logging.error("Hardware initialisation failed – aborting.")
        sys.exit(1)
    _serve_web_socket(args.web_port)
    _cleanup()
    logging.info("Smart Irrigation System Controller stopped.")


if __name__ == "__main__":
    main()

