import time
import signal
import sys
import board
import busio
import adafruit_lsm303_accel
import adafruit_lsm303dlh_mag
import Adafruit_ADS1x15
import pigpio

# Constants
MOTOR_DIR_PIN = 20
MOTOR_STEP_PIN = 21
MOTOR_MS0_PIN = 14
MOTOR_MS1_PIN = 15
MOTOR_RESOLUTION = 'Full'
MOTOR_DIRECTION = 'CCW'
ADC_GAIN = 1
ADC_CHANNEL = 0
ADC_VREF = 3.3
PWM_FREQUENCY = 500
LOOP_DELAY = 1

# Global state for signal handling
_running = True
_pi = None


def _signal_handler(signum, frame):
    global _running
    _running = False


class MotorController:
    def __init__(self, pi, dir_pin, step_pin, ms0_pin, ms1_pin, resolution, direction):
        self.pi = pi
        self.dir_pin = dir_pin
        self.step_pin = step_pin
        self.ms0_pin = ms0_pin
        self.ms1_pin = ms1_pin
        self.resolution = resolution
        self.direction = direction
        self._setup_pins()
        self._set_resolution()
        self._set_direction()

    def _setup_pins(self):
        for pin in (self.dir_pin, self.step_pin, self.ms0_pin, self.ms1_pin):
            self.pi.set_mode(pin, pigpio.OUTPUT)

    def _set_resolution(self):
        self.pi.write(self.ms0_pin, 0)
        self.pi.write(self.ms1_pin, 0)
        if self.resolution == 'Half':
            self.pi.write(self.ms0_pin, 1)
        elif self.resolution == '1/4':
            self.pi.write(self.ms0_pin, 1)
            self.pi.write(self.ms1_pin, 1)

    def _set_direction(self):
        if self.direction == 'CCW':
            self.pi.write(self.dir_pin, 0)
        elif self.direction == 'CW':
            self.pi.write(self.dir_pin, 1)

    def set_pwm_frequency(self, frequency):
        self.pi.set_PWM_frequency(self.step_pin, frequency)

    def set_pwm_duty_cycle(self, duty_cycle):
        self.pi.set_PWM_dutycycle(self.step_pin, duty_cycle)

    def stop(self):
        self.pi.set_PWM_dutycycle(self.step_pin, 0)


class SensorManager:
    def __init__(self, i2c):
        try:
            self.accelerometer = adafruit_lsm303_accel.LSM303_Accel(i2c)
            self.magnetometer = adafruit_lsm303dlh_mag.LSM303DLH_Mag(i2c)
        except Exception as e:
            print(f"Error initializing sensors: {e}", file=sys.stderr)
            raise

    def get_acceleration(self):
        try:
            return self.accelerometer.acceleration
        except Exception as e:
            print(f"Error reading acceleration: {e}", file=sys.stderr)
            return None

    def get_magnetic_field(self):
        try:
            return self.magnetometer.magnetic
        except Exception as e:
            print(f"Error reading magnetic field: {e}", file=sys.stderr)
            return None

    def get_heading(self):
        try:
            mag_x, mag_y, _ = self.magnetometer.magnetic
            return self._heading_from_magnetometer(mag_x, mag_y)
        except Exception as e:
            print(f"Error reading heading: {e}", file=sys.stderr)
            return None

    def _heading_from_magnetometer(self, mag_x, mag_y):
        if mag_x is None or mag_y is None:
            return None
        angle = self._rad_to_deg(self._atan2(mag_y, mag_x))
        return angle + 360 if angle < 0 else angle

    def get_inclination(self):
        try:
            acc_x, acc_y, acc_z = self.accelerometer.acceleration
            return self._inclination_from_acceleration(acc_x, acc_y, acc_z)
        except Exception as e:
            print(f"Error reading inclination: {e}", file=sys.stderr)
            return None

    def _inclination_from_acceleration(self, acc_x, acc_y, acc_z):
        if acc_x is None or acc_y is None or acc_z is None:
            return None
        xz = self._rad_to_deg(self._atan2(acc_x, acc_z))
        yz = self._rad_to_deg(self._atan2(acc_y, acc_z))
        return (xz + 360 if xz < 0 else xz,
                yz + 360 if yz < 0 else yz)

    def _rad_to_deg(self, rad):
        return rad * 180.0 / 3.141592653589793

    def _atan2(self, y, x):
        return (x * y).atan2()


class ADCManager:
    def __init__(self, i2c, address=0x48, gain=1, vref=3.3):
        self.i2c = i2c
        self.address = address
        self.gain = gain
        self.vref = vref
        try:
            self.adc = Adafruit_ADS1x15.ADS1015(self.i2c, address=address)
        except Exception as e:
            print(f"Error initializing ADC at 0x{address:02X}: {e}", file=sys.stderr)
            raise

    def read_channel(self, channel):
        if not 0 <= channel <= 3:
            raise ValueError("Invalid ADC channel")
        try:
            return self.adc.read_adc(channel, gain=self.gain)
        except Exception as e:
            print(f"Error reading ADC channel {channel}: {e}", file=sys.stderr)
            return None

    def get_voltage(self, channel):
        raw = self.read_channel(channel)
        if raw is None:
            return None
        return raw * (self.vref / 32768.0)


def main():
    global _pi

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        _pi = pigpio.pi()
        if not _pi.connected:
            print("Failed to connect to pigpio daemon. Is pigpiod running?", file=sys.stderr)
            sys.exit(1)

        i2c = busio.I2C(board.SCL, board.SDA)
        motor_controller = MotorController(_pi, MOTOR_DIR_PIN, MOTOR_STEP_PIN,
                                           MOTOR_MS0_PIN, MOTOR_MS1_PIN,
                                           MOTOR_RESOLUTION, MOTOR_DIRECTION)
        sensor_manager = SensorManager(i2c)
        adc_manager = ADCManager(i2c, address=0x48, gain=ADC_GAIN, vref=ADC_VREF)

        motor_controller.set_pwm_frequency(PWM_FREQUENCY)

        while _running:
            voltage = adc_manager.get_voltage(ADC_CHANNEL)
            if voltage is not None:
                duty_cycle = int((voltage / ADC_VREF) * 255)
                duty_cycle = max(0, min(255, duty_cycle))
                motor_controller.set_pwm_duty_cycle(duty_cycle)

            acc = sensor_manager.get_acceleration()
            mag = sensor_manager.get_magnetic_field()
            heading = sensor_manager.get_heading()
            inclination = sensor_manager.get_inclination()

            if acc is not None:
                print(f"Acceleration: x={acc[0]:.3f}, y={acc[1]:.3f}, z={acc[2]:.3f} m/s^2")
            else:
                print("Acceleration: unavailable")

            if mag is not None:
                print(f"Magnetic Field: x={mag[0]:.3f}, y={mag[1]:.3f}, z={mag[2]:.3f} gauss")
            else:
                print("Magnetic Field: unavailable")

            if heading is not None:
                print(f"Heading: {heading:.2f} degrees")
            else:
                print("Heading: unavailable")

            if inclination is not None:
                print(f"XZ angle: {inclination[0]:.2f} degrees, YZ angle: {inclination[1]:.2f} degrees")
            else:
                print("Inclination: unavailable")

            time.sleep(LOOP_DELAY)

    except Exception as e:
        print(f"Fatal error: {e}", file=sys.stderr)
    finally:
        if _pi is not None and _pi.connected:
            _pi.set_PWM_dutycycle(MOTOR_STEP_PIN, 0)
            _pi.stop()
        print("Program terminated gracefully.")


if __name__ == "__main__":
    main()

