    def __init__(self, sensor_id, sensor_type, threshold, sample_rate, gpio_pins, channels, spi_speed, log_queue):
        self.sensor_id = sensor_id
        self.sensor_type = sensor_type
        self.threshold = threshold
        self.sample_rate = sample_rate
        self.gpio_pins = gpio_pins
        self.channels = channels
        self.spi_speed = spi_speed
        self.log_queue = log_queue
        self.spi = None
        self.gpio_initialized = False
        self.running = False
        self.event = threading.Event()

        if self.sensor_type == "digital":
            self.read_function = self.read_digital
        elif self.sensor_type == "analog":
            self.read_function = self.read_analog
        else:
            raise ValueError(f"Invalid sensor type: {sensor_type}")

        self.setup_gpio()
        self.setup_spi()

    def setup_gpio(self):
        """Initialize GPIO for digital sensors."""
        if self.sensor_type == "digital":
            if self.gpio_pins:
                try:
                    GPIO.setmode(GPIO.BCM)
                    GPIO.setwarnings(False)
                    for pin in self.gpio_pins:
                        GPIO.setup(pin, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
                    self.gpio_initialized = True
                    logging.info(f"Digital sensor {self.sensor_id}: GPIO pins {self.gpio_pins} initialized.")
                except Exception as e:
                    logging.error(f"Error initializing GPIO for digital sensor {self.sensor_id}: {e}")
                    raise
            else:
                logging.warning(f"Digital sensor {self.sensor_id}: No GPIO pins specified. Sensor disabled.")
                self.running = False

    def setup_spi(self):
        """Initialize SPI for analog sensors via MCP3008."""
        if self.sensor_type == "analog":
            try:
                self.spi = spidev.SpiDev()
                self.spi.open(0, 0)
                self.spi.max_speed_hz = self.spi_speed
                self.spi.mode = 0
                logging.info(f"Analog sensor {self.sensor_id}: SPI initialized (bus 0, device 0, {self.spi_speed} Hz).")
            except Exception as e:
                logging.error(f"Error initializing SPI for analog sensor {self.sensor_id}: {e}")
                raise
        else:
            if self.spi:
                self.spi.close()
                self.spi = None

    def read_digital(self):
        """Read digital sound level from GPIO pin."""
        try:
            if self.gpio_initialized:
                pin = self.gpio_pins[0]
                value = GPIO.input(pin)
                return value
            else:
                return 0
        except Exception as e:
            logging.error(f"Error reading digital sensor {self.sensor_id}: {e}")
            return 0

    def read_analog(self):
        """Read analog sound level from MCP3008 ADC channel."""
        try:
            if self.spi:
                channel = self.channels[0]
                # MCP3008 single-ended read: start bit (1), single-ended mode (1), channel bits (3), then dummy byte
                cmd = 0b11000000 | (channel << 3)
                resp = self.spi.xfer2([cmd, 0x00, 0x00])
                adc_value = ((resp[1] & 0x03) << 8) | resp[2]
                return adc_value
            else:
                return 0
        except Exception as e:
            logging.error(f"Error reading analog sensor {self.sensor_id}: {e}")
            return 0

    def run(self):
        """Main loop: detect sound events, debounce, log."""
        self.running = True
        self.event.set()
        logging.info(f"Sound sensor {self.sensor_id} started.")

        try:
            while self.running and not self.event.is_set():
                try:
                    sound_level = self.read_function()
                    if sound_level >= self.threshold:
                        logging.info(f"Sound event detected by sensor {self.sensor_id}: value={sound_level}")
                        self.log_queue.put({"sensor_id": self.sensor_id, "event_type": "sound_detected", "value": sound_level})
                        time.sleep(0.1)  # Debounce
                except Exception as e:
                    logging.error(f"Error reading sensor {self.sensor_id}: {e}")
                time.sleep(1 / self.sample_rate)
        except KeyboardInterrupt:
            logging.info(f"Sound sensor {self.sensor_id} stopped by user.")
        finally:
            self.cleanup()

    def stop(self):
        """Signal the main loop to stop."""
        self.running = False
        self.event.set()

    def cleanup(self):
        """Release resources."""
        if self.sensor_type == "digital" and self.gpio_initialized:
            try:
                GPIO.cleanup()
                logging.info(f"Digital sensor {self.sensor_id}: GPIO cleaned up.")
            except Exception as e:
                logging.error(f"Error cleaning up GPIO for digital sensor {self.sensor_id}: {e}")
        if self.spi:
            try:
                self.spi.close()
                logging.info(f"Analog sensor {self.sensor_id}: SPI closed.")
            except Exception as e:
                logging.error(f"Error closing SPI for analog sensor {self.sensor_id}: {e}")


def main():
    parser = argparse.ArgumentParser(description="Sound sensor data logger for Raspberry Pi.")
    parser.add_argument("--sensor_type", required=True, choices=["digital", "analog"], help="Sensor type (digital or analog).")
    parser.add_argument("--threshold", type=int, required=True, help="Sound level threshold (ADC value for analog, GPIO value for digital).")
    parser.add_argument("--sample_rate", type=int, required=True, help="Sampling rate in Hz.")
    parser.add_argument("--log_file", type=str, required=True, help="Path to log file.")
    parser.add_argument("--gpio_pins", nargs='+', type=int, help="GPIO pins for digital sensor (list of ints).")
    parser.add_argument("--channels", nargs='+', type=int, help="MCP3008 ADC channels for analog sensor (list of ints).")
    parser.add_argument("--spi_speed", type=int, default=1000000, help="SPI speed in Hz (default: 1 MHz).")
    parser.add_argument("--sensor_ids", nargs='+', type=str, help="Unique sensor IDs (list of strings).")

    args = parser.parse_args()

    logging.basicConfig(filename=args.log_file, level=logging.INFO,
                        format='%(asctime)s - %(levelname)s - %(message)s')
    logging.info("Starting sound sensor data logger.")

    log_queue = queue.Queue()
    sensors = []

    try:
        if args.sensor_type == "digital":
            if args.gpio_pins:
                for i, sensor_id in enumerate(args.sensor_ids):
                    sensor = SoundSensor(sensor_id, args.sensor_type, args.threshold, args.sample_rate, args.gpio_pins, [], args.spi_speed, log_queue)
                    sensors.append(sensor)
                    sensors[i].start()
            else:
                logging.warning("No GPIO pins specified for digital sensor. No sensors started.")
        elif args.sensor_type == "analog":
            if args.channels:
                for i, sensor_id in enumerate(args.sensor_ids):
                    sensor = SoundSensor(sensor_id, args.sensor_type, args.threshold, args.sample_rate, [], args.channels, args.spi_speed, log_queue)
                    sensors.append(sensor)
                    sensors[i].start()
            else:
                logging.warning("No ADC channels specified for analog sensor. No sensors started.")
        else:
            logging.error("Invalid sensor type. Use 'digital' or 'analog'.")
            sys.exit(1)

        for sensor in sensors:
            sensor.event.wait()

    except KeyboardInterrupt:
        logging.info("Exiting program.")
    finally:
        for sensor in sensors:
            sensor.stop()
        for sensor in sensors:
            sensor.join(timeout=2.0)
        logging.info("Program finished.")


if __name__ == "__main__":
    main()

