import time
import board
import busio
import adafruit_ads1x15.ads1115 as ADS
from adafruit_ads1x15.analog_in import AnalogIn

# Constants
I2C_ADDRESS = 0x48
ADC_GAIN = 1
READ_INTERVAL_SECONDS = 0.5
NUM_CHANNELS = 4


def initialize_adc():
    """Initialize I2C bus and ADS1115 ADC. Returns (i2c, adc) or exits on failure."""
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
    except Exception as exc:
        print(f"Error initializing I2C bus: {exc}")
        return None, None

    try:
        adc = ADS.ADS1115(i2c, address=I2C_ADDRESS)
        adc.gain = ADC_GAIN
    except Exception as exc:
        print(f"Error initializing ADS1115 at 0x{I2C_ADDRESS:02X}: {exc}")
        return None, None

    return i2c, adc


def read_all_channels(adc):
    """Read all four single-ended channels. Returns list of AnalogIn or None on error."""
    values = []
    for ch in range(NUM_CHANNELS):
        try:
            pin = getattr(ADS, f"P{ch}")
            values.append(AnalogIn(adc, pin))
        except Exception as exc:
            print(f"Error reading channel {ch}: {exc}")
            return None
    return values


def print_header():
    """Print the table header."""
    print("| {0:>6} | {1:>6} | {2:>6} | {3:>6} |".format("A0", "A1", "A2", "A3"))
    print("-" * 37)


def format_row(values):
    """Format a row of channel values."""
    return "| {0:>6} | {1:>6} | {2:>6} | {3:>6} |".format(*values)


def main():
    i2c, adc = initialize_adc()
    if i2c is None or adc is None:
        return

    print("Reading ADS1115 channels A0-A3. Press Ctrl-C to stop.")
    print_header()

    try:
        while True:
            values = read_all_channels(adc)
            if values is None:
                print("I2C bus error during read; retrying next cycle.")
            else:
                print(format_row(values))
            time.sleep(READ_INTERVAL_SECONDS)
    except KeyboardInterrupt:
        print("\nProgram stopped by user.")
    finally:
        print("Exiting.")


if __name__ == "__main__":
    main()

