import time
import signal
import sys
import board
import busio
import adafruit_max30102

LOG_FILE = 'heart_rate_log.txt'
SAMPLE_INTERVAL = 1.0
WINDOW_SECONDS = 4.0

_running = True

def _handle_sigint(signum, frame):
    global _running
    _running = False

def _int_or_none(value):
    if isinstance(value, int):
        return int(value)
    if isinstance(value, _AdaValue):
        return int(value.value)
    return None

def _format_value(value, unit):
    if value is None:
        return 'N/A'
    if isinstance(value, _AdaValue):
        return f'{int(value.value):.2f}'
    return f'{value:.2f}'

def _log_reading(log_file, timestamp, heart_rate, spo2):
    log_file.write(f'{timestamp} - Heart Rate: {heart_rate} bpm, SpO2: {spo2} %\n')
    log_file.flush()

def main():
    global _running
    signal.signal(signal.SIGINT, _handle_sigint)

    i2c = None
    sensor = None
    log_file = None

    try:
        i2c = busio.I2C(board.SCL, board.SDA)
        sensor = adafruit_max30102.MAX30102(i2c)
        sensor.setup_sensor()
        time.sleep(1)

        log_file = open(LOG_FILE, 'a')
        print(f'MAX30102 initialized at I2C 0x57. Logging to {LOG_FILE}.')

        while _running:
            try:
                red = sensor.get_red()
                ir = sensor.get_ir()
                part_id = sensor.get_part_id()
                timestamp = time.strftime('%Y-%m-%dT%H:%M:%S')

                ir_samples = []
                red_samples = []
                start_time = time.monotonic()
                while time.monotonic() - start_time < WINDOW_SECONDS and _running:
                    try:
                        red_samples.append(_int_or_none(sensor.get_red()))
                        ir_samples.append(_int_or_none(sensor.get_ir()))
                    except OSError as e:
                        print(f'I2C read error during peak detection: {e}')
                        break
                    time.sleep(0.01)

                if not ir_samples or not red_samples:
                    print('No IR samples collected; skipping heart-rate estimate.')
                    continue

                ir_count = sum(1 for s in ir_samples if s > 0)
                red_count = sum(1 for s in red_samples if s > 0)
                if red_count == 0:
                    heart_rate = 0
                else:
                    heart_rate = max(0, min(ir_count / (red_count + 1e-9) * 60, 220))

                spo2 = _int_or_none(sensor.get_spo2())
                _log_reading(log_file, timestamp, heart_rate, spo2)
                print(f'Timestamp: {timestamp}, Heart Rate: {heart_rate} bpm, SpO2: {spo2} %')

            except OSError as e:
                print(f'I2C bus error: {e}')
            except Exception as e:
                print(f'Unexpected error: {e}')

            time.sleep(SAMPLE_INTERVAL)

    except ValueError as e:
        print(f'Sensor not found at address 0x57: {e}')
    except OSError as e:
        print(f'I2C bus error: {e}')
    except Exception as e:
        print(f'Fatal error: {e}')
    finally:
        if log_file:
            log_file.close()
        if sensor:
            try:
                sensor.cleanup()
            except Exception:
                pass
        print('Resources cleaned up. Exiting.')

if __name__ == '__main__':
    main()

