import spidev
import time
import datetime
import os
import json
import signal
import sys
from gpiozero import OutputDevice

CONFIG_FILE = "config.json"
LOG_FILE = os.path.join(os.path.expanduser("~"), "logs", "industrial_air_quality.log")

running = True

def signal_handler(signum, frame):
    global running
    running = False

def load_config(config_file):
    try:
        with open(config_file, "r") as f:
            config = json.load(f)
        required = ["mq2_channel", "mq7_channel", "mq135_channel",
                    "mq2_warning", "mq2_critical", "mq7_warning",
                    "mq7_critical", "mq135_warning", "mq135_critical",
                    "actuator_pin"]
        for key in required:
            if key not in config:
                raise KeyError(f"Missing required config key: {key}")
        return config
    except FileNotFoundError:
        print(f"Error: Configuration file not found: {config_file}")
        sys.exit(1)
    except json.JSONDecodeError as e:
        print(f"Error: Invalid JSON in configuration file: {e}")
        sys.exit(1)
    except KeyError as e:
        print(f"Error: Missing required config key: {e}")
        sys.exit(1)

def read_mcp3008(spi, channel):
    if not 0 <= channel <= 7:
        raise ValueError("MCP3008 channel must be 0-7")
    try:
        adc = spi.xfer2([0x01, (0x08 | channel << 4), 0x00])
        data = ((adc[1] & 0x03) << 8) | adc[2]
        return data
    except spidev.SpiDevError as e:
        print(f"SPI communication error on channel {channel}: {e}")
        return None

def convert_to_voltage(adc_value, vref=3.3, rl=10000):
    if adc_value is None:
        return None
    return (adc_value / 1023.0) * vref * (rl / (rl + vref))

def log_data(timestamp, mq2_voltage, mq7_voltage, mq135_voltage, voltages):
    try:
        log_file_dir = os.path.dirname(LOG_FILE)
        if log_file_dir and not os.path.exists(log_file_dir):
            os.makedirs(log_file_dir, exist_ok=True)
        with open(LOG_FILE, "a") as f:
            f.write(f"{timestamp},{mq2_voltage},{mq7_voltage},{mq135_voltage},{voltages}\n")
    except IOError as e:
        print(f"Error writing to log file: {e}")

def check_thresholds(mq2_voltage, mq7_voltage, mq135_voltage, config):
    actuator = None
    try:
        actuator = OutputDevice(config["actuator_pin"])
    except Exception as e:
        print(f"Error initializing GPIO actuator on pin {config['actuator_pin']}: {e}")
        return

    mq2_crit = config["mq2_critical"]
    mq7_crit = config["mq7_critical"]
    mq135_crit = config["mq135_critical"]

    if mq2_voltage is not None and mq2_voltage > mq2_crit:
        print(f"Critical: MQ-2 sensor voltage: {mq2_voltage:.3f}V exceeds critical threshold: {mq2_crit:.3f}V")
        actuator.on()
    elif mq2_voltage is not None and mq2_voltage > mq2_crit / 2:
        print(f"Warning: MQ-2 sensor voltage: {mq2_voltage:.3f}V exceeds warning threshold: {mq2_crit / 2:.3f}V")
        actuator.on()
    elif mq2_voltage is not None and mq2_voltage < mq2_crit / 2:
        actuator.off()

    if mq7_voltage is not None and mq7_voltage > mq7_crit:
        print(f"Critical: MQ-7 sensor voltage: {mq7_voltage:.3f}V exceeds critical threshold: {mq7_crit:.3f}V")
        actuator.on()
    elif mq7_voltage is not None and mq7_voltage > mq7_crit / 2:
        print(f"Warning: MQ-7 sensor voltage: {mq7_voltage:.3f}V exceeds warning threshold: {mq7_crit / 2:.3f}V")
        actuator.on()
    elif mq7_voltage is not None and mq7_voltage < mq7_crit / 2:
        actuator.off()

    if mq135_voltage is not None and mq135_voltage > mq135_crit:
        print(f"Critical: MQ-135 sensor voltage: {mq135_voltage:.3f}V exceeds critical threshold: {mq135_crit:.3f}V")
        actuator.on()
    elif mq135_voltage is not None and mq135_voltage > mq135_crit / 2:
        print(f"Warning: MQ-135 sensor voltage: {mq135_voltage:.3f}V exceeds warning threshold: {mq135_crit / 2:.3f}V")
        actuator.on()
    elif mq135_voltage is not None and mq135_voltage < mq135_crit / 2:
        actuator.off()

    return actuator

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    config = load_config(CONFIG_FILE)

    spi = None
    actuator = None

    try:
        spi = spidev.SpiDev()
        spi.open(0, 0)
        spi.max_speed_hz = 1000000
        spi.mode = 0

        while running:
            mq2_channel = config["mq2_channel"]
            mq7_channel = config["mq7_channel"]
            mq135_channel = config["mq135_channel"]

            mq2_voltage = convert_to_voltage(read_mcp3008(spi, mq2_channel))
            mq7_voltage = convert_to_voltage(read_mcp3008(spi, mq7_channel))
            mq135_voltage = convert_to_voltage(read_mcp3008(spi, mq135_channel))

            voltages = convert_to_voltage(None, vref=3.3, rl=10000)

            timestamp = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
            log_data(timestamp, mq2_voltage, mq7_voltage, mq135_voltage, voltages)

            check_thresholds(mq2_voltage, mq7_voltage, mq135_voltage, config)

            time.sleep(5)

    except spidev.SpiDevError as e:
        print(f"SPI communication error: {e}")
    except IOError as e:
        print(f"File I/O error: {e}")
    except KeyboardInterrupt:
        print("Program terminated by user.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        if actuator is not None:
            try:
                actuator.off()
                actuator.close()
            except Exception:
                pass
        if spi is not None:
            try:
                spi.close()
            except Exception:
                pass
        print("Resources cleaned up. Exiting.")

if __name__ == "__main__":
    main()

