        return None

def capture_image(camera):
    try:
        buffer = io.BytesIO()
        camera.capture_file(buffer, format='jpeg')
        buffer.seek(0)
        return Image.open(buffer)
    except Exception as e:
        logging.error(f"Error capturing image: {e}")
        return None

def detect_bird(image, model_path):
