        logging.error(f"Failed to initialize camera: {e}")
        sys.exit(1)

    led_pin = config.get('gpio_led_pin')
    if led_pin is not None:
        try:
            from gpiozero import LED
            led = LED(led_pin)
            led_pin = led
            logging.info(f"LED initialized on GPIO pin {led_pin}.")
        except Exception as e:
            logging.error(f"Failed to initialize LED on pin {led_pin}: {e}")
            led_pin = None

    door_config = config.get('gpio_door_control')
    if door_config:
        try:
            door_device = OutputDevice(door_config)
            logging.info(f"Feeder door control initialized on pin {door_config}.")
        except Exception as e:
            logging.error(f"Failed to initialize feeder door control on pin {door_config}: {e}")
            door_device = None

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        while True:
            image = capture_image(camera)
            if image:
                bird_detected = detect_bird(image, config.get('model_path', 'model.h5'))
                if bird_detected is not None:
                    if bird_detected > 0.7:
                        indicate_bird(led_pin, duration=1.0)
                        control_feeder(door_device, "open")
                    else:
                        control_feeder(door_device, "close")
            time.sleep(0.1)
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        cleanup(camera, led_pin, door_device)

