import io
import time
import json
import threading
import queue
import signal
import sys
import RPi.GPIO as GPIO
from picamera2 import Picamera2
from gpiozero import LED

class CameraHandler:
    def __init__(self, config_path):
        self.config = self.load_config(config_path)
        self.camera = None
        self.frame_queue = queue.Queue(maxsize=self.config['frame_buffer_size'])
        self.running = True
        self.led = None
        self.gpio_pin = self.config.get('gpio_pin')
        self.alert_duration = self.config.get('alert_duration', 2)
        self.warmup_time = self.config.get('warmup_time', 2)
        self.sleep_time = self.config.get('sleep_time', 0.1)
        self.motion_threshold = self.config.get('motion_threshold', 10)
        self.setup_gpio()
        self.setup_camera()

    def load_config(self, config_path):
        try:
            with open(config_path, 'r') as f:
                return json.load(f)
        except FileNotFoundError:
            print(f"Error: Config file not found at {config_path}")
            sys.exit(1)
        except json.JSONDecodeError as e:
            print(f"Error: Invalid JSON in config file: {e}")
            sys.exit(1)

    def setup_gpio(self):
        if self.gpio_pin is not None:
            try:
                self.led = LED(self.gpio_pin)
            except Exception as e:
                print(f"Error setting up GPIO pin {self.gpio_pin}: {e}")
                self.led = None

    def setup_camera(self):
        try:
            self.camera = Picamera2()
            config = self.camera.create_video_configuration(
                main={"size": (self.config['resolution_width'], self.config['resolution_height']), "format": "RGB888"},
                controls={"FrameRate": self.config['framerate']}
            )
            self.camera.configure(config)
            self.camera.start()
            time.sleep(self.warmup_time)
        except Exception as e:
            print(f"Error setting up camera: {e}")
            self.camera = None

    def capture_frames(self):
        if not self.camera:
            return
        try:
            while self.running:
                frame = self.camera.capture_array()
                if frame is None:
                    print("Warning: Captured empty frame")
                    time.sleep(self.sleep_time)
                    continue
                self.frame_queue.put(frame, timeout=1)
                time.sleep(self.sleep_time)
        except queue.Full:
            print("Warning: Frame queue is full, dropping frame")
        except Exception as e:
            print(f"Error capturing frames: {e}")
        finally:
            self.stop()

    def process_frames(self):
        try:
            while self.running:
                try:
                    frame = self.frame_queue.get(timeout=1)
                except queue.Empty:
                    continue
                self.process_frame(frame)
                self.frame_queue.task_done()
        except Exception as e:
            print(f"Error processing frames: {e}")
        finally:
            self.stop()

    def process_frame(self, frame):
        pass

    def trigger_alert(self):
        if self.led:
            try:
                self.led.on()
                timer = threading.Timer(self.alert_duration, self.led.off)
                timer.start()
            except Exception as e:
                print(f"Error triggering alert: {e}")

    def stop(self):
        self.running = False
        if self.led:
            try:
                self.led.off()
                self.led.close()
            except Exception:
                pass
        if self.camera:
            try:
                self.camera.stop()
            except Exception:
                pass
        GPIO.cleanup()

    def run(self):
        capture_thread = threading.Thread(target=self.capture_frames, daemon=True)
        process_thread = threading.Thread(target=self.process_frames, daemon=True)
        capture_thread.start()
        process_thread.start()
        try:
            while self.running:
                time.sleep(0.5)
        except KeyboardInterrupt:
            self.stop()
        capture_thread.join(timeout=2)
        process_thread.join(timeout=2)

def signal_handler(sig, frame):
    print("\nExiting program...")
    sys.exit(0)

if __name__ == "__main__":
    signal.signal(signal.SIGINT, signal_handler)
    config_path = "config.json"
    handler = CameraHandler(config_path)
    handler.run()

