import time
import signal
import sys
import random
import board
import busio
import adafruit_amg88xx
from gpiozero import Buzzer

# Constants
I2C_ADDRESS = 0x69
BUZZER_PIN = 17
TEMP_THRESHOLD = 30.0
POLL_INTERVAL = 0.1
BUZZER_DURATION = 1.0

# Global resources for cleanup
buzzer = None
i2c = None
thermal_sensor = None
running = True


def cleanup(signum=None, frame=None):
    """Release resources and exit cleanly."""
    global running, buzzer, i2c
    running = False
    if buzzer is not None:
        try:
            buzzer.off()
            buzzer.close()
        except Exception:
            pass
    if i2c is not None:
        try:
            i2c.deinit()
        except Exception:
            pass
    if signum is not None:
        sys.exit(0)


def detect_human(thermal_data):
    """Return True if any pixel exceeds the threshold."""
    if thermal_data is None or thermal_data.shape != (8, 8):
        return False
    return any(pixel > TEMP_THRESHOLD for pixel in thermal_data.flatten())


def trigger_alert(buzzer_device):
    """Sound the buzzer for BUZZER_DURATION seconds."""
    if buzzer_device is None:
        return
    try:
        buzzer_device.on()
        time.sleep(BUZZER_DURATION)
    except Exception as e:
        print(f"Buzzer error: {e}")
    finally:
        try:
            buzzer_device.off()
        except Exception:
            pass


def main():
    global buzzer, i2c, thermal_sensor

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    # Initialize buzzer
    try:
        buzzer = Buzzer(BUZZER_PIN)
    except Exception as e:
        print(f"Failed to initialize buzzer on GPIO{BUZZER_PIN}: {e}")
        sys.exit(1)

    # Initialize I2C and AMG8833
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
        thermal_sensor = adafruit_amg88xx.AMG88XX(i2c, addr=I2C_ADDRESS)
        print("AMG8833 thermal camera initialized.")
    except Exception as e:
        print(f"Failed to initialize AMG8833 at 0x{I2C_ADDRESS:02X}: {e}")
        print("Falling back to simulated thermal data.")
        thermal_sensor = None

    # Main loop
    while running:
        try:
            if thermal_sensor is not None:
                thermal_data = thermal_sensor.pixels
            else:
                # Simulate 8x8 thermal data (20-45°C)
                thermal_data = [
                    [random.uniform(20, 45) for _ in range(8)] for _ in range(8)
                ]

            if detect_human(thermal_data):
                print("ALERT: Human detected!")
                trigger_alert(buzzer)
            else:
                print("All clear.")

            time.sleep(POLL_INTERVAL)

        except Exception as e:
            print(f"Error in main loop: {e}")
            time.sleep(POLL_INTERVAL)

    cleanup()


if __name__ == "__main__":
    main()

