import sys
import time

from smbus2 import SMBus, i2c_msg
from gpiozero import Button

PCF8574_ADDR = 0x20
PCF8574_INT_PIN = 0x00
I2C_BUS = 1
DEBOUNCE_MS = 50

_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False


def read_proximity_sensors(bus):
    """Read the 8-bit state of the PCF8574 and print obstacle detections."""
    try:
        data = bus.read_byte(PCF8574_ADDR)
        for i in range(8):
            if (data >> i) & 0x01 == 0:
                print(f"Obstacle detected by sensor {i}")
    except OSError as e:
        print(f"I2C read error: {e}", file=sys.stderr)


def main():
    global _running

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    bus = None
    int_pin = None

    try:
        bus = SMBus(I2C_BUS)
    except OSError as e:
        print(f"Failed to open I2C bus {I2C_BUS}: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        int_pin = Button(17, pull_up=True, bounce_time=DEBOUNCE_MS / 1000.0)
        int_pin.when_pressed = read_proximity_sensors
    except Exception as e:
        print(f"Failed to configure GPIO17 interrupt: {e}", file=sys.stderr)
        bus.close()
        sys.exit(1)

    print("PCF8574 interrupt active-low detection running. Press Ctrl+C to exit.")

    try:
        while _running:
            time.sleep(1)
    finally:
        _running = False
        if int_pin is not None:
            int_pin.close()
        if bus is not None:
            bus.close()
        print("Resources cleaned up. Exiting.")


if __name__ == "__main__":
    main()

