import cv2
import numpy as np
import signal
import sys
import logging
from picamera2 import Picamera2

logging.basicConfig(level=logging.INFO, format='%(asctime)s [%(levelname)s] %(message)s')
logger = logging.getLogger(__name__)

running = True

def _signal_handler(signum, frame):
    global running
    logger.info('Received signal %s, shutting down...', signum)
    running = False

def initialize_camera(camera_num=0):
    """Initialize a Picamera2 instance with a 640x480 RGB888 preview stream at 30 fps."""
    try:
        picam2 = Picamera2(camera_num=camera_num)
        config = picam2.create_preview_configuration(
            main={'size': (640, 480), 'format': 'RGB888'},
            controls={'FrameDurationLimits': (33333, 33333)}
        )
        picam2.configure(config)
        picam2.start()
        logger.info('Camera %d initialized successfully.', camera_num)
        return picam2
    except Exception as e:
        logger.error('Failed to initialize camera %d: %s', camera_num, e)
        return None

def grab_frame(picam2):
    """Capture a single frame from a Picamera2 instance."""
    try:
        return picam2.capture_array()
    except Exception as e:
        logger.error('Frame capture failed on camera: %s', e)
        return None

def display_cameras(picam2_left, picam2_right):
    """Display concatenated camera frames until ESC is pressed or running becomes False."""
    global running
    window_name = 'Dual CSI Cameras'
    try:
        cv2.namedWindow(window_name, cv2.WINDOW_AUTOSIZE)
    except cv2.error as e:
        logger.error('Failed to create display window: %s', e)
        return

    try:
        while running:
            img_left = grab_frame(picam2_left)
            img_right = grab_frame(picam2_right)

            if img_left is None or img_right is None:
                logger.warning('One or both cameras returned None, retrying...')
                continue

            # Concatenate images side by side (height must match)
            try:
                height, width = img_left.shape[:2]
                if height != img_right.shape[0]:
                    raise ValueError(f'Left and right images have different heights: {height} vs {img_right.shape[0]}')
                combined = np.hstack((img_left, img_right))
            except Exception as e:
                logger.error('Failed to concatenate images: %s', e)
                continue

            # Check for ESC key or window close
            key = cv2.waitKey(30) & 0xFF
            if key == 27 or not cv2.getWindowProperty(window_name, cv2.WND_PROP_AUTOSIZE):
                logger.info('Exit condition triggered.')
                break

            cv2.imshow(window_name, combined)
    except Exception as e:
        logger.error('Display loop error: %s', e)
    finally:
        cv2.destroyAllWindows()

def release_resources(picam2_left, picam2_right):
    """Stop and close all cameras cleanly."""
    for name, cam in [('left', picam2_left), ('right', picam2_right)]:
        if cam is not None:
            try:
                cam.stop()
                logger.info('%s camera stopped.', name)
            except Exception as e:
                logger.error('Error stopping %s camera: %s', name, e)

def main():
    global running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    picam2_left = initialize_camera(0)
    picam2_right = initialize_camera(1)

    if picam2_left is None or picam2_right is None:
        logger.error('One or both cameras failed to initialize. Exiting.')
        release_resources(picam2_left, picam2_right)
        sys.exit(1)

    try:
        display_cameras(picam2_left, picam2_right)
    except KeyboardInterrupt:
        logger.info('KeyboardInterrupt received.')
    finally:
        release_resources(picam2_left, picam2_right)
        logger.info('Resources released. Exiting.')

if __name__ == '__main__':
    main()

