import queue
import signal
import sys
import threading
import time
from datetime import datetime
from pathlib import Path

import numpy as np
from picamera2 import Picamera2
from picamera2.encoders import H264Encoder
from picamera2.outputs import FfmpegOutput

try:
    import tflite_runtime.interpreter as tflite
except ImportError:
    try:
        import tensorflow.lite as tflite
    except ImportError:
        tflite = None


GESTURE_LABELS = {
    0: "Open Hand",
    1: "Closed Fist",
    2: "Pointing Up",
    3: "Pointing Down",
    4: "Peace Sign",
}

DEFAULT_MODEL = "gesture_model_quantized.tflite"
DEFAULT_THRESHOLD = 0.7
DEFAULT_INTERVAL = 2.0
DEFAULT_LOG_LEVEL = "INFO"
DEFAULT_CAMERA_RESOLUTION = "640x480"
DEFAULT_CAMERA_FRAMERATE = 30
DEFAULT_USER_ID = "default_user"


class CameraHandler:
    def __init__(self, resolution, framerate, stop_event):
        self.resolution = resolution
        self.framerate = framerate
        self.stop_event = stop_event
        self.picam2 = None
        self.encoder = None
        self.output = None
        self.lock = threading.Lock()
        self._init_camera()

    def _init_camera(self):
        try:
            self.picam2 = Picamera2()
            w, h = map(int, self.resolution.split("x"))
            config = self.picam2.create_video_configuration(
                main={"size": (w, h), "format": "RGB888"},
                controls={"FrameRate": self.framerate},
            )
            self.picam2.configure(config)
            self.encoder = H264Encoder()
            self.output = FfmpegOutput("/dev/null")
            self.picam2.start_recording(self.encoder, self.output)
            logging.info("Camera initialized successfully.")
        except Exception as e:
            logging.error(f"Failed to initialize camera: {e}")
            self.picam2 = None

    def capture_frame(self):
        if self.picam2 is None:
            return None
        with self.lock:
            try:
                return self.picam2.capture_array()
            except Exception as e:
                logging.error(f"Error capturing frame: {e}")
                return None

    def stop(self):
        if self.picam2:
            try:
                self.picam2.stop_recording()
            except Exception:
                pass
            try:
                self.picam2.close()
            except Exception:
                pass
            self.picam2 = None


class InferenceHandler:
    def __init__(self, model_path, threshold, interval, stop_event, user_id):
        self.model_path = model_path
        self.threshold = threshold
        self.interval = interval
        self.stop_event = stop_event
        self.user_id = user_id
        self.interpreter = None
        self.input_details = None
        self.output_details = None
        self.input_size = None
        self.is_coral = False
        self.load_model()

    def load_model(self):
        try:
            if tflite is None:
                raise RuntimeError("tflite_runtime not installed")
            if not Path(self.model_path).is_file():
                raise FileNotFoundError(f"Model file not found: {self.model_path}")
            self.interpreter = tflite.Interpreter(model_path=self.model_path)
            self.interpreter.allocate_tensors()
            self.input_details = self.interpreter.get_input_details()
            self.output_details = self.interpreter.get_output_details()
            self.input_size = self.input_details[0]["shape"][1]
            self.is_coral = False
            try:
                delegates = self.interpreter.get_delegates()
                if len(delegates) > 0 and delegates[0]["delegate_type"] == "libedgetpu":
                    logging.info("Using Coral USB Accelerator.")
                    self.interpreter.set_tensor_buffer_size(
                        self.input_details[0]["index"], 1024 * 1024
                    )
                    self.is_coral = True
            except Exception as e:
                logging.warning(f"Coral unavailable ({e}); falling back to CPU.")
        except Exception as e:
            logging.error(f"Error loading model: {e}")
            raise

    def preprocess_frame(self, frame):
        try:
            resized = np.resize(frame, (self.input_size, self.input_size, 3))
            normalized = (resized / 127.5) - 1.0
            return normalized
        except Exception as e:
            logging.error(f"Error preprocessing frame: {e}")
            return None

    def run_inference(self, frame):
        if frame is None:
            return None
        try:
            input_data = self.preprocess_frame(frame)
            if input_data is None:
                return None
            self.interpreter.set_tensor(
                self.input_details[0]["index"], input_data
            )
            self.interpreter.invoke()
            output_data = self.interpreter.get_tensor(
                self.output_details[0]["index"]
            )
            return output_data[0]
        except Exception as e:
            logging.error(f"Error running inference: {e}")
            return None

    def process_gesture(self, output_data):
        try:
            idx = int(np.argmax(output_data))
            if idx < 0 or idx >= len(GESTURE_LABELS):
                logging.warning(f"Invalid gesture index: {idx}")
                return None
            label = GESTURE_LABELS[idx]
            confidence = float(output_data[idx])
            if confidence > self.threshold and (
                time.time() - self.last_gesture_time > self.interval
            ):
                self.last_gesture_time = time.time()
                return label
            return None
        except Exception as e:
            logging.error(f"Error processing gesture: {e}")
            return None

    def get_state(self):
        return {
            "light": self.light,
            "temperature": self.temperature,
            "tv": self.tv,
        }

    def set_state(self, state):
        self.light = state["light"]
        self.temperature = state["temperature"]
        self.tv = state["tv"]

    def run(self):
        logging.info("Starting inference thread.")
        while not self.stop_event.is_set():
            try:
                frame = self.frame_queue.get(timeout=1)
                if frame is None:
                    continue
