                raise RuntimeError("Camera not initialised")
            # picamera2 capture_array returns a numpy array; convert to JPEG.
            import numpy as np
            from PIL import Image
            array = self.picam2.capture_array()
            if array is None:
                raise RuntimeError("capture_array returned None")
            img = Image.fromarray(array)
            buf = io.BytesIO()
            img.save(buf, format="JPEG", quality=90)
            return buf.getvalue()

    def get_object(self, classifier: Any) -> tuple[bytes, bool]:
        """Run detection on the latest frame; return (jpeg_bytes, detected)."""
        jpeg = self.get_frame()
        detected = bool(classifier.detect(jpeg))
        return jpeg, detected

    def get_object_with_basic_motion_detection(self) -> tuple[bytes, bool]:
        """Run motion detection + classifier detection; return (jpeg_bytes, detected)."""
        jpeg, motion_detected = self.get_motion_detection()
        detected = bool(self.classifier.detect(jpeg))
        return jpeg, detected

    def get_motion_detection(self) -> tuple[bytes, bool]:
        """Return (jpeg_bytes, bool) after applying basic motion heuristics."""
        jpeg, _ = self.get_frame()
        # Placeholder motion heuristic: simple frame differencing on the
        # raw numpy array (placeholder – real motion detection would use
        # picamera2's motion-detection capabilities or a dedicated module).
        import numpy as np
        prev_gray = None
        try:
            array = self.picam2.capture_array()
            if array is None:
                return (b"", False)
            if prev_gray is not None:
                diff = np.abs(array.astype(np.int16) - prev_gray.astype(np.int16))
                mean_diff = float(diff.mean())
                if mean_diff > 10.0:
                    return (b"", True)
            prev_gray = array
            return (jpeg, False)
        except Exception as exc:
            print(f"Motion detection error: {exc}", file=sys.stderr)
            return (b"", False)

    # -- lifecycle ----------------------------------------------------------
    def _init_camera(self) -> None:
        """Initialise picamera2 with a video configuration suitable for JPEG streaming."""
        try:
            self.picam2 = Picamera2()
            # Use a video configuration for continuous JPEG capture.
            video_config = self.picam2.create_video_configuration(
                main={"size": (640, 480), "format": "RGB888"},
                transform=self._get_transform(),
            )
            self.picam2.configure(video_config)
            self.picam2.start()
            self._started = True
        except Exception as exc:
            print(f"Camera initialisation failed: {exc}", file=sys.stderr)
            traceback.print_exc(file=sys.stderr)
            self.picam2 = None
            raise

    def _get_transform(self) -> Any:
        """Apply vertical flip via picamera2 transform options (no flip parameter)."""
        from libcamera import Transform
        return Transform(vflip=1)

    def stop(self) -> None:
        """Stop the camera and release resources."""
        with self._lock:
            if self.picam2 is not None:
                try:
                    self.picam2.stop()
                except Exception as exc:
                    print(f"Error stopping camera: {exc}", file=sys.stderr)
                finally:
                    self.picam2 = None
