def check_for_objects() -> None:
    """Background thread: detect objects and send email notifications."""
    last_email_time: float = 0.0
    while getattr(config, "running", True):
        try:
            if config.classifier_name == "motion_detector":
                jpeg, detected = _camera.get_object_with_basic_motion_detection()
            else:
                jpeg, detected = _camera.get_object(config.classifier)

            if detected and config.send_email_notifications:
                if (time.time() - last_email_time) >= int(config.email_send_interval):
                    last_email_time = time.time()
