        time.sleep(0.1)


def gen(camera: Camera) -> bytes:
    """Generator yielding JPEG frames for multipart streaming."""
    while getattr(config, "running", True):
        try:
            jpeg = camera.get_frame()
            yield (
                b"--frame\r\n"
                b"Content-Type: image/jpeg\r\n\r\n" + jpeg + b"\r\n\r\n"
            )
        except Exception as exc:
            print(f"Streaming error: {exc}", file=sys.stderr)
            traceback.print_exc(file=sys.stderr)
            time.sleep(0.5)


@app.route("/video_feed")
