import json
import logging
import os
import signal
import statistics
import sys
import time
from datetime import datetime

try:
    from gpiozero import OutputDevice, InputDevice
except Exception:
    OutputDevice = None
    InputDevice = None

DEFAULT_CONFIG = {
    "sensors": [
        {"trigger_pin": 17, "echo_pin": 18, "offset": 0.0, "max_distance": 200.0},
        {"trigger_pin": 22, "echo_pin": 23, "offset": 0.0, "max_distance": 200.0},
        {"trigger_pin": 24, "echo_pin": 25, "offset": 0.0, "max_distance": 200.0},
    ],
    "alert_threshold_low": 10.0,
    "alert_threshold_high": 180.0,
    "alert_repeat_delay": 60,
    "log_file": "water_level.log",
}

_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False


def load_config(config_file="config.json"):
    if not os.path.exists(config_file):
        logging.warning(f"Config file '{config_file}' not found; creating default.")
        try:
            with open(config_file, "w") as f:
                json.dump(DEFAULT_CONFIG, f, indent=2)
        except OSError as e:
            logging.error(f"Could not write default config: {e}")
        return dict(DEFAULT_CONFIG)
    try:
        with open(config_file, "r") as f:
            cfg = json.load(f)
    except (OSError, json.JSONDecodeError) as e:
        logging.error(f"Error loading config: {e}; using defaults.")
        return dict(DEFAULT_CONFIG)
    required = ["sensors", "alert_threshold_low", "alert_threshold_high", "alert_repeat_delay", "log_file"]
    for key in required:
        if key not in cfg:
            logging.error(f"Missing required config key: {key}; using default.")
            cfg[key] = DEFAULT_CONFIG[key]
    return cfg


def measure_distance(trigger_pin, echo_pin, offset, max_distance):
    if OutputDevice is None or InputDevice is None:
        logging.error("gpiozero not available; cannot measure distance.")
        return None
    try:
        trigger = OutputDevice(trigger_pin)
        echo = InputDevice(echo_pin)
    except Exception as e:
        logging.error(f"Failed to init GPIO pins {trigger_pin}/{echo_pin}: {e}")
        return None
    try:
        trigger.off()
        time.sleep(0.00005)
        trigger.on()
        time.sleep(0.00001)
        trigger.off()

        timeout = time.time() + 0.05
        while echo.value == 0:
            if time.time() > timeout:
                logging.warning(f"Timeout waiting for echo rising edge on pin {echo_pin}")
                return None
        pulse_start = time.time()

        timeout = time.time() + 0.05
        while echo.value == 1:
            if time.time() > timeout:
                logging.warning(f"Timeout waiting for echo falling edge on pin {echo_pin}")
                return None
        pulse_end = time.time()

        pulse_duration = pulse_end - pulse_start
        distance = (pulse_duration * 34300) / 2
        distance += offset
        if distance > max_distance:
            logging.warning(f"Distance {distance:.2f} out of range [0, {max_distance}] on pin {echo_pin}; clamping.")
            distance = max(0.0, min(distance, max_distance))
        return distance
    except Exception as e:
        logging.error(f"Error measuring distance on trigger {trigger_pin}, echo {echo_pin}: {e}")
        return None
    finally:
        try:
            trigger.close()
        except Exception:
            pass
        try:
            echo.close()
        except Exception:
            pass


def get_median_water_level(sensor_data):
    valid = [d for d in sensor_data if d is not None]
    if not valid:
        return None
    return statistics.median(valid)


def check_alerts(water_levels, alert_threshold_low, alert_threshold_high, alert_repeat_delay, last_alerts):
    now = time.time()
    new_alerts = []
    for wl in water_levels:
        if wl is None:
            continue
        if wl < alert_threshold_low and (now - last_alerts.get("low", 0)) > alert_repeat_delay:
            new_alerts.append("low")
        if wl > alert_threshold_high and (now - last_alerts.get("high", 0)) > alert_repeat_delay:
            new_alerts.append("high")
    return new_alerts, {k: now for k in new_alerts}


def log_data(log_file, message):
    try:
        with open(log_file, "a") as f:
            f.write(message + "\n")
    except OSError as e:
        logging.error(f"Error writing to log file '{log_file}': {e}")


def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    config = load_config()
    log_file = config["log_file"]
    logging.basicConfig(
        filename=log_file,
        level=logging.INFO,
        format="%(asctime)s - %(levelname)s - %(message)s",
    )
    logging.info("Water level monitoring system started.")

    sensors = []
    for item in config["sensors"]:
        sensors.append({
            "trigger_pin": item["trigger_pin"],
            "echo_pin": item["echo_pin"],
            "offset": item["offset"],
            "max_distance": item["max_distance"],
        })

    alert_threshold_low = config["alert_threshold_low"]
    alert_threshold_high = config["alert_threshold_high"]
    alert_repeat_delay = config["alert_repeat_delay"]
    last_alerts = {}

    if OutputDevice is None and InputDevice is None:
        logging.error("gpiozero not available; exiting.")
        logging.info("Water level monitoring system stopped.")
        return

    try:
        while _running:
            sensor_data = []
            for sensor in sensors:
                dist = measure_distance(sensor["trigger_pin"], sensor["echo_pin"], sensor["offset"], sensor["max_distance"])
                sensor_data.append(dist)

            water_levels = []
            for i, d in enumerate(sensor_data):
                if d is not None:
                    water_levels.append(max(sensor["max_distance"], 0.0) - d)
                else:
                    logging.warning(f"Sensor {i} failed; excluding from averaging.")

            median_level = get_median_water_level(water_levels)
            if median_level is not None:
                logging.info(f"Median water level: {median_level:.2f} cm")
                logging.info(f"Sensor readings: {[f'{d:.2f}' if d is not None else 'N/A' for d in sensor_data]}")
                logging.info(f"Alert thresholds: low={alert_threshold_low}, high={alert_threshold_high}")
                alerts, last_alerts = check_alerts(
                    [median_level], alert_threshold_low, alert_threshold_high, alert_repeat_delay, last_alerts
                )
                for a in alerts:
                    logging.warning(f"ALERT: Water level {median_level:.2f} cm exceeds {a} threshold.")
            else:
                logging.error("No valid sensor readings; skipping alert check.")

            for _ in range(50):
                if not _running:
                    break
                time.sleep(0.1)
    except Exception as e:
        logging.error(f"Unexpected error in main loop: {e}")
    finally:
        logging.info("Water level monitoring system stopped.")


if __name__ == "__main__":
    main()

