#!/usr/bin/env python3

import speech_recognition as sr
import time
import datetime
import os
import signal
import sys
import random

try:
    import RPi.GPIO as GPIO
    GPIO_AVAILABLE = True
except (ImportError, RuntimeError):
    GPIO_AVAILABLE = False
    print("RPi.GPIO not available. Running in simulation mode.")

try:
    import board
    import adafruit_dht
    DHT_AVAILABLE = True
except (ImportError, NotImplementedError):
    DHT_AVAILABLE = False
    print("adafruit_dht not available. Running in simulation mode.")

try:
    from picamera2 import Picamera2
    CAMERA_AVAILABLE = True
except (ImportError, NotImplementedError):
    CAMERA_AVAILABLE = False
    print("picamera2 not available. Running in simulation mode.")

# Configuration
LIGHT_PIN = 17
DHT_PIN = 4
IMAGE_RESOLUTION = (640, 480)
WAKE_WORD = "Greenhouse"

# Global state
lights_on = False
running = True

def signal_handler(sig, frame):
    global running
    print("\nShutting down gracefully...")
    running = False

def initialize_gpio():
    if GPIO_AVAILABLE:
        try:
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(LIGHT_PIN, GPIO.OUT, initial=GPIO.LOW)
            print("GPIO initialized successfully.")
        except Exception as e:
            print(f"GPIO initialization failed: {e}. Falling back to simulation mode.")
            GPIO_AVAILABLE = False
    else:
        print("GPIO not available. Running in simulation mode.")

def turn_lights_on():
    global lights_on
    if GPIO_AVAILABLE:
        try:
            GPIO.output(LIGHT_PIN, GPIO.HIGH)
            lights_on = True
            print("Lights turned ON")
        except Exception as e:
            print(f"Error turning lights ON: {e}")
    else:
        lights_on = True
        print("Lights turned ON (simulation)")

def turn_lights_off():
    global lights_on
    if GPIO_AVAILABLE:
        try:
            GPIO.output(LIGHT_PIN, GPIO.LOW)
            lights_on = False
            print("Lights turned OFF")
        except Exception as e:
            print(f"Error turning lights OFF: {e}")
    else:
        lights_on = False
        print("Lights turned OFF (simulation)")

def read_temperature():
    if DHT_AVAILABLE:
        try:
            dht_device = adafruit_dht.DHT11(board.D4)
            temperature = dht_device.temperature
            dht_device.exit()
            if temperature is not None:
                return temperature
            else:
                print("DHT11 returned None. Using simulated temperature.")
                return random.uniform(15, 35)
        except RuntimeError as e:
            print(f"DHT11 read error: {e}. Using simulated temperature.")
            return random.uniform(15, 35)
        except Exception as e:
            print(f"Unexpected DHT11 error: {e}. Using simulated temperature.")
            return random.uniform(15, 35)
    else:
        print("DHT11 not available. Using simulated temperature.")
        return random.uniform(15, 35)

def capture_image():
    if CAMERA_AVAILABLE:
        try:
            picam2 = Picamera2()
            config = picam2.create_preview_configuration(main={"format": 'XRGB8888', "size": IMAGE_RESOLUTION})
            picam2.configure(config)
            picam2.start()
            time.sleep(2)
            picam2.capture_file(f"greenhouse_{datetime.datetime.now().strftime('%Y%m%d_%H%M%S')}.jpg")
            picam2.stop()
            picam2.close()
            print("Image captured successfully.")
        except Exception as e:
            print(f"Error capturing image: {e}. Using simulated image.")
            try:
                with open("greenhouse.txt", "w") as f:
                    f.write("Simulated Image")
                print("Simulated image file created.")
            except Exception as e2:
                print(f"Error creating simulated image file: {e2}")
    else:
        try:
            with open("greenhouse.txt", "w") as f:
                f.write("Simulated Image")
            print("Simulated image file created.")
        except Exception as e:
            print(f"Error creating simulated image file: {e}")

def recognize_voice_command():
    r = sr.Recognizer()
    try:
        with sr.Microphone() as source:
            print("Listening for command...")
            r.adjust_for_ambient_noise(source, duration=0.5)
            audio = r.listen(source, timeout=5)
    except sr.WaitTimeoutError:
        print("No speech detected within timeout.")
        return None
    except Exception as e:
        print(f"Microphone error: {e}")
        return None

    try:
        command = r.recognize_google(audio).lower()
        print(f"Recognized: {command}")
        return command
    except sr.UnknownValueError:
        print("Could not understand audio")
        return None
    except sr.RequestError as e:
        print(f"Could not request results from Google Web Speech API; {e}")
        return None

def main():
    global lights_on, running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    initialize_gpio()

    try:
        while running:
            command = recognize_voice_command()
            if command:
                if WAKE_WORD in command:
                    parts = command.split()
                    if len(parts) >= 2:
                        if parts[1] == "turn on the lights":
                            turn_lights_on()
                        elif parts[1] == "turn off the lights":
                            turn_lights_off()
                        elif parts[1] == "what is the temperature":
                            temperature = read_temperature()
