    global running
    print("\nShutting down gracefully...")
    running = False

def initialize_gpio():
    if GPIO_AVAILABLE:
        try:
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(LIGHT_PIN, GPIO.OUT, initial=GPIO.LOW)
