            GPIO_AVAILABLE = False
    else:
        print("GPIO not available. Running in simulation mode.")

def turn_lights_on():
    global lights_on
    if GPIO_AVAILABLE:
        try:
            GPIO.output(LIGHT_PIN, GPIO.HIGH)
            lights_on = True
            print("Lights turned ON")
        except Exception as e:
            print(f"Error turning lights ON: {e}")
