import signal
import sys
import time

try:
    from gpiozero import Button, OutputDevice
    from gpiozero.exc import GPIOZeroError, DeviceClosed
except ImportError:
    print("Error: gpiozero is not installed. Install with: sudo apt install python3-gpiozero", file=sys.stderr)
    sys.exit(1)

# BCM pin assignments
INPUT_PINS = [4, 5, 6]
OUTPUT_PINS = [23, 24]
POLL_INTERVAL = 0.05  # seconds

# Internal state tracking
_gpio_available = {pin: False for pin in OUTPUT_PINS}
_output_states = {pin: False for pin in OUTPUT_PINS}
_running = True


def _cleanup():
    """Release all GPIO resources safely."""
    global _gpio_available
    for pin in OUTPUT_PINS:
        try:
            dev = _gpio_available.get(pin)
            if dev is not None and not dev.closed:
                dev.close()
        except DeviceClosed:
            pass
        except Exception as exc:
            print(f"Warning: error closing GPIO {pin}: {exc}", file=sys.stderr)
    _gpio_available = {}


def _signal_handler(signum, frame):
    """Handle SIGINT / SIGTERM for graceful shutdown."""
    global _running
    _running = False


def _init_gpio():
    """Initialize all input and output pins. Raises on failure."""
    global _gpio_available
    try:
        for pin in INPUT_PINS:
            btn = Button(pin=pin, pull_up=True, bounce_time=None)
            # pull_up=True keeps the line HIGH when idle; a button press pulls it LOW.
            _gpio_available[pin] = btn
    except GPIOZeroError as exc:
        raise RuntimeError(f"Failed to initialize input pins: {exc}") from exc

    try:
        for pin in OUTPUT_PINS:
            dev = OutputDevice(pin=pin, active_high=True, initial_value=False)
            _gpio_available[pin] = dev
            _output_states[pin] = False
    except GPIOZeroError as exc:
        raise RuntimeError(f"Failed to initialize output pins: {exc}") from exc


def _read_inputs():
    """Return dict of pin -> boolean (True = HIGH, False = LOW)."""
    return {pin: bool(dev.value) for pin, dev in _gpio_available.items()}


def _write_outputs(states):
    """Drive all output pins to the given logical states."""
    for pin, dev in _gpio_available.items():
        _output_states[pin] = states[pin]
        dev.value = 1 if states[pin] else 0


def main():
    global _running

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        _init_gpio()
    except RuntimeError as exc:
        print(f"GPIO initialization error: {exc}", file=sys.stderr)
        _cleanup()
        sys.exit(1)

    print("Monitoring inputs GPIO 4, 5, 6; driving outputs GPIO 23, 24. Press Ctrl-C to exit.")

    try:
        while _running:
            inputs = _read_inputs()

            # GPIO 4 -> GPIO 23
            if inputs[4] == 0:
                _write_outputs({pin: _output_states[pin] for pin in OUTPUT_PINS})
                _output_states[23] = not _output_states[23]

            # GPIO 5 -> GPIO 23 (clear when active)
            if inputs[5] == 0:
                _write_outputs({pin: _output_states[pin] for pin in OUTPUT_PINS})
                _output_states[23] = False

            # GPIO 6 -> toggle GPIO 24
            if inputs[6] == 0:
                _write_outputs({pin: _output_states[pin] for pin in OUTPUT_PINS})
                _output_states[24] = not _output_states[24]

            time.sleep(POLL_INTERVAL)

    except Exception as exc:
        print(f"Runtime error: {exc}", file=sys.stderr)
    finally:
        _cleanup()
        print("GPIO cleanup completed.")


if __name__ == "__main__":
    main()

