#!/usr/bin/env python3
"""
Motion-activated security camera for Raspberry Pi using picamera2.
Captures 5-second H.264 clips when motion is detected.
Manages storage by deleting oldest files if total size exceeds --max_size.
"""

import argparse
import datetime
import os
import signal
import sys
import time

import cv2
import numpy as np
from picamera2 import Picamera2
from picamera2.encoders import H264Encoder
from picamera2.outputs import FileOutput


def parse_arguments():
    parser = argparse.ArgumentParser(
        description="Raspberry Pi motion-activated security camera (picamera2)"
    )
    parser.add_argument(
        "--threshold",
        type=int,
        default=5,
        help="Brightness difference threshold for motion detection (default: 5)",
    )
    parser.add_argument(
        "--duration",
        type=int,
        default=5,
        help="Recording duration in seconds after motion is detected (default: 5)",
    )
    parser.add_argument(
        "--max_size",
        type=int,
        default=1024 * 1024 * 1,
        help="Maximum total file size in bytes for the security_footage directory (default: 1 GB)",
    )
    return parser.parse_args()


def initialize_camera():
    """Initialize picamera2 with 320x240 @ 15 fps. Returns Picamera2 instance or None."""
    try:
        picam2 = Picamera2()
        config = picam2.create_preview_configuration(
            main={"size": (320, 240), "format": "RGB888"},
            controls={"FrameRate": 15},
        )
        picam2.configure(config)
        picam2.start()
        return picam2
    except Exception as e:
        print(f"Error initializing camera: {e}", file=sys.stderr)
        return None


def ensure_directory(path):
    """Create directory if it does not exist. Handle permission and disk-full errors."""
    try:
        os.makedirs(path, exist_ok=True)
    except PermissionError as e:
        print(f"Permission denied creating directory '{path}': {e}", file=sys.stderr)
        return False
    except OSError as e:
        if e.errno == 28:
        # ENOSPC: disk full
            print(f"Disk full. Cannot create directory '{path}'.", file=sys.stderr)
        else:
            print(f"OS error creating directory '{path}': {e}", file=sys.stderr)
        return False
    return True


def capture_frame(picam2):
    """Capture a single frame as a numpy array (RGB)."""
    try:
        return picam2.capture_array()
    except Exception as e:
        print(f"Error capturing frame: {e}", file=sys.stderr)
        return None


def calculate_average_brightness(frame):
    """Return average brightness of a frame as float."""
    if frame is None or frame.size == 0:
        return 0.0
    if frame.ndim == 3:
        # Convert RGB to grayscale by averaging channels
        gray = np.mean(frame, axis=2).astype(np.float32)
    else:
        gray = frame.astype(np.float32)
    return float(np.mean(gray))


def detect_motion(picam2, threshold):
    """Return True if average brightness difference between two frames exceeds threshold."""
    frame1 = capture_frame(picam2)
    if frame1 is None:
        return False
    time.sleep(0.1)  # Small delay for second frame
    frame2 = capture_frame(picam2)
    if frame2 is None:
        return False
    return abs(calculate_average_brightness(frame1) - calculate_average_brightness(frame2)) > threshold


def record_video(picam2, duration, output_dir):
    """Record a video clip of given duration in H.264 format."""
    timestamp = datetime.datetime.now().strftime("%Y-%m-%d_%H-%M-%S")
    filename = os.path.join(output_dir, f"{timestamp}.h264")
    try:
        encoder = H264Encoder()
        output = FileOutput(filename)
        picam2.start_recording(encoder, output)
        time.sleep(duration)
        picam2.stop_recording()
        print(f"Video saved: {filename}")
        return filename
    except Exception as e:
        print(f"Error recording video: {e}", file=sys.stderr)
        try:
            picam2.stop_recording()
        except Exception:
            pass
        return None


def manage_storage(output_dir, max_size):
    """Delete oldest files if total size exceeds max_size."""
    try:
        files = [
            (os.path.join(output_dir, f), os.path.getmtime(f))
            for f in os.listdir(output_dir)
            if os.path.isfile(os.path.join(output_dir, f))
        ]
        total_size = sum(os.path.getsize(f) for _, f in files)
        if total_size > max_size:
            files.sort(key=lambda x: x[1])
            for filepath, _ in files:
                try:
                    os.remove(filepath)
                    total_size -= os.path.getsize(filepath)
                    print(f"Deleted old file: {filepath}")
                    if total_size <= max_size:
                        break
                except OSError as e:
                    print(f"Error deleting {filepath}: {e}", file=sys.stderr)
                    break
    except OSError as e:
        print(f"Error managing storage: {e}", file=sys.stderr)


def signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for clean shutdown."""
    print("\nInterrupt received, shutting down...")
    sys.exit(0)


def main():
    args = parse_arguments()
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    # Initialize camera
    picam2 = initialize_camera()
    if picam2 is None:
        sys.exit(1)

    # Ensure output directory exists
    output_dir = "/home/pi/security_footage"
    if not ensure_directory(output_dir):
        picam2.close()
        sys.exit(1)

    print("Security camera started. Press Ctrl+C to stop.")

    try:
        while True:
            if detect_motion(picam2, args.threshold):
                print("Motion detected!")
                record_video(picam2, args.duration, output_dir)
                manage_storage(output_dir, args.max_size)
            time.sleep(2)
    except KeyboardInterrupt:
        print("\nExiting...")
    finally:
        try:
            picam2.stop_recording()
        except Exception:
            pass
        picam2.close()
        print("Camera resources released.")


if __name__ == "__main__":
    main()

