import io
import time
import threading
import subprocess
import zmq
from gps3 import gps3
from picamera2 import Picamera2
from picamera2.encoders import MJPEGEncoder
from picamera2.outputs import Output

DEFAULT_GPS_LAT = "22.483425"
DEFAULT_GPS_LON = "88.455463"
ZMQ_ENDPOINT = "tcp://192.168.1.4:5555"
CAMERA_RESOLUTION = (640, 480)
CAMERA_FRAMERATE = 100
CAMERA_ROTATION = 180
GPS_POLL_INTERVAL = 0.5


class MJPEGStreamOutput(Output):
    """picamera2 Output that buffers complete MJPEG frames."""

    def __init__(self):
        super().__init__()
        self.frame = None
        self.buffer = io.BytesIO()
        self.condition = threading.Condition()

    def outputframe(self, frame):
        # frame is a bytes-like object containing a complete JPEG
        with self.condition:
            self.frame = frame
            self.condition.notify_all()

    def get_frame(self):
        with self.condition:
            self.condition.wait()
            return self.frame


def restart_gpsd():
    """Attempt to restart gpsd via systemctl, with one retry."""
    try:
        subprocess.run(
            ["sudo", "systemctl", "restart", "gpsd"],
            check=True,
            timeout=10,
        )
        print("gpsd restarted via systemctl")
    except (subprocess.CalledProcessError, subprocess.TimeoutExpired):
        print("gpsd not running; attempting restart via systemctl")
    except FileNotFoundError:
        print("systemctl not available; cannot restart gpsd")
    except Exception as e:
        print(f"Error restarting gpsd: {e}")


def send_frame(socket, gps_data, frame_data):
    """Send a two-part message: CSV metadata followed by MJPEG bytes."""
    try:
        socket.send_string(gps_data, zmq.SNDMORE)
        socket.send(frame_data)
    except zmq.ZMQError as e:
        print(f"ZMQError sending frame: {e}")
    except Exception as e:
        print(f"Unexpected error sending frame: {e}")


def capture_and_send_images(footage_socket, stop_event):
    """Background thread: capture MJPEG frames and send them with GPS data."""
    camera = None
    try:
        camera = Picamera2()
        video_config = camera.create_video_configuration(
            main={"size": CAMERA_RESOLUTION, "format": "MJPEG"},
            controls={"FrameRate": CAMERA_FRAMERATE},
        )
        camera.configure(video_config)
        camera.set_controls({"Rotation": CAMERA_ROTATION})

        output = MJPEGStreamOutput()
        encoder = MJPEGEncoder()
        camera.start_recording(encoder, output)
        print("Camera recording started")

        gps_lat = DEFAULT_GPS_LAT
        gps_lon = DEFAULT_GPS_LON
        lock = threading.Lock()

        while not stop_event.is_set():
            try:
                with lock:
                    lat = gps_lat
                    lon = gps_lon

                frame = output.get_frame()
                if frame is None:
                    continue

                mag = 1.0
                alt = 0.0
                metadata_str = f"{lat},{lon},{mag},{alt}"
                send_frame(footage_socket, metadata_str, frame)

            except zmq.ZMQError as e:
                print(f"ZMQError in capture loop: {e}")
                break
            except Exception as e:
                print(f"Unexpected error in capture loop: {e}")
                break

    except Exception as e:
        print(f"Camera error: {e}")
    finally:
        if camera is not None:
            try:
                camera.stop_recording()
            except Exception:
                pass
            try:
                camera.close()
            except Exception:
                pass
        print("Camera recording stopped")


def get_gps_data(stop_event):
    """Background thread: poll gpsd every GPS_POLL_INTERVAL seconds."""
    gps_socket = None
    try:
        gps_socket = gps3.GPSDSocket()
        data_stream = gps3.DataStream()
        gps_socket.connect()
        gps_socket.watch()

        gps_lat = DEFAULT_GPS_LAT
        gps_lon = DEFAULT_GPS_LON
        lock = threading.Lock()

        while not stop_event.is_set():
            try:
                for new_data in gps_socket:
                    if stop_event.is_set():
                        break
                    if new_data:
                        data_stream.unpack(new_data)
                        lat = data_stream.TPV['lat']
                        lon = data_stream.TPV['lon']

                        if isinstance(lat, (int, float)) and isinstance(lon, (int, float)):
                            with lock:
                                gps_lat = str(lat)
                                gps_lon = str(lon)
                            print(f"GPS: lat={gps_lat}, lon={gps_lon}")
                        else:
                            print("GPS data not valid (non-numeric)")
                    time.sleep(GPS_POLL_INTERVAL)
            except Exception as e:
                print(f"Error reading GPS data: {e}")
                restart_gpsd()
                time.sleep(GPS_POLL_INTERVAL)

    except Exception as e:
        print(f"GPS initialization error: {e}")
    finally:
        if gps_socket is not None:
            try:
                gps_socket.close()
            except Exception:
                pass
        print("GPS data stream stopped")


def main():
    context = None
    footage_socket = None
    stop_event = threading.Event()
    gps_thread = None
    camera_thread = None

    try:
        context = zmq.Context()
        footage_socket = context.socket(zmq.PUB)
        footage_socket.setsockopt(zmq.LINGER, 0)
        footage_socket.connect(ZMQ_ENDPOINT)
        print(f"ZMQ PUB connected to {ZMQ_ENDPOINT}")

        gps_thread = threading.Thread(target=get_gps_data, args=(stop_event,), daemon=True)
        camera_thread = threading.Thread(
            target=capture_and_send_images, args=(footage_socket, stop_event), daemon=True
        )
        gps_thread.start()
        camera_thread.start()

        while not stop_event.is_set():
            time.sleep(0.1)

    except KeyboardInterrupt:
        print("KeyboardInterrupt received")
    except zmq.ZMQError as e:
        print(f"ZMQError in main: {e}")
    except Exception as e:
        print(f"Unexpected error in main: {e}")
    finally:
        stop_event.set()
        if gps_thread is not None and gps_thread.is_alive():
            gps_thread.join(timeout=2.0)
        if camera_thread is not None and camera_thread.is_alive():
            camera_thread.join(timeout=2.0)
        if footage_socket is not None:
            try:
                footage_socket.close()
            except Exception:
                pass
        if context is not None:
            try:
                context.term()
            except Exception:
                pass
        print("Shutdown complete")


if __name__ == "__main__":
    main()

