import signal
import sys
import time
import numpy as np
import sounddevice as sd
from gpiozero import Button

SAMPLE_RATE = 44100
BLOCK_SIZE = 1024
BUTTON_PIN = 5

gain = 1.0
running = True
button = None
stream = None


def signal_handler(signum, frame):
    global running
    running = False


def apply_gain(indata, gain_val):
    outdata = indata * gain_val
    return np.clip(outdata, -1.0, 1.0)


def apply_distortion(indata, gain_val):
    outdata = np.tanh(indata * gain_val)
    return np.clip(outdata, -1.0, 1.0)


def audio_callback(indata, outdata, frames, time_info, status):
    if status:
        print(f"Audio stream status: {status}", file=sys.stderr)
    try:
        outdata[:] = apply_gain(indata, gain)
        outdata = apply_distortion(outdata, gain)
    except Exception as e:
        print(f"Error in audio callback: {e}", file=sys.stderr)
        outdata[:] = indata


def button_pressed():
    global gain
    gain = 2.0 if gain == 1.0 else 1.0
    print(f"Gain toggled to: {gain}")


def cleanup():
    global button, stream
    if stream is not None:
        try:
            stream.stop()
            stream.close()
        except Exception:
            pass
        stream = None
    if button is not None:
        try:
            button.close()
        except Exception:
            pass
        button = None


def main():
    global button, stream

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        button = Button(BUTTON_PIN, pull_up=True, active_state=False, bounce_time=0.2)
        button.when_pressed = button_pressed
    except Exception as e:
        print(f"Failed to initialize button on GPIO{BUTTON_PIN}: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        stream = sd.Stream(
            samplerate=SAMPLE_RATE,
            blocksize=BLOCK_SIZE,
            channels=1,
            dtype='float32',
            callback=audio_callback,
        )
        stream.start()
    except Exception as e:
        print(f"Failed to start audio stream: {e}", file=sys.stderr)
        cleanup()
        sys.exit(1)

    print("Audio effects processor running. Press Ctrl+C to exit.")

    try:
        while running:
            time.sleep(0.1)
    finally:
        cleanup()
        print("Resources released. Exiting.")


if __name__ == "__main__":
    main()

