import time
import threading

import pygame.mixer
import cv2
from picamera2 import Picamera2
from gpiozero import Button, OutputDevice

import config
import face


class DoorController:
    """Controls a door lock via GPIO and recognizes faces using picamera2."""

    def __init__(self):
        self.lock = None
        self.button = None
        self.camera = None
        self.welcome_sound = None
        self.wait_sound = None
        self.later_sound = None
        self.is_running = False
        self.running_lock = threading.Lock()
        self._shutdown = False

        try:
            self.lock = OutputDevice(18, active_high=True, initial_value=False)
            self.button = Button(17, pull_up=True)
        except Exception as e:
            print(f"Error initializing GPIO: {e}", file=sys.stderr)
            raise

        try:
            pygame.mixer.init(48000, -16, 1, 1024)
            self.welcome_sound = pygame.mixer.Sound(config.WELCOME_SOUND_PATH)
            self.wait_sound = pygame.mixer.Sound(config.WAIT_SOUND_PATH)
            self.later_sound = pygame.mixer.Sound(config.LATER_SOUND_PATH)
        except Exception as e:
            print(f"Error initializing sound: {e}", file=sys.stderr)
            raise

        try:
            self.camera = Picamera2()
            self.camera.configure(
                self.camera.create_preview_configuration(
                    main={"size": (640, 480), "format": "RGB888"}
                )
            )
            self.camera.start()
        except Exception as e:
            print(f"Error initializing camera: {e}", file=sys.stderr)
            raise

        try:
            print("Loading face recognition model...")
            self.model = cv2.face.EigenFaceRecognizer_create()
            self.model.read(config.TRAINING_FILE)
        except Exception as e:
            print(f"Error loading face recognition model: {e}", file=sys.stderr)
            raise

        self.is_running = True

    def _cleanup(self):
        """Release all hardware and mixer resources."""
        if self.camera is not None:
            try:
                self.camera.stop()
            except Exception:
                pass
            self.camera = None

        if self.lock is not None:
            try:
                self.lock.close()
            except Exception:
                pass
            self.lock = None

        if self.button is not None:
            try:
                self.button.close()
            except Exception:
                pass
            self.button = None

        try:
            pygame.mixer.quit()
        except Exception:
            pass

    def _signal_handler(self, signum, frame):
        print(f"\nSignal {signum} received, shutting down...")
        self._shutdown = True
        self.is_running = False

    def run(self):
        signal.signal(signal.SIGINT, self._signal_handler)
        signal.signal(signal.SIGTERM, self._signal_handler)

        print("Running door controller...")
        print("Press the button to attempt face recognition.")
        print("Press Ctrl-C to quit.")

        try:
            while self.is_running and not self._shutdown:
                try:
                    if self.button.is_button_up():
                        self.process_face()
                except Exception as e:
                    print(f"Error during button check: {e}", file=sys.stderr)

                time.sleep(0.1)
        finally:
            self._cleanup()
            print("Exiting...")

