        """Capture a frame, run face recognition, and act on the result."""
        try:
            image = self.camera.capture_array()
            if image is None:
                print("Warning: captured empty frame", file=sys.stderr)
                self.play_sound(self.later_sound)
                return

            gray_image = cv2.cvtColor(image, cv2.COLOR_RGB2GRAY)
            face_coords = face.detect_single(gray_image)

            if face_coords is None:
                print("No face detected.")
                self.play_sound(self.later_sound)
                return

            x, y, w, h = face_coords
            cropped_face = face.crop(gray_image, x, y, w, h)
            resized_face = face.resize(cropped_face)

            label, confidence = self.model.predict(resized_face)

            print(
                f"Predicted label: {label}, Confidence: {confidence:.2f}"
            )

            if label == config.POSITIVE_LABEL and confidence < config.POSITIVE_THRESHOLD:
                print("Face recognized! Unlocking door...")
                self.lock.on()
                self.play_sound(self.welcome_sound)
            else:
                print("Face not recognized.")
                self.play_sound(self.wait_sound)

        except Exception as e:
            print(f"Error during face processing: {e}", file=sys.stderr)

    def play_sound(self, sound):
        """Play a Sound asynchronously."""
        if sound is None:
            return
        try:
            sound.play()
        except pygame.error as e:
            print(f"Error playing sound: {e}", file=sys.stderr)


if __name__ == "__main__":
    try:
        controller = DoorController()
    except Exception:
        print("Initialization failed. Exiting.", file=sys.stderr)
        sys.exit(1)

    controller.run()

