import time
import signal
import sys
import board
import busio
import adafruit_ssd1306
import adafruit_bme280
import adafruit_tsl2561

# Global resources for cleanup
display = None
i2c_bus = None
running = True

def cleanup():
    """Release resources and clear the display."""
    global display, i2c_bus
    if display is not None:
        try:
            display.fill(0)
            display.show()
        except Exception:
            pass
    if i2c_bus is not None:
        try:
            i2c_bus.deinit()
        except Exception:
            pass

def signal_handler(sig, frame):
    """Handle SIGINT for graceful shutdown."""
    global running
    running = False

def main():
    global display, i2c_bus

    # Register signal handler for Ctrl+C
    signal.signal(signal.SIGINT, signal_handler)

    # Initialize I2C bus on GPIO3 (SCL) and GPIO2 (SDA)
    try:
        i2c_bus = busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Failed to initialize I2C bus: {e}", file=sys.stderr)
        sys.exit(1)

    # Initialize OLED display at address 0x3C
    try:
        display = adafruit_ssd1306.SSD1306_I2C(128, 64, i2c_bus, addr=0x3C)
        display.fill(0)
        display.show()
    except Exception as e:
        print(f"Failed to initialize OLED display: {e}", file=sys.stderr)
        cleanup()
        sys.exit(1)

    # Initialize BME280 sensor at address 0x76
    try:
        bme280 = adafruit_bme280.Adafruit_BME280_I2C(i2c_bus, address=0x76)
    except Exception as e:
        print(f"Failed to initialize BME280 sensor: {e}", file=sys.stderr)
        bme280 = None

    # Initialize TSL2561 sensor at address 0x39
    try:
        tsl2561 = adafruit_tsl2561.TSL2561(i2c_bus, address=0x39)
    except Exception as e:
        print(f"Failed to initialize TSL2561 sensor: {e}", file=sys.stderr)
        tsl2561 = None

    # Main loop
    while running:
        try:
            # Read data from sensors
            if bme280 is not None:
                temperature = bme280.temperature
                humidity = bme280.humidity
                pressure = bme280.pressure
            else:
                temperature = None
                humidity = None
                pressure = None

            if tsl2561 is not None:
                light_intensity = tsl2561.lux
            else:
                light_intensity = None

            # Update display
            if display is not None:
                display.fill(0)
                if temperature is not None:
                    display.text(f"Temp: {temperature:.1f} C", 0, 0, 1)
                else:
                    display.text("Temp: N/A", 0, 0, 1)
                if humidity is not None:
                    display.text(f"Humidity: {humidity:.1f} %", 0, 16, 1)
                else:
                    display.text("Humidity: N/A", 0, 16, 1)
                if pressure is not None:
                    display.text(f"Pressure: {pressure:.1f} hPa", 0, 32, 1)
                else:
                    display.text("Pressure: N/A", 0, 32, 1)
                if light_intensity is not None:
                    display.text(f"Light: {light_intensity:.1f} lux", 0, 48, 1)
                else:
                    display.text("Light: N/A", 0, 48, 1)
                display.show()

            # Wait 1 second, checking for exit signal
            for _ in range(10):
                if not running:
                    break
                time.sleep(0.1)

        except Exception as e:
            print(f"Error during sensor read or display update: {e}", file=sys.stderr)
            time.sleep(1)

    cleanup()

if __name__ == "__main__":
    main()

