import signal
import sys
import time
import struct
from smbus2 import SMBus
from luma.core.interface.serial import i2c
from luma.oled.device import ssd1306
from luma.core.render import canvas

TSL2561_ADDR = 0x29
SSD1306_ADDR = 0x3C
I2C_BUS = 1

TSL2561_CMD_BIT = 0xA0
TSL2561_REG_CONTROL = 0x80
TSL2561_REG_CHAN0_LOW = 0x0C
TSL2561_REG_CHAN1_LOW = 0x0E
TSL2561_REG_ID = 0x0A

TSL2561_INTEGRATIONTIME_101MS = 0x00
TSL2561_GAIN_1X = 0x10
TSL2561_POWER_ON = 0x03

TSL2561_ID_EXPECTED = 0x50

running = True
bus = None
tsl = None
oled = None


def cleanup(signum=None, frame=None):
    global running, bus, tsl, oled
    running = False
    try:
        if tsl is not None:
            tsl.power_off()
    except Exception:
        pass
    try:
        if oled is not None:
            oled.clear()
    except Exception:
        pass
    try:
        if bus is not None:
            bus.close()
    except Exception:
        pass
    if signum is not None:
        sys.exit(0)


def tsl2561_init(bus):
    global tsl
    try:
        dev_id = bus.read_byte_data(TSL2561_ADDR, TSL2561_REG_ID)
        if dev_id != TSL2561_ID_EXPECTED:
            raise RuntimeError(f"TSL2561 not found at 0x{TSL2561_ADDR:02X} (ID=0x{dev_id:02X})")
    except Exception as e:
        raise RuntimeError(f"TSL2561 not responding: {e}")
    try:
        bus.write_byte_data(TSL2561_ADDR, TSL2561_CMD_BIT | TSL2561_REG_CONTROL, TSL2561_POWER_ON)
        bus.write_byte_data(TSL2561_ADDR, TSL2561_CMD_BIT | TSL2561_REG_CONTROL, TSL2561_INTEGRATIONTIME_101MS | TSL2561_GAIN_1X)
        tsl = TSL2561(bus)
    except Exception as e:
        raise RuntimeError(f"TSL2561 init failed: {e}")


class TSL2561:
    def __init__(self, bus):
        self.bus = bus

    def power_off(self):
        try:
            self.bus.write_byte_data(TSL2561_ADDR, TSL2561_CMD_BIT | TSL2561_REG_CONTROL, 0x00)
        except Exception:
            pass

    @staticmethod
    def _read_channel(bus, reg_low):
        data = bus.read_i2c_block_data(TSL2561_ADDR, reg_low, 2)
        return struct.unpack('>H', bytes(data))[0]

    @staticmethod
    def _compute_lux(chan0, chan1):
        if chan0 == 0:
            return 0.0
        if chan1 == 0:
            return 0.0
        ratio = chan0 / chan1
        if 0 < ratio <= 0.52:
            lux = 0.0315 * chan0 - 0.05934 * chan0 * (ratio**1.4)
        elif 0.52 < ratio <= 0.65:
            lux = 0.02291 * chan0 - 0.02916 * chan1
        elif 0.65 < ratio <= 0.80:
            lux = 0.01579 * chan0 - 0.01804 * chan1
        elif 0.80 < ratio <= 1.3:
            lux = 0.00338 * chan0 - 0.0026 * chan1
        else:
            lux = 0.0
        return max(0.0, lux)


def main():
    global bus, oled
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    try:
        bus = SMBus(I2C_BUS)
    except Exception as e:
        print(f"Failed to open I2C bus {I2C_BUS}: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        tsl2561_init(bus)
    except Exception as e:
        print(f"Light sensor init failed: {e}", file=sys.stderr)
        bus.close()
        sys.exit(1)

    try:
        serial = i2c(port=I2C_BUS, address=SSD1306_ADDR)
        oled = ssd1306(serial, width=128, height=64)
    except Exception as e:
        print(f"OLED init failed: {e}", file=sys.stderr)
        bus.close()
        sys.exit(1)

    print("TSL2561 + SSD1306 ready. Press Ctrl+C to exit.")

    while running:
        try:
            chan0 = tsl._read_channel(bus, TSL2561_REG_CHAN0_LOW)
            chan1 = tsl._read_channel(bus, TSL2561_REG_CHAN1_LOW)
            lux = tsl._compute_lux(chan0, chan1)
            brightness = int(min(max(lux / 1000.0, 0.0), 255.0))
            oled.contrast(brightness)
            with canvas(oled) as draw:
                draw.text((0, 0), f"Lux: {lux:.2f}", fill="white")
        except Exception as e:
            print(f"Sensor read error: {e}", file=sys.stderr)
        time.sleep(1.0)


if __name__ == "__main__":
    main()

