        gif_files = [
            f for f in os.listdir(folder)
            if f.lower().endswith(".gif") and os.path.isfile(os.path.join(folder, f))
        ]

        if not gif_files:
            raise FileNotFoundError(f"No GIF files found in folder: {folder}")

        try:
            serial = spi(port=0, device=0, bus_speed_hz=1000000, gpio_DC=25, gpio_RST=24)
            self.device = st7789(serial, width=display_width, height=display_height)
        except Exception as e:
            raise RuntimeError(f"Failed to initialize display: {e}")

        self.gif_files = gif_files

    def _signal_handler(self, signum, frame):
        print(f"\nReceived signal {signum}, shutting down...")
        self._running = False

    def play(self):
        """
        Plays a single GIF, converting each frame to RGB and displaying it.
        """
        if not self.device:
            raise RuntimeError("Display not initialized.")

        try:
            with Image.open(os.path.join(self.folder, self.gif_files[0])) as img:
