                    rgb_frame = frame.convert("RGB")
                    padded_frame = ImageOps.pad(
                        rgb_frame,
                        (self.display_width, self.display_height),
                        method=Image.NEAREST,
                        color=(0, 0, 0),
                        centering=(0.5, 0.5),
                    )
                    self.device.display(padded_frame)
                    time.sleep(frame.info.get("duration", 0.1) / 1000.0)
        except Exception as e:
            print(f"Error playing GIF {self.gif_files[0]}: {e}")

