import signal
import sys
import time

try:
    from smbus2 import SMBus, i2c_msg
except ImportError:
    print("Error: smbus2 library not found. Install with: pip install smbus2")
    sys.exit(1)

PCF8574_ADDR = 0x20
I2C_BUS = 1
POLL_INTERVAL = 0.1
ERROR_PAUSE = 1.0

running = True


def signal_handler(signum, frame):
    global running
    running = False


def read_pcf8574(bus, addr):
    """Read the 8-bit output port of the PCF8574; return int or None on error."""
    try:
        return bus.read_byte_data(addr, 0x00)
    except OSError as e:
        print(f"I2C read error from 0x{addr:02X}: {e}")
        return None


def main():
    global running

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        bus = SMBus(I2C_BUS)
    except OSError as e:
        print(f"Error: cannot open I2C bus {I2C_BUS}: {e}")
        sys.exit(1)

    try:
        # Probe the bus for the expander address
        try:
            bus.read_byte_data(PCF8574_ADDR, 0x00)
        except OSError:
            print(f"Error: no device found at I2C address 0x{PCF8574_ADDR:02X} on bus {I2C_BUS}.")
            sys.exit(1)

        # Configure all pins as inputs with internal pull-up enabled (0xFF = all 1s)
        try:
            bus.write_byte_data(PCF8574_ADDR, 0x00, 0xFF)
        except OSError as e:
            print(f"Error: failed to write to PCF8574 output port: {e}")
            sys.exit(1)

        print("PCF8574 initialized. Polling sensors every 100 ms. Press Ctrl-C to exit.")

        while running:
            port = read_pcf8574(bus, PCF8574_ADDR)
            if port is None:
                time.sleep(ERROR_PAUSE)
                continue

            for i in range(8):
                if port & (1 << i):
                    print(f"Obstacle detected by sensor {i}")

            time.sleep(POLL_INTERVAL)

    finally:
        bus.close()
        print("\nI2C bus closed. Exiting.")


if __name__ == "__main__":
    main()

