import time
import signal
import sys
from gpiozero import OutputDevice, InputDevice

TRIGGER_PIN = 23
ECHO_PIN = 24
SETTLING_TIME = 2.0
TIMEOUT_S = 0.1
SPEED_OF_SOUND_CM_S = 34300.0

trigger = None
echo = None

def cleanup(signum=None, frame=None):
    global trigger, echo
    if trigger is not None:
        trigger.close()
        trigger = None
    if echo is not None:
        echo.close()
        echo = None
    if signum is not None:
        sys.exit(0)

def measure_distance():
    trigger.on()
    time.sleep(0.00001)
    trigger.off()

    deadline = time.time() + TIMEOUT_S
    while echo.is_active:
        if time.time() > deadline:
            return None
    pulse_start = time.time()

    deadline = time.time() + TIMEOUT_S
    while not echo.is_active:
        if time.time() > deadline:
            return None
    pulse_end = time.time()

    pulse_duration = pulse_end - pulse_start
    distance = pulse_duration * SPEED_OF_SOUND_CM_S / 2.0
    return round(distance, 2)

def main():
    global trigger, echo
    signal.signal(signal.SIGTERM, cleanup)
    try:
        trigger = OutputDevice(TRIGGER_PIN)
        echo = InputDevice(ECHO_PIN)
        trigger.off()
        time.sleep(SETTLING_TIME)
        while True:
            dist = measure_distance()
            if dist is not None:
                print(f"Measured Distance = {dist} cm")
            else:
                print("Error: Sensor not responding (timeout).")
            time.sleep(0.5)
    except KeyboardInterrupt:
        pass
    finally:
        cleanup()

if __name__ == "__main__":
    main()

