import time
import sys
import board
import adafruit_dht

# DHT11 on GPIO4 (BCM) == board.D4 (physical pin 7)
SENSOR_PIN = board.D4
MAX_RETRIES = 5
RETRY_DELAY = 2.0  # DHT11 needs >= 1 s between reads; 2 s is safe


def read_sensor(sensor):
    """Attempt one DHT11 read; return (temperature, None) on success or (None, error) on failure."""
    try:
        temperature = sensor.temperature
        if temperature is None:
            return None, "Sensor returned None"
        return temperature, None
    except RuntimeError as e:
        # Common DHT11 errors: checksum failure, timeout, or insufficient delay
        return None, f"DHT11 read error: {e}"
    except Exception as e:
        return None, f"Unexpected error: {e}"


def main():
    sensor = None
    try:
        sensor = adafruit_dht.DHT11(SENSOR_PIN, use_pulseio=False)
    except Exception as e:
        print(f"Failed to initialize DHT11 on GPIO4: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        for attempt in range(1, MAX_RETRIES + 1):
            temperature, error = read_sensor(sensor)
            if temperature is not None:
                print(f"Temperature: {temperature:.1f} C")
                sys.exit(0)
            print(f"Attempt {attempt}/{MAX_RETRIES}: {error}", file=sys.stderr)
            if attempt < MAX_RETRIES:
                time.sleep(RETRY_DELAY)

        print("Error: Could not read temperature after "
              f"{MAX_RETRIES} attempts.", file=sys.stderr)
        sys.exit(1)

    except KeyboardInterrupt:
        print("\nInterrupted by user.", file=sys.stderr)
        sys.exit(1)
    finally:
        if sensor is not None:
            try:
                sensor.exit()
            except Exception:
                pass


if __name__ == "__main__":
    main()

