import time
import logging
import signal
import sys
from smbus2 import SMBus

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)


class DHT20:
    """Driver for the Aosong DHT20 I2C temperature/humidity sensor."""

    DHT20_I2C_ADDRESS = 0x38
    DHT20_STATUS_REG = 0x71
    DHT20_MEASURE_REG = 0xAC
    DHT20_MEASURE_CMD = [0x33, 0x00]
    CRC_POLYNOMIAL = 0x31
    CRC_INITIAL = 0xFF
    MEASUREMENT_TIMEOUT = 0.1
    RETRY_DELAY = 2.0
    MAX_RETRIES = 5

    def __init__(self, i2c_bus=1):
        self.i2c_bus_number = i2c_bus
        self.bus = None
        self._closed = False
        try:
            self.bus = SMBus(i2c_bus)
        except FileNotFoundError:
            logger.error("I2C bus %d not found. Enable I2C and check /dev/i2c-%d.", i2c_bus, i2c_bus)
            raise
        except PermissionError:
            logger.error("Permission denied on /dev/i2c-%d. Add user to the 'i2c' group.", i2c_bus)
            raise
        except OSError as e:
            logger.error("Failed to open I2C bus %d: %s", i2c_bus, e)
            raise

        time.sleep(0.5)  # Allow sensor to stabilize after power-on

        try:
            status = self._read_register(self.DHT20_STATUS_REG)
            if (status & 0x18) != 0x18:
                logger.error("DHT20 status check failed: 0x%02X. Check wiring and address.", status)
                self.close()
                raise RuntimeError("DHT20 status check failed")
        except OSError as e:
            logger.error("Failed to read DHT20 status register: %s", e)
            self.close()
            raise RuntimeError("Failed to communicate with DHT20") from e

        logger.info("DHT20 initialized on bus %d at address 0x%02X.", i2c_bus, self.DHT20_I2C_ADDRESS)

    def _read_register(self, register):
        try:
            return self.bus.read_byte_data(self.DHT20_I2C_ADDRESS, register)
        except OSError as e:
            logger.error("I2C read error from register 0x%02X: %s", register, e)
            raise

    def _write_register(self, register, value):
        try:
            self.bus.write_byte_data(self.DHT20_I2C_ADDRESS, register, value)
        except OSError as e:
            logger.error("I2C write error to register 0x%02X: %s", register, e)
            raise

    def get_temperature_and_humidity(self):
        """
        Retrieve temperature (°C) and humidity (%) from the DHT20.

        Returns:
            tuple: (temperature, humidity, crc_error_flag)
                   crc_error_flag is True if the CRC check failed.
        """
        for attempt in range(1, self.MAX_RETRIES + 1):
            try:
                self._write_register(self.DHT20_MEASURE_REG, self.DHT20_MEASURE_CMD[0])
                self._write_register(self.DHT20_MEASURE_REG, self.DHT20_MEASURE_CMD[1])

                start_time = time.time()
                while True:
                    status = self._read_register(self.DHT20_STATUS_REG)
                    if (status & 0x80) == 0:
                        break
                    if time.time() - start_time > self.MEASUREMENT_TIMEOUT:
                        logger.warning("Measurement timeout on attempt %d.", attempt)
                        time.sleep(self.RETRY_DELAY)
                        continue
                    time.sleep(0.005)

                data = self._read_registers(self.DHT20_STATUS_REG, 7)
                if len(data) < 7:
                    logger.warning("Incomplete data read on attempt %d.", attempt)
                    time.sleep(self.RETRY_DELAY)
                    continue

                temperature, humidity, crc_error = self._process_data(data)
                if crc_error:
                    logger.warning("CRC error on attempt %d. Retrying...", attempt)
                    time.sleep(self.RETRY_DELAY)
                    continue

                return temperature, humidity, False

            except OSError as e:
                logger.error("I2C error during measurement on attempt %d: %s", attempt, e)
                time.sleep(self.RETRY_DELAY)

        logger.error("Failed to retrieve data from DHT20 after %d attempts.", self.MAX_RETRIES)
        return None, None, True

    def _process_data(self, data):
        """
        Convert raw 7-byte data into (temperature, humidity).

        Returns:
            tuple: (temperature, humidity, crc_error_flag)
                   crc_error_flag is True if the CRC8 check fails.
        """
