        raw_t = (((data[3] & 0x0F) << 16) | (data[4] << 8) | data[5]) & 0xFFFFF
        temperature = raw_t / 5242.88 - 50.0
        humidity = raw_h / 0x100000 * 100.0
        return temperature, humidity, self._calculate_crc8(data[:6]) == data[6]

