        except OSError as e:
            logger.error("I2C read error from register 0x%02X (length %d): %s", register, length, e)
            raise

    def close(self):
        if self.bus is not None and not self._closed:
            try:
                self.bus.close()
            except OSError:
                pass
            finally:
                self._closed = True

    def __del__(self):
        self.close()


def _signal_handler(signum, frame):
    logger.info("Received signal %d, exiting.", signum)
    sys.exit(0)


