import time
import board
import busio
import adafruit_tca9548a
import adafruit_bme280
import adafruit_tsl2591

# Constants for I2C addresses and sensor channels
TCA9548A_ADDR = 0x70
BME280_CHANNEL = 0
TSL2591_CHANNEL = 1


def initialize_i2c():
    """Initializes the I2C bus."""
    try:
        i2c_bus = busio.I2C(board.SCL, board.SDA)
        # Probe the multiplexer address to confirm it is present on the bus
        while not i2c_bus.try_lock():
            pass
        try:
            devices = i2c_bus.scan()
        finally:
            i2c_bus.unlock()

        if TCA9548A_ADDR not in devices:
            print(f"Error: TCA9548A not found at address 0x{TCA9548A_ADDR:02X}.")
            return None

        return i2c_bus
    except Exception as e:
        print(f"Error initializing I2C bus: {e}")
        return None


def initialize_multiplexer(i2c_bus):
    """Initializes the TCA9548A I2C multiplexer."""
    try:
        return adafruit_tca9548a.TCA9548A(i2c_bus, address=TCA9548A_ADDR)
    except Exception as e:
        print(f"Error initializing TCA9548A multiplexer: {e}")
        return None


def initialize_bme280(multiplexer):
    """Initializes the BME280 sensor on the specified channel."""
    try:
        return adafruit_bme280.Adafruit_BME280_I2C(multiplexer[BME280_CHANNEL], address=0x76)
    except Exception as e:
        print(f"Error initializing BME280 sensor: {e}")
        return None


def initialize_tsl2591(multiplexer):
    """Initializes the TSL2591 sensor on the specified channel."""
    try:
        return adafruit_tsl2591.TSL2591(multiplexer[TSL2591_CHANNEL], address=0x29)
    except Exception as e:
        print(f"Error initializing TSL2591 sensor: {e}")
        return None


def read_sensor_data(bme280_sensor, tsl2591_sensor):
    """Reads temperature, humidity, and light intensity from the sensors."""
    temperature = None
    humidity = None
    light_intensity = None

    if bme280_sensor is not None:
        try:
            temperature = bme280_sensor.temperature
            humidity = bme280_sensor.humidity
        except Exception as e:
            print(f"Error reading BME280 data: {e}")

    if tsl2591_sensor is not None:
        try:
            light_intensity = tsl2591_sensor.lux
        except Exception as e:
            print(f"Error reading TSL2591 data: {e}")

    return temperature, humidity, light_intensity


def print_sensor_data(temperature, humidity, light_intensity):
    """Prints the sensor readings to the console."""
    if all(val is not None for val in [temperature, humidity, light_intensity]):
        print(f"Temperature: {temperature:.2f} C, Humidity: {humidity:.2f} %, Light: {light_intensity:.2f} lux")


def main():
    """Main function to read and print sensor data."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return

    multiplexer = initialize_multiplexer(i2c_bus)
    if multiplexer is None:
        return

    bme280_sensor = initialize_bme280(multiplexer)
    tsl2591_sensor = initialize_tsl2591(multiplexer)

    if bme280_sensor is None and tsl2591_sensor is None:
        print("Error: No sensors initialized. Exiting.")
        return

    try:
        while True:
            temperature, humidity, light_intensity = read_sensor_data(bme280_sensor, tsl2591_sensor)
            print_sensor_data(temperature, humidity, light_intensity)
            time.sleep(2)
    except KeyboardInterrupt:
        print("\nProgram terminated by user.")
    finally:
        print("Exiting program.")


if __name__ == "__main__":
    main()

