import time
import board
import busio
import adafruit_tca9548a
import adafruit_bme280
import adafruit_tsl2591


def initialize_i2c():
    """Initialize the I2C bus on board.SCL / board.SDA."""
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
        # Probe the bus to confirm it is responsive
        while not i2c.try_lock():
            pass
        try:
            devices = i2c.scan()
        finally:
            i2c.unlock()
        if not devices:
            print("Error: No I2C devices detected on the bus.")
            return None
        return i2c
    except Exception as e:
        print(f"Error initializing I2C bus: {e}")
        return None


def initialize_multiplexer(i2c_bus):
    """Initialize the TCA9548A I2C multiplexer at address 0x70."""
    try:
        return adafruit_tca9548a.TCA9548A(i2c_bus, address=0x70)
    except Exception as e:
        print(f"Error initializing TCA9548A multiplexer: {e}")
        return None


def initialize_bme280(multiplexer):
    """Initialize the BME280 sensor on multiplexer channel 0."""
    try:
        return adafruit_bme280.Adafruit_BME280_I2C(multiplexer[0], address=0x76)
    except Exception as e:
        print(f"Error initializing BME280 on channel 0: {e}")
        return None


def initialize_tsl2591(multiplexer):
    """Initialize the TSL2591 sensor on multiplexer channel 1."""
    try:
        return adafruit_tsl2591.TSL2591(multiplexer[1], address=0x29)
    except Exception as e:
        print(f"Error initializing TSL2591 on channel 1: {e}")
        return None


def read_sensor_data(bme280_sensor, tsl2591_sensor):
    """Read temperature, humidity, and light intensity from the sensors."""
    temperature = None
    humidity = None
    light_intensity = None

    try:
        temperature = bme280_sensor.temperature
        humidity = bme280_sensor.humidity
    except Exception as e:
        print(f"Error reading BME280 data: {e}")

    try:
        light_intensity = tsl2591_sensor.lux
    except Exception as e:
        print(f"Error reading TSL2591 data: {e}")

    return temperature, humidity, light_intensity


def print_sensor_data(temperature, humidity, light_intensity):
    """Print the sensor readings with two decimal places."""
    if temperature is not None and humidity is not None and light_intensity is not None:
        print(f"Temperature: {temperature:.2f} C, Humidity: {humidity:.2f} %, Light Intensity: {light_intensity:.2f} lux")


def main():
    """Main function to read and print sensor data."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return

    multiplexer = initialize_multiplexer(i2c_bus)
    if multiplexer is None:
        return

    bme280_sensor = initialize_bme280(multiplexer)
    if bme280_sensor is None:
        return

    tsl2591_sensor = initialize_tsl2591(multiplexer)
    if tsl2591_sensor is None:
        return

    try:
        while True:
            temperature, humidity, light_intensity = read_sensor_data(bme280_sensor, tsl2591_sensor)
            print_sensor_data(temperature, humidity, light_intensity)
            time.sleep(2)
    except KeyboardInterrupt:
        print("Exiting program.")


if __name__ == "__main__":
    main()

