import time
import json
import logging
import signal
import sys
import urllib.request
import urllib.error
from collections import deque

import board
import adafruit_dht

CONFIG_FILE = "config.json"
DEFAULT_CONFIG = {
    "dht_pin": 4,
    "webhook_url": "https://example.com/webhook",
    "temperature_threshold": 30.0,
    "humidity_threshold": 80.0,
    "retry_delay": 1,
    "max_retries": 3,
    "moving_average_window": 5,
    "log_file": "greenhouse.log",
    "log_level": "INFO",
    "simulate_sensor": False,
}

running = True
dht_device = None


def load_config(config_file=CONFIG_FILE):
    try:
        with open(config_file, "r") as f:
            return json.load(f)
    except FileNotFoundError:
        logging.warning(f"Config file {config_file} not found. Using defaults.")
        return DEFAULT_CONFIG
    except json.JSONDecodeError as e:
        logging.error(f"Invalid JSON in {config_file}: {e}. Using defaults.")
        return DEFAULT_CONFIG


def setup_logging(log_file, log_level):
    level = getattr(logging, log_level.upper(), logging.INFO)
    logging.basicConfig(
        filename=log_file,
        level=level,
        format="%(asctime)s - %(levelname)s - %(message)s",
    )
    console = logging.StreamHandler(sys.stdout)
    console.setLevel(level)
    console.setFormatter(logging.Formatter("%(asctime)s - %(levelname)s - %(message)s"))
    logging.getLogger().addHandler(console)


def signal_handler(signum, frame):
    global running
    logging.info(f"Received signal {signum}. Shutting down gracefully...")
    running = False


def read_dht22(simulate, dht_device):
    if simulate:
        logging.info("Simulating sensor data.")
        temperature = 25.0 + (time.time() % 10)
        humidity = 70.0 + (time.time() % 10)
        return temperature, humidity
    try:
        temperature = dht_device.temperature
        humidity = dht_device.humidity
        if temperature is None or humidity is None:
            raise RuntimeError("Sensor returned None")
        return temperature, humidity
    except RuntimeError as e:
        logging.warning(f"DHT22 read error: {e}. Simulating data.")
        return 25.0 + (time.time() % 10), 70.0 + (time.time() % 10)
    except Exception as e:
        logging.error(f"Unexpected DHT22 error: {e}. Simulating data.")
        return 25.0 + (time.time() % 10), 70.0 + (time.time() % 10)


def validate_data(temperature, humidity):
    if not -40.0 <= temperature <= 80.0:
        logging.warning(f"Invalid temperature: {temperature}°C. Discarding.")
        return False
    if not 0.0 <= humidity <= 100.0:
        logging.warning(f"Invalid humidity: {humidity}%. Discarding.")
        return False
    return True


def moving_average(samples, window_size):
    if not samples:
        return None
    if len(samples) < window_size:
        return sum(samples) / len(samples)
    return sum(samples[-window_size:]) / window_size


def send_webhook(webhook_url, temperature, humidity, retry_delay, max_retries):
    payload = {
        "temperature": temperature,
        "humidity": humidity,
        "timestamp": time.time(),
    }
    for attempt in range(max_retries):
        try:
            data = json.dumps(payload).encode("utf-8")
            req = urllib.request.Request(
                webhook_url, data=data, headers={"Content-Type": "application/json"}
            )
            with urllib.request.urlopen(req, timeout=10) as response:
                if 200 <= response.status < 300:
                    logging.info("Webhook sent successfully.")
                    return
                logging.warning(f"Webhook returned status {response.status}.")
        except urllib.error.URLError as e:
            logging.error(f"Webhook URL error (attempt {attempt + 1}/{max_retries}): {e}")
        except Exception as e:
            logging.error(f"Webhook send error (attempt {attempt + 1}/{max_retries}): {e}")
        if attempt < max_retries - 1:
            time.sleep(retry_delay * (2 ** attempt))
    logging.error("Webhook failed after all retries.")


def control_actuators(temperature, humidity, vent_fan, water_pump, heater):
    if temperature > 30.0 and not vent_fan:
        logging.info("Activating vent fan.")
        vent_fan = True
    elif temperature <= 30.0 and vent_fan:
        logging.info("Deactivating vent fan.")
        vent_fan = False

    if humidity < 60.0 and not water_pump:
        logging.info("Activating water pump.")
        water_pump = True
    elif humidity >= 60.0 and water_pump:
        logging.info("Deactivating water pump.")
        water_pump = False

    if temperature < 15.0 and not heater:
        logging.info("Activating heater.")
        heater = True
    elif temperature >= 15.0 and heater:
        logging.info("Deactivating heater.")
        heater = False


def cleanup():
    global dht_device
    if dht_device is not None:
        try:
            dht_device.exit()
        except Exception:
            pass
        dht_device = None
    logging.info("Cleanup complete.")


def main():
    global dht_device, running

    config = load_config()
    setup_logging(config["log_file"], config["log_level"])

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        dht_device = adafruit_dht.DHT22(board.D4, use_pulseio=False)
        logging.info("DHT22 initialized on GPIO4.")
    except Exception as e:
        logging.error(f"Failed to initialize DHT22: {e}. Simulating sensor data.")
        dht_device = None

    temperature_readings = deque(maxlen=config["moving_average_window"])
    humidity_readings = deque(maxlen=config["moving_average_window"])
    sensor_failure_count = 0
    max_sensor_failures = 3

    try:
        while running:
            temperature, humidity = read_dht22(config["simulate_sensor"], dht_device)

            if not validate_data(temperature, humidity):
                sensor_failure_count += 1
                logging.warning(f"Invalid data. Failure count: {sensor_failure_count}")
                if sensor_failure_count >= max_sensor_failures:
                    logging.warning("Max sensor failures reached. Pausing for 300 seconds.")
                    time.sleep(300)
                    sensor_failure_count = 0
                continue
            else:
                sensor_failure_count = 0

            temperature_readings.append(temperature)
            humidity_readings.append(humidity)

            avg_temperature = moving_average(temperature_readings, config["moving_average_window"])
            avg_humidity = moving_average(humidity_readings, config["moving_average_window"])

            if avg_temperature is not None and avg_humidity is not None:
                logging.info(
                    f"Avg Temp: {avg_temperature:.2f}°C, Avg Humidity: {avg_humidity:.2f}%"
                )
                if avg_temperature > config["temperature_threshold"]:
                    logging.warning(
                        f"High temp alert! Avg Temp: {avg_temperature:.2f}°C"
                    )
                    send_webhook(
                        config["webhook_url"],
                        avg_temperature,
                        avg_humidity,
                        config["retry_delay"],
                        config["max_retries"],
                    )
                if avg_humidity < config["humidity_threshold"]:
                    logging.warning(
                        f"Low humidity alert! Avg Humidity: {avg_humidity:.2f}%"
                    )
                    send_webhook(
                        config["webhook_url"],
                        avg_temperature,
                        avg_humidity,
                        config["retry_delay"],
                        config["max_retries"],
                    )

                control_actuators(avg_temperature, avg_humidity, vent_fan, water_pump, heater)
            else:
                logging.warning("No valid data for moving average.")

            for _ in range(60):
                if not running:
                    break
                time.sleep(1)

    except Exception as e:
        logging.error(f"Unexpected error in main loop: {e}")
    finally:
        cleanup()


if __name__ == "__main__":
    main()

