        logging.error(f"Failed to initialize DHT22: {e}. Simulating sensor data.")
        dht_device = None

    temperature_readings = deque(maxlen=config["moving_average_window"])
    humidity_readings = deque(maxlen=config["moving_average_window"])
    sensor_failure_count = 0
    max_sensor_failures = 3

    try:
