            except DatabaseError as e:
                logging.error(f"Database logging failed: {e}")

            logging.info(
                f"Data: temp={temperature:.2f}°C, "
                f"humidity={humidity:.2f}%, light={light_level}, "
                f"fan={fan_state}, light={light_state}"
            )

            # Sleep in small increments so signals are caught promptly
            slept = 0
            while slept < args.interval and running:
                time.sleep(1)
                slept += 1

    except Exception as e:
        logging.critical(f"Unhandled exception: {e}", exc_info=True)
    finally:
        logging.info("Cleaning up resources...")
        if dht_device is not None:
            try:
                dht_device.exit()
            except Exception:
                pass
        if fan_led is not None:
            try:
                fan_led.close()
            except Exception:
                pass
        if light_led is not None:
            try:
                light_led.close()
            except Exception:
                pass
        logging.info("Shutdown complete.")


if __name__ == "__main__":
    main()

