import time
import board
import busio
import adafruit_bmp280

# Constants
I2C_ADDRESS = 0x76  # Default I2C address for BMP280 (SDO tied to GND)
BASELINE_DURATION = 10  # Seconds to collect baseline pressure
READ_INTERVAL = 1  # Seconds between readings


def get_i2c_bus():
    """Initialize and return the I2C bus object."""
    try:
        return busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Failed to initialize I2C bus: {e}")
        return None


def initialize_bmp280(i2c_bus):
    """Initialize the BMP280 sensor and verify its presence."""
    try:
        sensor = adafruit_bmp280.Adafruit_BMP280_I2C(i2c_bus, address=I2C_ADDRESS)
        # Configure for standard weather monitoring (1x oversampling, 100ms standby)
        sensor.sea_level_pressure = 1013.25
        sensor.mode = adafruit_bmp280.MODE_NORMAL
        sensor.overscan_pressure = adafruit_bmp280.OVERSCAN_X1
        sensor.overscan_temperature = adafruit_bmp280.OVERSCAN_X1
        sensor.standby_period = adafruit_bmp280.STANDBY_1000
        return sensor
    except ValueError:
        print(f"BMP280 not found at I2C address 0x{I2C_ADDRESS:02X}. Check wiring and address.")
        return None
    except Exception as e:
        print(f"Failed to initialize BMP280: {e}")
        return None


def get_baseline_pressure(sensor, duration):
    """Collect baseline pressure readings and return the average, excluding the first 2 readings."""
    print(f"Collecting baseline pressure for {duration} seconds. Keep the sensor still!")
    readings = []
    for i in range(duration):
        try:
            pressure = sensor.pressure
            readings.append(pressure)
            print(f"  Reading {i+1}/{duration}: {pressure:.2f} hPa")
            time.sleep(READ_INTERVAL)
        except OSError as e:
            print(f"  Error reading pressure during baseline: {e}")
            time.sleep(READ_INTERVAL)
        except Exception as e:
            print(f"  Unexpected error reading pressure: {e}")
            time.sleep(READ_INTERVAL)

    if not readings:
        print("No valid pressure readings collected. Cannot calculate baseline.")
        return None

    # Exclude the first 2 readings to avoid early sensor instability
    valid_readings = readings[2:]
    if not valid_readings:
        print("Insufficient valid readings after excluding first 2. Cannot calculate baseline.")
        return None

    baseline = sum(valid_readings) / len(valid_readings)
    print(f"\nBaseline pressure established: {baseline:.2f} hPa")
    return baseline


def get_altitude(sensor):
    """Read and return the relative altitude in meters."""
    try:
        # adafruit_bmp280 uses sea_level_pressure for altitude calculation
        altitude = sensor.altitude
        return altitude
    except OSError as e:
        print(f"Error reading altitude: {e}")
        return None
    except Exception as e:
        print(f"Unexpected error reading altitude: {e}")
        return None


def main():
    """Main function to initialize, collect baseline, and continuously read altitude."""
    i2c_bus = get_i2c_bus()
    if i2c_bus is None:
        return

    sensor = initialize_bmp280(i2c_bus)
    if sensor is None:
        return

    baseline = get_baseline_pressure(sensor, BASELINE_DURATION)
    if baseline is None:
        return

    print("\nStarting continuous altitude readings. Press Ctrl+C to exit.")
    while True:
        altitude = get_altitude(sensor)
        if altitude is not None:
            print(f"Relative altitude: {altitude:.2f} meters")
        time.sleep(READ_INTERVAL)


if __name__ == "__main__":
    try:
        main()
    except KeyboardInterrupt:
        print("\nExiting program.")

