        try:
            pressure = sensor.pressure
            readings.append(pressure)
            print(f"  Reading {i+1}/{duration}: {pressure:.2f} hPa")
            time.sleep(READ_INTERVAL)
        except OSError as e:
            print(f"  Error reading pressure during baseline: {e}")
            time.sleep(READ_INTERVAL)
        except Exception as e:
            print(f"  Unexpected error reading pressure: {e}")
            time.sleep(READ_INTERVAL)

    if not readings:
        print("No valid pressure readings collected. Cannot calculate baseline.")
        return None

    # Exclude the first 2 readings to avoid early sensor instability
    valid_readings = readings[2:]
    if not valid_readings:
        print("Insufficient valid readings after excluding first 2. Cannot calculate baseline.")
        return None

    baseline = sum(valid_readings) / len(valid_readings)
    print(f"\nBaseline pressure established: {baseline:.2f} hPa")
    return baseline


