import time
import logging
import signal
import sys
from typing import Tuple, Optional

import smbus2

logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)


class DHT20:
    """Driver for the Aosong DHT20 I2C temperature/humidity sensor."""

    DHT20_I2C_ADDRESS = 0x38
    DHT20_STATUS_REG = 0x71
    DHT20_MEASURE_REG = 0xAC
    DHT20_MEASURE_CMD = [0x33, 0x00]

    def __init__(self, i2c_bus: int = 1):
        self.i2c_bus = i2c_bus
        self.bus: Optional[smbus2.SMBus] = None
        self._last_read_time: float = 0.0
        self._min_interval = 2.0
        self._max_retries = 5
        self._measure_retries = 10
        self._timeout = 0.8
        self._busy_timeout = 0.8
        self._retry_delay = 0.01
        self._busy_poll_delay = 0.08

    # -- context manager -------------------------------------------------

    def __enter__(self):
        if not self.begin():
            raise RuntimeError('DHT20: I2C bus initialization failed')
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        self.close()
        return False

    # -- public API ------------------------------------------------------

    def begin(self) -> bool:
        """Open the I2C bus and verify the DHT20 is ready."""
        try:
            self.bus = smbus2.SMBus(self.i2c_bus)
        except OSError as e:
            logging.error('Failed to open I2C bus %d: %s', self.i2c_bus, e)
            self.bus = None
            return False

        time.sleep(0.5)  # DHT20 requires >0.5 s after power-on

        try:
            status = self._read_register(self.DHT20_STATUS_REG, 1)[0]
        except OSError as e:
            logging.error('DHT20 status read failed: %s', e)
            self.close()
            return False

        if (status & 0x18) != 0x18:
            logging.error(
                'DHT20 status 0x%02X does not match expected 0x18 (0x18|0x00|0x08)',
                status
            )
            self.close()
            return False

        logging.info('DHT20 initialized at address 0x%02X on bus %d',
                     self.DHT20_I2C_ADDRESS, self.i2c_bus)
        return True

    def close(self):
        """Release the I2C bus handle."""
        if self.bus is not None:
            try:
                self.bus.close()
            except OSError as e:
                logging.warning('Error closing I2C bus: %s', e)
            finally:
                self.bus = None

    def get_temperature_and_humidity(
        self,
        humidity_precision: int = 2,
        temperature_precision: int = 2,
    ) -> Tuple[Optional[float], Optional[float], bool]:
        """
        Return (temperature_celsius, humidity_percent, error_flag).

        Retries up to self._max_retries times.  If all attempts fail,
        returns (None, None, True).
        """
        now = time.time()
        if now - self._last_read_time < self._min_interval:
            logging.debug('Rate-limit: %.1f s elapsed since last read',
                          now - self._last_read_time)
            return self._last_read_temp, self._last_read_humidity, True

        self._last_read_time = now

        for attempt in range(1, self._max_retries + 1):
            try:
                temp, hum, crc_err = self._measure_and_read(
                    humidity_precision, temperature_precision
                )
                if crc_err:
                    logging.warning('CRC mismatch on attempt %d/%d', attempt, self._max_retries)
                    time.sleep(self._retry_delay)
                    continue
                return temp, hum, False
            except OSError as e:
                logging.error('I2C error on attempt %d/%d: %s', attempt, self._max_retries, e)
                time.sleep(self._retry_delay)
            except Exception as e:
                logging.error('Unexpected error on attempt %d/%d: %s', attempt, self._max_retries, e)
                time.sleep(self._retry_delay)

        logging.error('All %d measurement attempts failed', self._max_retries)
        return None, None, True

    @property
    def temperature(self) -> Optional[float]:
        """Last successfully read temperature in degrees Celsius."""
        return self._last_read_temp

    @property
    def humidity(self) -> Optional[float]:
        """Last successfully read relative humidity in percent."""
        return self._last_read_humidity

    @property
    def error(self) -> bool:
        """True if the last measurement attempt failed."""
        return bool(self._last_error)

    # -- internal helpers ------------------------------------------------

    def _measure_and_read(
        self,
        humidity_precision: int,
        temperature_precision: int,
    ) -> Tuple[Optional[float], Optional[float], bool]:
        """Trigger a measurement and read the 7-byte data frame."""
        self._write_register(self.DHT20_MEASURE_REG, self.DHT20_MEASURE_CMD)

        # Poll status until bit 7 (busy) clears or timeout
        for _ in range(int(self._busy_poll_delay / self._busy_poll_delay)):
            try:
                status = self._read_register(self.DHT20_STATUS_REG, 1)[0]
            except OSError as e:
                logging.error('Busy-poll I2C error: %s', e)
                return None, None, True
            if (status & 0x80) == 0:
                break
            time.sleep(self._busy_poll_delay)
        else:
            logging.warning('DHT20 busy-out timeout')
            return None, None, True

        try:
            data = self._read_register(self.DHT20_STATUS_REG, 7)
        except OSError as e:
            logging.error('Failed to read measurement data: %s', e)
            return None, None, True

        if len(data) < 7:
            logging.error('Short read: got %d bytes, expected 7', len(data))
            return None, None, True

        # CRC-8, poly 0x31, init 0xFF, no final XOR
        crc_err = (data[6] & 0xFF) != self._calculate_crc8(data[:6])
        if crc_err:
            logging.warning('CRC mismatch: calculated 0x%02X, received 0x%02X',
                            self._calculate_crc8(data[:6]), data[6])
            return None, None, True

        # Humidity: bits [19:12] of the 20-bit raw value
        raw_h = ((data[1] << 12) | (data[2] << 4) | ((data[3] & 0xF0) >> 4))
        humidity = raw_h / (1 << 20) * 100.0

        # Temperature: bits [19:4] of the 20-bit raw value
        raw_t = (((data[3] & 0x0F) << 16) | (data[4] << 8) | data[5])
        temperature = raw_t / (1 << 19) * 200.0 - 50.0

        self._last_read_temp = temperature
        self._last_read_humidity = humidity
        self._last_error = False
        return temperature, humidity, False

    @staticmethod
    def _calculate_crc8(data: bytes) -> int:
        crc = 0xFF
        for byte in data:
            crc ^= byte
            for _ in range(8):
                if crc & 0x80:
                    crc = ((crc << 1) ^ 0x31) & 0xFF
                else:
                    crc = (crc << 1) & 0xFF
        return crc

    def _write_register(self, register: int, data: list) -> None:
        if self.bus is None:
            raise RuntimeError('I2C bus not initialized')
        try:
            self.bus.write_i2c_block_data(self.DHT20_I2C_ADDRESS, register, data)
        except OSError as e:
            raise OSError(f'I2C write to register 0x{register:02X} failed: {e}') from e

    def _read_register(self, register: int, length: int) -> bytes:
        if self.bus is None:
            raise RuntimeError('I2C bus not initialized')
        try:
            return self.bus.read_i2c_block_data(self.DHT20_I2C_ADDRESS, register, length)
        except OSError as e:
            raise OSError(f'I2C read from register 0x{register:02X} failed: {e}') from e


# ---------------------------------------------------------------------------
# Demo / smoke test
# ---------------------------------------------------------------------------

_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False


def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        with DHT20(i2c_bus=1) as sensor:
            if not sensor.begin():
                print('DHT20 initialization failed. Check wiring and I2C address.')
                sys.exit(0)

            while _running:
                temp, hum, err = sensor.get_temperature_and_humidity(
                    humidity_precision=2, temperature_precision=2
                )
                if err or temp is None or hum is None:
                    logging.warning('Read failed: %s', ','.join(str(x) for x in (temp, hum, err)))
                else:
                    logging.info('Temperature: %.2f C  Humidity: %.2f %%', temp, hum)
                time.sleep(2.0)
    except KeyboardInterrupt:
        pass
    except SystemExit:
        raise
    except Exception as e:
        logging.error('Fatal error: %s', e)
        sys.exit(1)


if __name__ == '__main__':
    main()

