import time
import logging
import board
import adafruit_dht

# Configure logging to file and console
logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s',
    handlers=[
        logging.FileHandler('wildlife_monitoring.log'),
        logging.StreamHandler()
    ]
)

# Define GPIO pins for DHT22 sensors (BCM numbering)
DHT_PINS = [board.D4, board.D17]

# Anomaly thresholds
TEMP_MIN = 5.0
TEMP_MAX = 35.0
HUMIDITY_MAX = 90.0

# Retry configuration
MAX_RETRIES = 3
RETRY_DELAY = 2  # seconds


def read_dht22(pin):
    """
    Reads temperature and humidity from a DHT22 sensor.
    Implements retry logic with exponential backoff.
    Returns (temperature, humidity) or (None, None) on failure.
    """
    dht_device = None
    try:
        dht_device = adafruit_dht.DHT22(pin, use_pulseio=False)
    except Exception as e:
        logging.error(f"Failed to initialize DHT22 on pin {pin}: {e}")
        return None, None

    for attempt in range(1, MAX_RETRIES + 1):
        try:
            temperature = dht_device.temperature
            humidity = dht_device.humidity
            if temperature is not None and humidity is not None:
                return temperature, humidity
            else:
                logging.warning(f"Pin {pin}: DHT22 returned None values (attempt {attempt}/{MAX_RETRIES})")
        except RuntimeError as e:
            logging.warning(f"Pin {pin}: DHT22 read error (attempt {attempt}/{MAX_RETRIES}): {e}")
        except Exception as e:
            logging.error(f"Pin {pin}: Unexpected error during read (attempt {attempt}/{MAX_RETRIES}): {e}")

        if attempt < MAX_RETRIES:
            time.sleep(RETRY_DELAY * (2 ** (MAX_RETRIES - attempt)))

    logging.error(f"Pin {pin}: Failed to read DHT22 after {MAX_RETRIES} attempts")
    return None, None


def check_anomalies(temperature, humidity, pin):
    """
    Checks if temperature or humidity values are anomalous.
    Returns a list of anomaly strings.
    """
    anomalies = []
    if temperature is not None:
        if temperature > TEMP_MAX:
            anomalies.append(f"Temperature: {temperature:.1f}°C (threshold: {TEMP_MAX}°C)")
        elif temperature < TEMP_MIN:
            anomalies.append(f"Temperature: {temperature:.1f}°C (threshold: {TEMP_MIN}°C)")

    if humidity is not None:
        if humidity > HUMIDITY_MAX:
            anomalies.append(f"Humidity: {humidity:.1f}% (threshold: {HUMIDITY_MAX}%)")

    return anomalies


def log_anomaly(anomaly_type, value, pin):
    """Logs an anomaly to the console and file."""
    timestamp = time.strftime('%Y-%m-%dT%H:%M:%S')
    log_message = f"Anomaly: {anomaly_type}, Value: {value}, Pin: {pin}, Timestamp: {timestamp}"
    logging.error(log_message)


def main():
    """Main function to read sensors, check for anomalies, and log them."""
    try:
        while True:
            for pin in DHT_PINS:
                temperature, humidity = read_dht22(pin)

                if temperature is not None and humidity is not None:
                    timestamp = time.strftime('%Y-%m-%dT%H:%M:%S')
                    log_message = f"Temperature: {temperature:.1f}°C, Humidity: {humidity:.1f}%, Pin: {pin}, Timestamp: {timestamp}"
                    logging.info(log_message)

                    anomalies = check_anomalies(temperature, humidity, pin)
                    if anomalies:
                        for anomaly in anomalies:
                            log_anomaly(anomaly.split(':')[0], anomaly.split(':')[1], pin)

            time.sleep(60)  # Read every 60 seconds

    except KeyboardInterrupt:
        print("Program terminated by user.")
        logging.info("Program terminated by user.")
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        # Clean up DHT22 devices if they were initialized
        for pin in DHT_PINS:
            try:
                dht_device = adafruit_dht.DHT22(pin, use_pulseio=False)
                if dht_device.is_initialized:
                    dht_device.exit()
            except Exception:
                pass


if __name__ == "__main__":
    main()

