import signal
import sys
import time
import logging
from functools import partial

from gpiozero import PWMOutputDevice

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)
logger = logging.getLogger(__name__)


class FanController:
    """Controls a 4-pin PWM fan on a Raspberry Pi based on CPU temperature."""

    def __init__(
        self,
        fan_pin: int = 14,
        pwm_frequency: int = 100,
        temp_check_interval: float = 5.0,
        temp_thresholds: dict = None,
        temp_sources: list = None,
    ):
        self.fan_pin = fan_pin
        self.pwm_frequency = pwm_frequency
        self.temp_check_interval = temp_check_interval
        self.temp_thresholds = temp_thresholds or {
            70: 100,
            60: 85,
            50: 70,
            40: 50,
            32: 25,
            25: 15,
        }
        self.temp_sources = temp_sources if temp_sources else [self._read_temp_via_vcgencmd, self._read_temp_via_sysfs]
        self._running = True

        try:
            self.fan = PWMOutputDevice(
                pin=fan_pin,
                frequency=pwm_frequency,
                initial_value=0.0,
            )
        except Exception as exc:
            logger.critical("Failed to initialize PWM on GPIO%d: %s", fan_pin, exc)
            raise

        self._set_fan_speed = partial(self.set_fan_speed, self.fan)
        logger.info(
            "FanController initialized on GPIO%d @ %d Hz. Checking every %.1fs.",
            fan_pin,
            pwm_frequency,
            self.temp_check_interval,
        )

    def _read_temp_via_vcgencmd(self) -> float:
        """Read CPU temperature via vcgencmd measure_temp."""
        try:
            output = run_command(["vcgencmd", "measure_temp"], timeout=5)
            return float(output.split("=")[1].split("'")[0])
        except Exception as exc:
            logger.error("vcgencmd failed: %s", exc)
            return None

    def _read_temp_via_sysfs(self) -> float:
        """Read CPU temperature via /sys/class/thermal/thermal_zone0/temp."""
        try:
            with open("/sys/class/thermal/thermal_zone0/temp", "r") as f:
                return float(f.read().strip()) / 1000.0
        except Exception as exc:
            logger.error("sysfs read failed: %s", exc)
            return None

    def read_cpu_temperature(self) -> float | None:
        """Read CPU temperature from any available source."""
        for source in self.temp_sources:
            temp = source()
            if temp is not None:
                return temp
        return None

    def set_fan_speed(self, fan, duty_cycle: float):
        """Set fan duty cycle (0.0 to 1.0)."""
        try:
            fan.value = duty_cycle / 100.0
            logger.debug("Fan speed set to %.1f%%", duty_cycle)
        except Exception as exc:
            logger.error("Failed to set fan speed: %s", exc)

    def run(self):
        """Main control loop."""
        logger.info("Starting fan control loop.")
        while self._running:
            temp = self.read_cpu_temperature()
            if temp is not None:
                logger.info("CPU Temp: %.1f°C", temp)
                self._set_fan_speed(temp)
            else:
                logger.warning("Temperature read failed; keeping current fan speed.")
            time.sleep(self.temp_check_interval)

    def stop(self):
        """Stop the control loop and release GPIO resources."""
        self._running = False
        try:
            self.fan.value = 0.0
            self.fan.close()
            logger.info("Fan stopped and GPIO released.")
        except Exception as exc:
            logger.error("Error during cleanup: %s", exc)


def run_command(command: list, timeout: int = 10) -> str:
    """Execute a command and return its stdout, raising on timeout."""
    try:
        process = subprocess.Popen(
            command,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
        )
        end = time.time() + timeout
        while process.poll() is None and time.time() < end:
            line = process.stdout.readline()
            if line:
                return line.strip()
            time.sleep(0.1)
        if process.poll() is None:
            raise subprocess.TimeoutExpired(timeout, process)
        return process.stdout.read().strip()
    except subprocess.TimeoutExpired:
        raise
    except Exception as exc:
        raise RuntimeError(f"Command failed: {command} - {exc}") from exc


def _signal_handler(signum, frame, controller: FanController):
    logger.info("Signal %d received, shutting down.", signum)
    controller.stop()
    sys.exit(0)


def main():
    controller = FanController()
    signal.signal(signal.SIGINT, lambda s, f: _signal_handler(s, f, controller))
    signal.signal(signal.SIGTERM, lambda s, f: _signal_handler(s, f, controller))
    controller.run()


if __name__ == "__main__":
    main()

