import config
import signal
import sys
import time
import logging

import paho.mqtt.client as mqtt
import adafruit_dht
import board

logging.basicConfig(level=logging.INFO, format="%(asctime)s [%(levelname)s] %(message)s")
log = logging.getLogger("dht22_mqtt")

DEGREE_CELSIUS = "\u00B0C"
HOMIE_VERSION = "4.0"

running = True
client = None
dht_device = None


def signal_handler(signum, frame):
    global running
    log.info("Signal %s received, shutting down...", signum)
    running = False


def on_connect(client, userdata, flags, reason_code, properties):
    if reason_code == 0:
        log.info("Connected to MQTT broker")
    else:
        log.error("MQTT connection failed with reason code %s", reason_code)


def on_disconnect(client, userdata, flags, reason_code, properties):
    if reason_code != 0:
        log.warning("Unexpected MQTT disconnect (code %s); client will auto-reconnect", reason_code)
    else:
        log.info("MQTT disconnected cleanly")


def publish(client, topic, payload, qos=1):
    full_topic = f"homie/{config.homieclientid}/{topic}"
    info = client.publish(full_topic, str(payload), qos=qos)
    info.wait_for_publish(timeout=5)
    if info.rc != mqtt.MQTT_ERR_SUCCESS:
        log.error("Publish failed to %s (rc=%s)", full_topic, info.rc)


def read_dht22():
    global dht_device
    try:
        pin = getattr(board, f"D{config.dhtgpiopin}")
    except AttributeError:
        log.error("Board pin D%s not found", config.dhtgpiopin)
        return None, None
    try:
        dht_device = adafruit_dht.DHT22(pin, use_pulseio=False)
    except Exception as exc:
        log.error("Failed to initialise DHT22 on pin %s: %s", config.dhtgpiopin, exc)
        return None, None
    for attempt in range(3):
        try:
            temperature = dht_device.temperature
            humidity = dht_device.humidity
            if temperature is not None and humidity is not None:
                return temperature, humidity
        except RuntimeError as exc:
            log.warning("DHT22 read attempt %d failed: %s", attempt + 1, exc)
        except Exception as exc:
            log.error("Unexpected DHT22 error: %s", exc)
            break
        time.sleep(2.0)
    return None, None


def main():
    global client
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        client = mqtt.Client(
            mqtt.CallbackAPIVersion.VERSION2,
            client_id=config.mqttclientid,
            clean_session=True,
        )
        client.username_pw_set(config.mqttusername, config.mqttpassword)
        client.on_connect = on_connect
        client.on_disconnect = on_disconnect
        client.will_set(
            f"homie/{config.homieclientid}/$state",
            payload="lost",
            qos=1,
            retain=True,
        )
        client.connect(config.mqttbroker, port=config.mqttport, keepalive=30)
        client.loop_start()
        time.sleep(1)

        while running:
            temperature, humidity = read_dht22()
            if temperature is not None and humidity is not None:
                log.info("Temperature = %.1f%s, Humidity = %.1f%%", temperature, DEGREE_CELSIUS, humidity)
                publish(client, "temperature", f"{temperature:.1f}")
                publish(client, "humidity", f"{humidity:.1f}")
            else:
                log.error("DHT22 read failed after retries; skipping publish cycle")
            for _ in range(config.publishtime):
                if not running:
                    break
                time.sleep(1)
    except Exception as exc:
        log.exception("Fatal error: %s", exc)
    finally:
        if client is not None:
            try:
                client.loop_stop()
                client.disconnect()
            except Exception:
                pass
        if dht_device is not None:
            try:
                dht_device.exit()
            except Exception:
                pass
        log.info("Cleanup complete")


if __name__ == "__main__":
    main()

