import time
import signal
import sys
from datetime import datetime
from smbus2 import SMBus, i2c_msg

I2C_BUS = 1
I2C_ADDR = 0x38

running = True

def signal_handler(sig, frame):
    global running
    running = False

def crc8(data, init=0xFF, poly=0x31):
    crc = init
    for byte in data:
        crc ^= byte
        for _ in range(8):
            if crc & 0x80:
                crc = ((crc << 1) ^ poly) & 0xFF
            else:
                crc = (crc << 1) & 0xFF
    return crc

def init_sensor(bus):
    try:
        bus.write_byte(I2C_ADDR, 0xBA)
        time.sleep(0.02)
        status = bus.read_byte(I2C_ADDR)
        if not (status & 0x08):
            bus.write_i2c_block_data(I2C_ADDR, 0xBE, [0x08, 0x00])
            time.sleep(0.01)
    except IOError as e:
        raise IOError(f"Sensor init failed: {e}")

def read_sensor(bus):
    try:
        bus.write_i2c_block_data(I2C_ADDR, 0xAC, [0x33, 0x00])
        time.sleep(0.08)
        data = bus.read_i2c_block_data(I2C_ADDR, 0x00, 7)
        if data[0] & 0x80:
            raise IOError("Sensor busy")
        crc_err = (crc8(data[:6]) != data[6])
        if crc_err:
            raise IOError("CRC mismatch")
        raw_temp = ((data[1] << 12) | (data[2] << 4) | (data[3] >> 4)) & 0xFFFFF
        raw_humid = (((data[3] & 0x0F) << 16) | (data[4] << 8) | data[5]) & 0xFFFFF
        temp_c = (raw_temp / 0x100000) * 200.0 - 50.0
        humidity = (raw_humid / 0x100000) * 100.0
        return temp_c, humidity
    except IOError as e:
        raise IOError(f"Sensor read failed: {e}")

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    try:
        bus = SMBus(I2C_BUS)
    except IOError as e:
        print(f"Failed to open I2C bus {I2C_BUS}: {e}", file=sys.stderr)
        sys.exit(1)
    try:
        init_sensor(bus)
        while running:
            try:
                temp_c, humidity = read_sensor(bus)
                temp_f = temp_c * 9.0 / 5.0 + 32.0
                ts = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
                print(f"[{ts}] Temp: {temp_c:.2f}C / {temp_f:.2f}F  Humidity: {humidity:.2f}%")
            except IOError as e:
                print(f"[{datetime.now().strftime('%Y-%m-%d %H:%M:%S')}] Error: {e}", file=sys.stderr)
            for _ in range(5):
                if not running:
                    break
                time.sleep(1)
    finally:
        bus.close()
        print("\nExited cleanly.")

if __name__ == "__main__":
    main()

