        temp_c = (raw_temp / 0x100000) * 200.0 - 50.0
        humidity = (raw_humid / 0x100000) * 100.0
        return temp_c, humidity
    except IOError as e:
        raise IOError(f"Sensor read failed: {e}")

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    try:
        bus = SMBus(I2C_BUS)
    except IOError as e:
        print(f"Failed to open I2C bus {I2C_BUS}: {e}", file=sys.stderr)
        sys.exit(1)
    try:
        init_sensor(bus)
        while running:
            try:
                temp_c, humidity = read_sensor(bus)
                temp_f = temp_c * 9.0 / 5.0 + 32.0
                ts = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
                print(f"[{ts}] Temp: {temp_c:.2f}C / {temp_f:.2f}F  Humidity: {humidity:.2f}%")
            except IOError as e:
                print(f"[{datetime.now().strftime('%Y-%m-%d %H:%M:%S')}] Error: {e}", file=sys.stderr)
            for _ in range(5):
                if not running:
                    break
                time.sleep(1)
    finally:
        bus.close()
        print("\nExited cleanly.")

if __name__ == "__main__":
    main()

