import signal
import RPi.GPIO as GPIO
import DOG

# Constants
DEFAULT_LOG_FILE = "data.log"
PROMPT = "JAYES@ROVER53:\t"

# Global variables
server_running = False
log_file_path = DEFAULT_LOG_FILE
receive_thread = None

# GPIO setup
GPIO.setwarnings(False)
GPIO.setmode(GPIO.BCM)

def signal_handler(sig, frame):
    """Handles SIGINT and SIGTERM for clean shutdown."""
    global server_running
    print("\nShutting down...")
    server_running = False
    if receive_thread is not None and receive_thread.is_alive():
        receive_thread.join(timeout=1.0)
    GPIO.cleanup()
    sys.exit(0)

def help_commands():
    """Displays help information."""
    print("Available commands:")
    print("  help [command]        Displays help information")
    print("  start <filename>     Starts the server and logs data to the specified file")
    print("  stop                 Stops the server")
    print("  display              Displays the contents of the log file")
    print("  send <data>          Sends data using DOG.send()")
    print("  write <data>         Writes data directly to the log file")
    print("  exit                Stops the server and exits")

def receive_loop():
    """Continuously receives data and writes it to the log file."""
    global server_running
    try:
        while server_running:
            try:
                data = DOG.receive()
                if data:
                    with open(log_file_path, "a") as f:
                        f.write(data + "\n")
            except Exception as e:
                print(f"Error in receive loop: {e}")
                server_running = False
                break
            time.sleep(0.1)
    except Exception as e:
        print(f"Fatal error in receive loop: {e}")
        server_running = False

def start_server(filename):
    """Starts the server and logs data to the specified file."""
    global server_running, log_file_path, receive_thread
    try:
        log_file_path = filename
        with open(log_file_path, "a") as f:
            pass
        server_running = True
        receive_thread = threading.Thread(target=receive_loop, daemon=True)
        receive_thread.start()
        print(f"Server started. Logging to {log_file_path}")
    except Exception as e:
        print(f"Error starting server: {e}")

def stop_server():
    """Stops the server and cleans up GPIO."""
    global server_running
    if server_running:
        server_running = False
        if receive_thread is not None and receive_thread.is_alive():
            receive_thread.join(timeout=1.0)
    GPIO.cleanup()
    print("Server stopped.")

def display_log():
    """Displays the contents of the log file."""
    try:
        with open(log_file_path, "r") as f:
            print(f.read())
    except FileNotFoundError:
        print("Log file not found.")
    except Exception as e:
        print(f"Error displaying log: {e}")

def send_data(data):
    """Sends data using DOG.send()."""
    try:
        DOG.send(data)
        print(f"Sent: {data}")
    except Exception as e:
        print(f"Error sending data: {e}")

def write_to_log(data):
    """Writes data directly to the log file with a newline character."""
    try:
        with open(log_file_path, "a") as f:
            f.write(data + "\n")
        print(f"Wrote to log: {data}")
    except Exception as e:
        print(f"Error writing to log: {e}")

def process_command(command):
    """Processes user commands."""
    parts = command.split()
    if not parts:
        return

    cmd = parts[0].lower()

    if cmd == "help":
        if len(parts) == 2:
            help_commands()
        else:
            print("Usage: help [command]")
    elif cmd == "start":
        if len(parts) == 2:
            start_server(parts[1])
        else:
            print("Usage: start <filename>")
    elif cmd == "stop":
        stop_server()
    elif cmd == "display":
        display_log()
    elif cmd == "send":
        if len(parts) == 2:
            send_data(parts[1])
        else:
            print("Usage: send <data>")
    elif cmd == "write":
        if len(parts) == 2:
            write_to_log(parts[1])
        else:
            print("Usage: write <data>")
    elif cmd == "exit":
        stop_server()
        sys.exit(0)
    else:
        print("Invalid command. Type 'help' for available commands.")

def main():
    """Main function to run the server."""
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    print("Starting DOGServer...")
    print("Type 'help' for available commands.")

    try:
        while True:
            try:
                command = input(PROMPT).strip()
                process_command(command)
            except EOFError:
                print("\nEOF received. Exiting.")
                break
            except Exception as e:
                print(f"An error occurred: {e}")
    finally:
        stop_server()

if __name__ == "__main__":
    main()

