import time
import signal
import sys
import board
import busio
import RPi.GPIO as GPIO
from adafruit_tsl2561 import TSL2561

# --- Configuration -----------------------------------------------------------
LED_PIN = 18
PWM_FREQUENCY = 1000  # Hz
TSL2561_I2C_ADDRESS = 0x39
INTEGRATION_TIME = 0.402  # seconds (402 ms)

# --- Globals for cleanup -----------------------------------------------------
i2c_bus = None
light_sensor = None
pwm_led = None
running = True


def cleanup():
    """Release all hardware resources safely."""
    global pwm_led, i2c_bus
    if pwm_led is not None:
        try:
            pwm_led.stop()
        except Exception:
            pass
        pwm_led = None
    try:
        GPIO.cleanup()
    except Exception:
        pass
    if i2c_bus is not None:
        try:
            i2c_bus.deinit()
        except Exception:
            pass
        i2c_bus = None


def signal_handler(signum, frame):
    """Handle SIGINT / SIGTERM for graceful shutdown."""
    global running
    running = False


def init_hardware():
    """Initialize I2C bus, TSL2561 sensor, and GPIO PWM. Returns (lux_sensor, pwm)."""
    global i2c_bus, light_sensor, pwm_led

    # --- I2C bus -------------------------------------------------------------
    try:
        i2c_bus = busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"FATAL: Failed to initialize I2C bus: {e}")
        sys.exit(1)

    # --- TSL2561 sensor -----------------------------------------------------
    try:
        light_sensor = TSL2561(i2c_bus, address=TSL2561_I2C_ADDRESS)
        light_sensor.gain = 1  # auto-gain
        light_sensor.integration_time = INTEGRATION_TIME
    except Exception as e:
        print(f"FATAL: TSL2561 not detected at 0x{TSL2561_I2C_ADDRESS:02X}: {e}")
        cleanup()
        sys.exit(1)

    # --- GPIO PWM ------------------------------------------------------------
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(LED_PIN, GPIO.OUT)
        pwm_led = GPIO.PWM(LED_PIN, PWM_FREQUENCY)
        pwm_led.start(0)
    except Exception as e:
        print(f"FATAL: Failed to initialize GPIO PWM on pin {LED_PIN}: {e}")
        cleanup()
        sys.exit(1)

    return light_sensor, pwm_led


def lux_to_brightness(lux):
    """Map lux to a 0-100 brightness percentage, clamped."""
    if lux <= 0:
        return 0
    if lux >= 1000:
        return 100
    return int((lux / 1000.0) * 100)


def main_loop(light_sensor, pwm_led):
    """Continuously read light and update PWM duty cycle every 1 second."""
    global running
    while running:
        try:
            lux = light_sensor.lux
            if lux is None:
                print("Warning: Sensor returned None (saturation or not ready).")
            else:
                brightness = lux_to_brightness(lux)
                pwm_led.ChangeDutyCycle(brightness)
                print(f"Lux: {lux:.2f}, Brightness: {brightness}%")
        except Exception as e:
            print(f"Error reading light sensor: {e}")
        time.sleep(1)


def main():
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    light_sensor, pwm_led = init_hardware()
    try:
        main_loop(light_sensor, pwm_led)
    except Exception as e:
        print(f"Unexpected error in main loop: {e}")
    finally:
        cleanup()


if __name__ == "__main__":
    main()

