import signal
import sys
from flask import Flask, render_template_string
from gpiozero import LED
from gpiozero.exc import GPIOZeroError, BadPinFactory

app = Flask(__name__)

LED_PIN = 17
led = None

HTML_INDEX = """
<h1>Light Control</h1>
<a href="/light_on">Turn ON</a> | <a href="/light_off">Turn OFF</a>
"""

HTML_ON = """
<h1>Light ON</h1>
<a href="/">Back</a>
"""

HTML_OFF = """
<h1>Light OFF</h1>
<a href="/">Back</a>
"""

HTML_ERROR = """
<h1>Error</h1>
<p>GPIO initialization failed. Ensure this is running on a Raspberry Pi.</p>
<a href="/">Back</a>
"""


def init_gpio():
    """Initialize the LED on GPIO 17 using gpiozero."""
    global led
    try:
        led = LED(LED_PIN)
        print(f"LED initialized on GPIO {LED_PIN} (BCM).")
    except BadPinFactory:
        print("Error: No GPIO pin factory available. Are you running on a Raspberry Pi?")
        led = None
    except GPIOZeroError as e:
        print(f"Error initializing GPIO: {e}")
        led = None
    except Exception as e:
        print(f"Unexpected error during GPIO init: {e}")
        led = None


def cleanup(signum=None, frame=None):
    """Release GPIO resources on exit."""
    global led
    if led is not None:
        try:
            led.close()
            print("LED resource released.")
        except Exception as e:
            print(f"Error closing LED: {e}")
        finally:
            led = None
    if signum is not None:
        sys.exit(0)


@app.route('/')
def index_page():
    if led is None:
        return render_template_string(HTML_ERROR), 503
    return render_template_string(HTML_INDEX)


@app.route('/light_on')
def light_on():
    if led is None:
        return render_template_string(HTML_ERROR), 503
    try:
        led.on()
        return render_template_string(HTML_ON)
    except GPIOZeroError as e:
        print(f"Error turning LED on: {e}")
        return render_template_string(HTML_ERROR), 500


@app.route('/light_off')
def light_off():
    if led is None:
        return render_template_string(HTML_ERROR), 503
    try:
