#!/usr/bin/python3

"""
GPIO control classes for Raspberry Pi using pigpio.

OutputPin: hardware-safe GPIO output with state tracking and clean shutdown.
TriggerPin: pigpio hardware PWM output for precise pulse generation.
"""

import signal
import sys
import threading
import pigpio


class OutputPin:
    """Hardware-safe GPIO output pin with state tracking and clean shutdown."""

    def __init__(self, pin, value_list=(0, 1), initial_value=None,
                 pigp=None):
        if pigp is None:
            pigp = pigpio.pi()
        if not pigp.connected:
            raise RuntimeError("pigpio daemon not connected")

        self.pin = pin
        self.value_list = value_list
        self.current_value = None

        if initial_value is None:
            initial_value = value_list[0]
        if initial_value not in value_list:
            raise ValueError(f"initial_value {initial_value} not in value_list {value_list}")

        try:
            pigp.set_mode(pin, pigpio.OUTPUT)
            pigp.write(pin, initial_value)
        except pigpio.error as e:
            pigp.stop()
            raise RuntimeError(f"Failed to initialize GPIO {pin}: {e}") from e

        self.pigp = pigp
        self._closed = False

    def set_value(self, value):
        if self._closed:
            raise RuntimeError(f"Pin {self.pin} is closed")
        if value not in self.value_list:
            raise ValueError(f"Value {value} not in value_list {self.value_list}")
        try:
            self.pigp.write(self.pin, value)
            self.current_value = value
        except pigpio.error as e:
            raise RuntimeError(f"Failed to write to GPIO {self.pin}: {e}") from e

    def get_value(self):
        return self.current_value

    def shutdown(self):
        if self._closed:
            return
        self._closed = True
        try:
            self.pigp.set_mode(self.pin, pigpio.INPUT)
        except pigpio.error as e:
            print(f"Warning: failed to set GPIO {self.pin} to input: {e}", file=sys.stderr)

    def __repr__(self):
        return f"OutputPin(pin={self.pin}, value={self.current_value})"


class TriggerPin(OutputPin):
    """GPIO output pin with hardware PWM for precise pulse generation."""

    def __init__(self, pin, pulse_duration, pulse_high=True,
                 pigp=None):
        if pulse_duration <= 0:
            raise ValueError("pulse_duration must be positive")
        super().__init__(pin, value_list=(0, 1), initial_value=0, pigp=pigp)
        self.pulse_duration = pulse_duration
        self.pulse_high = pulse_high
        self.pulse_lock = threading.Lock()
        self._closed = False

    def trigger(self):
        if self._closed:
            raise RuntimeError(f"Pin {self.pin} is closed")
        with self.pulse_lock:
            if self._closed:
                return
            try:
                if self.pulse_high:
                    self.pigp.write(self.pin, 1)
                    self.pigp.hardware_PWM(self.pin, 1000000, self.pulse_duration)
                else:
                    self.pigp.hardware_PWM(self.pin, 1000000, self.pulse_duration)
                    self.pigp.write(self.pin, 0)
            except pigpio.error as e:
                raise RuntimeError(f"Failed to trigger GPIO {self.pin}: {e}") from e

    def shutdown(self):
        if self._closed:
            return
        self._closed = True
        try:
            self.pigp.set_mode(self.pin, pigpio.INPUT)
        except pigpio.error as e:
            print(f"Warning: failed to set GPIO {self.pin} to input: {e}", file=sys.stderr)

    def __repr__(self):
        return f"TriggerPin(pin={self.pin}, pulse_duration={self.pulse_duration}, " \
               f"pulse_high={self.pulse_high})"


# --- Example usage and signal handling ---

_output = None
_trigger = None


def _cleanup(signum=None, frame=None):
    global _output, _trigger
    if _output is not None:
        _output.shutdown()
    if _trigger is not None:
        _trigger.shutdown()
    if signum is not None:
        sys.exit(0)


def main():
    global _output, _trigger

    signal.signal(signal.SIGINT, _cleanup)
    signal.signal(signal.SIGTERM, _cleanup)

    try:
        _output = OutputPin(21, value_list=(0, 1), initial_value=0)
        print(f"OutputPin initialized on GPIO 21: {_output}")

        _trigger = TriggerPin(20, pulse_duration=100, pulse_high=True)
        print(f"TriggerPin initialized on GPIO 20: {_trigger}")

        _trigger.trigger()
        print("Pulse generated on trigger pin.")

        _output.set_value(1)
        print(f"OutputPin set to 1: {_output}")

    except Exception as e:
        print(f"Error: {e}", file=sys.stderr)
    finally:
        _cleanup()


if __name__ == "__main__":
    main()

