import signal
import sys
import time
import logging
import zmq

try:
    from gpiozero import PWMOutputDevice, OutputDevice
    from gpiozero.exc import GPIOZeroError
except ImportError:
    logging.error("gpiozero is required. Install with: pip install gpiozero")
    sys.exit(1)


class PIDHandler:
    """
    Manages PID controllers and error output using gpiozero for GPIO/PWM.

    Physical pin mapping (BOARD numbering):
        - PWM mode (pwm=True):  physical pin 12 (BCM GPIO 18) via PWMOutputDevice
        - Digital mode (pwm=False): physical pin 10 (BCM GPIO 15) via OutputDevice
    """

    def __init__(self, logger=None, pwm=True, watchdog_timeout=20.0):
        self.logger = logger or logging.getLogger(__name__)
        self.pwm = pwm
        self.watchdog_timeout = watchdog_timeout
        self.last_msg = time.time()
        self.global_err_state = False
        self.error_output = None
        self.pwm_output = None
        self._running = True

        # Register signal handlers for clean shutdown
        signal.signal(signal.SIGINT, self._signal_handler)
        signal.signal(signal.SIGTERM, self._signal_handler)

        try:
            if self.pwm:
                self.pwm_output = PWMOutputDevice(
                    pin=12,  # BCM GPIO 18 (physical pin 12)
                    frequency=1000,
                    initial_value=0.0,
                )
                self.logger.info("PWM initialized on BCM GPIO 18 (physical pin 12) at 1000 Hz, 0% duty.")
            else:
                self.error_output = OutputDevice(pin=10, initial_value=False)
                self.logger.info("Digital error output initialized on BCM GPIO 15 (physical pin 10).")
        except GPIOZeroError as e:
            self.logger.error(f"Failed to initialize GPIO: {e}")
            raise
        except Exception as e:
            self.logger.error(f"Unexpected error during GPIO initialization: {e}")
            raise

    def _signal_handler(self, signum, frame):
        self.logger.info(f"Received signal {signum}, shutting down...")
        self._running = False
        self.cleanup()
        sys.exit(0)

    def update_error_output(self):
        """Set the error output based on self.global_err_state."""
        try:
            if self.pwm_output is not None:
                duty = 1.0 if self.global_err_state else 0.0
                self.pwm_output.value = duty
            elif self.error_output is not None:
                self.error_output.value = self.global_err_state
        except GPIOZeroError as e:
            self.logger.error(f"Error updating error output: {e}")

    def set_error_output(self, state):
        """Directly set the error output to a boolean value."""
        try:
            if self.pwm_output is not None:
                self.pwm_output.value = 1.0 if state else 0.0
            elif self.error_output is not None:
                self.error_output.value = state
        except GPIOZeroError as e:
            self.logger.error(f"Error setting error output: {e}")

    def handle_message(self, subscriber_socket, cmd):
        """
        Process incoming ZMQ messages.
        Non-blocking recv: on zmq.EAGAIN, check watchdog; on success, update last_msg.
        """
        try:
            if subscriber_socket.poll(timeout=100):
                try:
                    msg = subscriber_socket.recv(flags=zmq.NOBLOCK)
                    if msg:
                        self.last_msg = time.time()
                        # Placeholder for subscription callback registration
                        self.logger.info(f"Received message: {msg}")
                except zmq.Again:
                    # Watchdog check on timeout
                    if time.time() - self.last_msg > self.watchdog_timeout:
                        self.logger.warning(
                            f"Watchdog timeout ({self.watchdog_timeout}s) triggered. "
                            "Setting error output to True."
                        )
                        self.set_error_output(True)
        except zmq.ZMQError as e:
            self.logger.error(f"ZMQ error in handle_message: {e}")
        except Exception as e:
            self.logger.error(f"Unexpected error in handle_message: {e}")

    def cleanup(self):
        """Release GPIO resources."""
        try:
            if self.pwm_output is not None:
                self.pwm_output.close()
                self.pwm_output = None
            elif self.error_output is not None:
                self.error_output.close()
                self.error_output = None
            self.logger.info("GPIO cleanup complete.")
        except Exception as e:
            self.logger.error(f"Error during cleanup: {e}")

    def __del__(self):
        self.cleanup()

