import time
import board
import busio
import adafruit_fingerprint

# Constants
I2C_ADDR = 0x26
RETRY_DELAY = 1  # seconds between authentication attempts


def initialize_i2c():
    """Initialize the I2C bus on board.SCL / board.SDA."""
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
        return i2c
    except ValueError as e:
        print(f"I2C initialization error (bus locked?): {e}")
        return None
    except Exception as e:
        print(f"I2C initialization error: {e}")
        return None


def initialize_fingerprint_sensor(i2c_bus):
    """Initialize the Adafruit Fingerprint sensor on the given I2C bus."""
    try:
        sensor = adafruit_fingerprint.Adafruit_Fingerprint(i2c_bus, addr=I2C_ADDR)
        return sensor
    except ValueError as e:
        print(f"Fingerprint sensor not found at 0x{I2C_ADDR:02X}: {e}")
        return None
    except RuntimeError as e:
        print(f"Fingerprint sensor initialization error: {e}")
        return None
    except Exception as e:
        print(f"Unexpected error initializing fingerprint sensor: {e}")
        return None


def authenticate_user(sensor):
    """
    Acquire a fingerprint image, create a template, and search the database.
    Returns (access_granted, fingerprint_id, confidence) or (False, None, None).
    """
    try:
        # Acquire an image; sensor may return NOFINGER (0) if no finger is present
        while True:
            image = sensor.get_image()
            if image == adafruit_fingerprint.NOFINGER:
                time.sleep(0.1)
                continue
            break

        # Convert the image to a template
        if sensor.image_2_tz(1) != adafruit_fingerprint.OK:
            print("Error creating template")
            return False, None, None

        # Search the database for a match
        if sensor.finger_search() != adafruit_fingerprint.OK:
            print("No fingerprint detected")
            return False, None, None

        # Return (access_granted, fingerprint_id, confidence)
        return True, sensor.finger_id, sensor.confidence

    except RuntimeError as e:
        print(f"Sensor runtime error during authentication: {e}")
        return False, None, None
    except Exception as e:
        print(f"Unexpected error during authentication: {e}")
        return False, None, None


def main():
    """Main loop: initialize hardware, authenticate until interrupted."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        print("Failed to initialize I2C bus. Exiting.")
        return

    sensor = initialize_fingerprint_sensor(i2c_bus)
    if sensor is None:
        print("Failed to initialize fingerprint sensor. Exiting.")
        try:
            i2c_bus.deinit()
        except Exception:
            pass
        return

    try:
        while True:
            access_granted, fingerprint_id, confidence = authenticate_user(sensor)

            if access_granted:
                print(f"Access Granted: ID={fingerprint_id}, Confidence={confidence}")
            else:
                print("Access Denied: No matching fingerprint found.")

            time.sleep(RETRY_DELAY)

    except KeyboardInterrupt:
        print("\nKeyboardInterrupt received. Exiting program.")
    finally:
        try:
            i2c_bus.deinit()
            print("I2C bus deinitialized.")
        except Exception as e:
            print(f"Error deinitializing I2C bus: {e}")
        print("Program finished.")


if __name__ == "__main__":
    main()

