import logging
import time
from gpiozero import Button
from gpiozero.pins.mock import MockFactory

logging.basicConfig(level=logging.INFO, format="%(asctime)s [%(levelname)s] %(message)s")
logger = logging.getLogger(__name__)


class RotaryEncoder:
    """
    Quadrature rotary encoder reader for Raspberry Pi using gpiozero.

    Pins (BCM numbering):
        CLK  -> GPIO17
        DT   -> GPIO18

    Transition table (4 states, states 0-3):
        Q01 Q02  -> 00 01 11 10  -> states 0 1 2 3
        TRANSITION:
            CW : 00 -> 01 -> 11 -> 10
            CCW: 00 -> 10 -> 10 -> 00
    """

    TRANSITION = {
        (0, 0): {
            "next": (1, 0),
            "dir": 1,
        },
        (1, 0): {
            "next": (0, 1),
            "dir": 1,
        },
        (0, 1): {
            "next": (1, 1),
            "dir": 0,
        },
        (1, 1): {
            "next": (0, 0),
            "dir": 0,
        },
    }

    def __init__(self, clk_pin=17, dt_pin=18, callback=None, bounce_time=0.02):
        self._clk = None
        self._dt = None
        self._callback = callback
        self._bounce_time = bounce_time
        self._counter = 0
        self._last_state = None
        self._last_event_time = 0.0
        self._closed = False

        try:
            factory = Button.pin_factory
            if factory is not None and isinstance(factory, MockFactory):
                logger.warning("Mock pin factory detected; running in simulation mode.")
            self._clk = Button(clk_pin, pull_up=True, bounce_time=bounce_time)
            self._dt = Button(dt_pin, pull_up=True, bounce_time=bounce_time)
        except Exception as exc:
            logger.error("Failed to initialize GPIO pins %d/%d: %s", clk_pin, dt_pin, exc)
            raise

        self._clk.when_activated = self._transition
        self._clk.when_deactivated = self._transition
        self._dt.when_activated = self._transition
        self._dt.when_deactivated = self._transition

        self._last_state = self._read_state()
        logger.info("RotaryEncoder initialized on CLK=%d DT=%d (bounce=%.3fs)", clk_pin, dt_pin, bounce_time)

    def _read_state(self):
        """Return (clk_level, dt_level) as integers (0 or 1)."""
        try:
            return int(self._clk.is_active), int(self._dt.is_active)
        except Exception as exc:
            logger.error("Error reading encoder state: %s", exc)
            return 0, 0

    def _transition(self):
        """Handle a rising/falling edge on CLK or DT and update the counter."""
        now = time.monotonic()
        if now - self._last_event_time < self._bounce_time:
            return
        self._last_event_time = now

        try:
            clk_state, dt_state = self._read_state()
        except Exception as exc:
            logger.error("Error reading encoder state during transition: %s", exc)
            return

        if self._last_state is None:
            self._last_state = (clk_state, dt_state)
            return

        key = self._last_state
        try:
            transition = self.TRANSITION.get(key)
        except KeyError:
            logger.warning("Unknown state %s; skipping transition.", key)
            self._last_state = (clk_state, dt_state)
            return

        next_state = transition["next"]
        self._counter += transition["dir"]
        self._last_state = next_state

        if self._callback is not None and callable(self._callback):
            try:
                self._callback(self._counter)
            except Exception as exc:
                logger.error("Callback raised an exception: %s", exc)

    def get_counter(self):
        return self._counter

    def cleanup(self):
        """Remove event detections and release GPIO resources."""
        if self._closed:
            return
        self._closed = True
        for dev in (self._clk, self._dt):
            if dev is not None:
                try:
                    dev.close()
                except Exception as exc:
                    logger.warning("Error closing GPIO device: %s", exc)
        try:
            self._clk.when_activated = None
            self._clk.when_deactivated = None
            self._dt.when_activated = None
            self._dt.when_deactivated = None
        except Exception:
            pass
        logger.info("RotaryEncoder cleanup complete.")


def _main():
    encoder = None

    def _signal_handler(signum, frame):
        logger.info("Signal %d received; shutting down.", signum)
        if encoder is not None:
            encoder.cleanup()
        raise SystemExit(0)

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        encoder = RotaryEncoder(clk_pin=17, dt_pin=18, callback=None, bounce_time=0.02)
        logger.info("Counter: %d", encoder.get_counter())
        while True:
            time.sleep(0.1)
    except SystemExit:
        pass
    except Exception as exc:
        logger.error("Runtime error: %s", exc)
    finally:
        if encoder is not None:
            encoder.cleanup()


if __name__ == "__main__":
    _main()

