import sys
import signal

try:
    from gpiozero import PWMOutputDevice
    from gpiozero.exc import GPIOZeroError, DeviceClosed
except ImportError:
    print("Error: gpiozero is not installed. Install with: sudo apt install python3-gpiozero")
    sys.exit(1)

FAN_PIN = 12
PWM_FREQ = 25000

fan = None
running = True

def cleanup():
    global fan
    if fan is not None:
        try:
            fan.close()
        except DeviceClosed:
            pass
        except Exception:
            pass
        fan = None

def handle_signal(signum, frame):
    global running
    running = False

signal.signal(signal.SIGINT, handle_signal)
signal.signal(signal.SIGTERM, handle_signal)

try:
    try:
        fan = PWMOutputDevice(FAN_PIN, frequency=PWM_FREQ, initial_value=0.0)
    except GPIOZeroError as e:
        print(f"Warning: hardware PWM on GPIO{FAN_PIN} unavailable ({e}). Falling back to software PWM.")
        try:
            from gpiozero import PWMOutputDevice
            fan = PWMOutputDevice(FAN_PIN, frequency=PWM_FREQ, initial_value=0.0)
        except Exception as e2:
            print(f"Warning: software PWM also unavailable ({e2}). Continuing without PWM control.")
            fan = None

    while running:
        try:
            user_input = input("Enter fan speed (0-100): ").strip()
            if not user_input:
                continue
            speed = float(user_input)
            if 0 <= speed <= 100:
                if fan is not None:
                    fan.value = speed / 100.0
                else:
                    print("Warning: PWM device not initialized. Fan speed not updated.")
            else:
                print("Invalid input. Please enter a number between 0 and 100.")
        except ValueError:
            print("Invalid input. Please enter a number.")
        except EOFError:
            break
        except Exception as e:
            print(f"An error occurred: {e}")

except Exception as e:
    print(f"Fatal error during initialization: {e}")
finally:
    cleanup()
    print("GPIO cleaned up. Exiting.")

