import RPi.GPIO as GPIO
import time
import logging
import random

# Configure logging to file
logging.basicConfig(
    filename='art_installation.log',
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)

# GPIO pin definitions (BCM numbering)
PIR_SENSOR_1_PIN = 17
PIR_SENSOR_2_PIN = 18

# Actuator functions (simulated)
ACTUATORS = [
    lambda: print("Activating light"),
    lambda: print("Activating sound"),
    lambda: print("Activating motor")
]


def read_sensor(pin):
    """Read a PIR sensor. Returns True if idle (HIGH), False if triggered (LOW)."""
    try:
        return GPIO.input(pin) == GPIO.HIGH
    except Exception as e:
        logging.error(f"Error reading sensor on pin {pin}: {e}")
        return False


def trigger_actuator(actuator_func):
    """Execute a random actuator function from the list."""
    try:
        ACTUATORS[random.randint(0, len(ACTUATORS) - 1)]()
        logging.info("Actuator triggered")
    except Exception as e:
        logging.error(f"Error triggering actuator: {e}")


def handle_intrusion(sensor_number, sensor_pin):
    """Log and trigger an actuator on a single sensor intrusion."""
    logging.info(f"Intrusion Detected by Sensor {sensor_number} on pin {sensor_pin}")
    trigger_actuator(ACTUATORS[random.randint(0, len(ACTUATORS) - 1)])


def handle_confirmed_intrusion(sensor1_pin, sensor2_pin):
    """Log and trigger all actuators on a confirmed dual-sensor intrusion."""
    logging.warning("Confirmed Intrusion - Both Sensors Triggered")
    for i in range(len(ACTUATORS)):
        ACTUATORS[i]()
        logging.info(f"Actuator {i + 1} triggered")


def main():
    """Main loop: monitor PIR sensors and trigger actuators on intrusion."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(PIR_SENSOR_1_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)
        GPIO.setup(PIR_SENSOR_2_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)
    except RuntimeError as e:
        logging.error(f"GPIO initialization failed: {e}. Run with sudo.")
        return
    except Exception as e:
        logging.error(f"Unexpected error during GPIO setup: {e}")
        return

    last_sensor1_trigger = None
    last_sensor2_trigger = None

    try:
        while True:
            sensor1_triggered = read_sensor(PIR_SENSOR_1_PIN)
            sensor2_triggered = read_sensor(PIR_SENSOR_2_PIN)

            current_time = time.time()

            # Single sensor trigger
            if sensor1_triggered:
                if last_sensor1_trigger is None:
                    handle_intrusion(1, PIR_SENSOR_1_PIN)
                    last_sensor1_trigger = current_time
            elif sensor1_triggered and last_sensor1_trigger is not None:
                elapsed = current_time - last_sensor1_trigger
                if elapsed < 0.5:
                    handle_confirmed_intrusion(PIR_SENSOR_1_PIN, PIR_SENSOR_2_PIN)
                    last_sensor1_trigger = None
                else:
                    last_sensor1_trigger = None

            if sensor2_triggered:
                if last_sensor2_trigger is None:
                    handle_intrusion(2, PIR_SENSOR_2_PIN)
                    last_sensor2_trigger = current_time
            elif sensor2_triggered and last_sensor2_trigger is not None:
                elapsed = current_time - last_sensor2_trigger
                if elapsed < 0.5:
                    handle_confirmed_intrusion(PIR_SENSOR_1_PIN, PIR_SENSOR_2_PIN)
                    last_sensor2_trigger = None
                else:
                    last_sensor2_trigger = None

            time.sleep(0.1)  # Debounce / cooldown
            time.sleep(0.05)  # Reduce CPU usage

    except KeyboardInterrupt:
        print("Exiting program...")
        logging.info("Program terminated by user (KeyboardInterrupt)")
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        GPIO.cleanup()
        logging.info("GPIO cleanup completed")


if __name__ == "__main__":
    main()

