import signal
import sys

try:
    from gpiozero import OutputDevice
    from gpiozero.exc import GPIOZeroError, GPIODeviceError
except ImportError:
    print("Error: gpiozero is not installed. Install with: sudo apt install python3-gpiozero")
    sys.exit(1)

WATER_PUMP_PIN = 17
MOISTURE_THRESHOLD = 30
ITERATIONS = 5
DELAY_SECONDS = 2

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def read_soil_moisture():
    """Simulate a soil-moisture sensor reading between 0 and 100 inclusive."""
    return random.randint(0, 100)

def control_water_pump(pump, moisture_level):
    """Control the water pump based on the soil-moisture level."""
    if moisture_level < MOISTURE_THRESHOLD:
        pump.on()
        print(f"Water Pump ON: Soil too dry ({moisture_level} < {MOISTURE_THRESHOLD})")
    else:
        pump.off()
        print(f"Water Pump OFF: Soil moisture sufficient ({moisture_level} >= {MOISTURE_THRESHOLD})")

def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    pump = None
    try:
        pump = OutputDevice(WATER_PUMP_PIN)
        print(f"Water pump initialized on GPIO {WATER_PUMP_PIN} (BCM).")

        for i in range(1, ITERATIONS + 1):
            if not _running:
                print("Shutdown signal received; exiting loop early.")
                break

            moisture = read_soil_moisture()
            print(f"[{i}/{ITERATIONS}] Soil Moisture: {moisture}%")
            control_water_pump(pump, moisture)

            if i < ITERATIONS and _running:
                time.sleep(DELAY_SECONDS)

    except (GPIOZeroError, GPIODeviceError) as e:
        print(f"GPIO error: {e}")
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        if pump is not None:
            try:
                pump.off()
                pump.close()
                print("Pump turned off and GPIO released.")
            except Exception as e:
                print(f"Error during cleanup: {e}")
        print("Program terminated.")

if __name__ == "__main__":
    main()

