from gpiozero.exc import GPIOZeroError, GPIODeviceError

DOOR_LOCK_PIN = 27
UNLOCK_DURATION_S = 5.0
LOOP_DELAY_S = 0.1

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        lock = OutputDevice(DOOR_LOCK_PIN, active_high=True, initial_value=False)
    except (GPIOZeroError, GPIODeviceError) as exc:
        print(f"Failed to initialize GPIO {DOOR_LOCK_PIN}: {exc}", file=sys.stderr)
        sys.exit(1)
    except Exception as exc:
        print(f"Unexpected error initializing GPIO {DOOR_LOCK_PIN}: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        lock.off()  # Ensure door is locked on startup
        print("Door locked. Simulating authorization checks...")

        while _running:
            # Simulate receiving an authorization signal
            authorization_granted = False

            if authorization_granted:
                print("Authorization granted. Unlocking door...")
                try:
                    lock.on()
                except (GPIOZeroError, GPIODeviceError) as exc:
                    print(f"Error unlocking door: {exc}", file=sys.stderr)
                    lock.off()
                    continue

                time.sleep(UNLOCK_DURATION_S)

                try:
                    lock.off()
                except (GPIOZeroError, GPIODeviceError) as exc:
                    print(f"Error relocking door: {exc}", file=sys.stderr)
                else:
                    print("Door locked.")
            else:
                print("Authorization denied.")

            time.sleep(LOOP_DELAY_S)

    except Exception as exc:
        print(f"Runtime error: {exc}", file=sys.stderr)
    finally:
        try:
            lock.off()
            lock.close()
        except Exception:
            pass
        print("GPIO cleanup completed. Exiting.")


if __name__ == "__main__":
    main()

