import random
import time
from gpiozero import LED
from gpiozero.exc import GPIOZeroError

# Constants
LED_PIN = 17
LIGHT_THRESHOLD = 50
CYCLES = 5
DELAY_SECONDS = 2


def read_light_level() -> int:
    """Simulate reading an ambient light sensor (0-100 inclusive)."""
    return random.randint(0, 100)


def control_led(led: LED, light_level: int) -> str:
    """Control the LED based on the light level and return its status string."""
    if light_level < LIGHT_THRESHOLD:
        led.on()
        return "ON"
    else:
        led.off()
        return "OFF"


def main() -> None:
    """Main loop: simulate light readings and control the LED."""
    try:
        with LED(LED_PIN) as led:
            for cycle in range(1, CYCLES + 1):
                light_level = read_light_level()
                status = control_led(led, light_level)
                print(f"Cycle {cycle}/{CYCLES}: Light Level = {light_level}% | LED is {status}")
                if cycle < CYCLES:
                    time.sleep(DELAY_SECONDS)
    except KeyboardInterrupt:
        print("\nProgram interrupted by user.")
    except GPIOZeroError as exc:
        print(f"GPIO error: {exc}")
    except Exception as exc:
        print(f"Unexpected error: {exc}")


if __name__ == "__main__":
    main()

