import RPi.GPIO as GPIO
import time
import sys

# Pin definitions (BCM numbering)
LEFT_SENSOR_PIN = 5
RIGHT_SENSOR_PIN = 6
LEFT_MOTOR_PIN = 16
RIGHT_MOTOR_PIN = 26

def setup_pins():
    """Configure GPIO pins for sensors and motors."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(LEFT_SENSOR_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)
        GPIO.setup(RIGHT_SENSOR_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)
        GPIO.setup(LEFT_MOTOR_PIN, GPIO.OUT, initial=GPIO.LOW)
        GPIO.setup(RIGHT_MOTOR_PIN, GPIO.OUT, initial=GPIO.LOW)
    except Exception as e:
        print(f"GPIO setup failed: {e}")
        sys.exit(1)

def read_sensors():
    """Read both reflectance sensors. Returns (left_detecting, right_detecting)."""
    try:
        left_state = GPIO.input(LEFT_SENSOR_PIN)
        right_state = GPIO.input(RIGHT_SENSOR_PIN)
        return left_state == GPIO.LOW, right_state == GPIO.LOW
    except Exception as e:
        print(f"Sensor read error: {e}")
        return False, False

def decide_action(left_detecting, right_detecting):
    """Decide motor actions based on sensor readings."""
    if left_detecting and not right_detecting:
        return "left"
    elif right_detecting and not left_detecting:
        return "right"
    elif left_detecting and right_detecting:
        return "straight"
    else:
        return "stop"

def apply_action(action):
    """Drive motors according to decision."""
    try:
        if action == "left":
            GPIO.output(LEFT_MOTOR_PIN, GPIO.HIGH)
            GPIO.output(RIGHT_MOTOR_PIN, GPIO.LOW)
        elif action == "right":
            GPIO.output(LEFT_MOTOR_PIN, GPIO.LOW)
            GPIO.output(RIGHT_MOTOR_PIN, GPIO.HIGH)
        elif action == "straight":
            GPIO.output(LEFT_MOTOR_PIN, GPIO.HIGH)
            GPIO.output(RIGHT_MOTOR_PIN, GPIO.HIGH)
        else:  # stop
            GPIO.output(LEFT_MOTOR_PIN, GPIO.LOW)
            GPIO.output(RIGHT_MOTOR_PIN, GPIO.LOW)
    except Exception as e:
        print(f"Motor control error: {e}")

def cleanup():
    """Safely release GPIO resources."""
    try:
        GPIO.output(LEFT_MOTOR_PIN, GPIO.LOW)
        GPIO.output(RIGHT_MOTOR_PIN, GPIO.LOW)
        GPIO.cleanup()
    except Exception as e:
        print(f"Cleanup error: {e}")

if __name__ == "__main__":
    setup_pins()
    try:
        for iteration in range(20):
            left_detecting, right_detecting = read_sensors()
            action = decide_action(left_detecting, right_detecting)
            apply_action(action)
            print(f"Iteration {iteration+1}: left={left_detecting}, right={right_detecting}, action={action}")
            time.sleep(0.1)
    except KeyboardInterrupt:
        print("\nLine following stopped by user")
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        cleanup()

