import RPi.GPIO as GPIO
import time
import logging
import sys

logging.basicConfig(level=logging.INFO, format="%(asctime)s %(message)s")


class ServoController:
    """Controls a 5V hobby servo via RPi.GPIO PWM with robust cleanup."""

    def __init__(self, servo_pin=18, frequency=50, min_duty=2.5, max_duty=12.5):
        self.servo_pin = servo_pin
        self.frequency = frequency
        self.min_duty = min_duty
        self.max_duty = max_duty
        self.pwm_channel = None

        try:
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(self.servo_pin, GPIO.OUT)
            self.pwm_channel = GPIO.PWM(self.servo_pin, self.frequency)
            self.pwm_channel.start(0)
            logging.info("Servo controller initialized on GPIO %d at %d Hz", servo_pin, frequency)
        except Exception as e:
            logging.error("Failed to initialize servo controller: %s", e)
            self.cleanup()
            raise

    def _angle_to_duty_cycle(self, angle):
        """Map a servo angle (0-180) to a duty cycle percentage."""
        clamped = max(0, min(180, angle))
        return self.min_duty + (clamped / 180.0) * (self.max_duty - self.min_duty)

    def move_to(self, angle):
        """Move servo to the given angle and log the action."""
        if self.pwm_channel is None:
            raise RuntimeError("Servo controller not initialized")
        duty = self._angle_to_duty_cycle(angle)
        self.pwm_channel.ChangeDutyCycle(duty)
        logging.info("Servo moved to %d degrees (duty %.1f%%)", angle, duty)

    def stop(self):
        """Stop the PWM signal and release the servo."""
        if self.pwm_channel is not None:
            try:
                self.pwm_channel.ChangeDutyCycle(0)
                self.pwm_channel.stop()
            except Exception as e:
                logging.warning("Error stopping PWM: %s", e)
            finally:
                self.pwm_channel = None
        logging.info("Servo stopped")

    def cleanup(self):
        """Stop PWM and release GPIO resources."""
        self.stop()
        try:
            GPIO.cleanup()
        except Exception as e:
            logging.warning("GPIO cleanup failed: %s", e)


def demonstrate_servo(controller, angle_list):
    """Sweep the servo through a list of angles for student observation."""
    for angle in angle_list:
        controller.move_to(angle)
        time.sleep(0.5)


if __name__ == "__main__":
    SERVO_PIN = 18
    ANGLE_LIST = [0, 45, 90, 135, 180, 135, 90, 45, 0]

    servo_controller = None
    try:
        servo_controller = ServoController(servo_pin=SERVO_PIN)
        demonstrate_servo(servo_controller, ANGLE_LIST)
    except KeyboardInterrupt:
        logging.info("Demonstration interrupted by user")
    except Exception as e:
        logging.error("Unexpected error: %s", e)
        sys.exit(1)
    finally:
        if servo_controller is not None:
            servo_controller.cleanup()
        else:
            GPIO.cleanup()

