import serial
import time
import signal
import sys
from gpiozero import PWMOutputDevice

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
SERVO_PIN = 17

servo = None
serial_connection = None
running = True

def signal_handler(signum, frame):
    global running
    running = False

def move_servo(angle):
    if not 0 <= angle <= 180:
        raise ValueError("Angle must be between 0 and 180 degrees.")
    duty_cycle = angle / 18.0 + 2.0
    servo.value = duty_cycle
    time.sleep(1)
    servo.value = 0

def cleanup():
    global servo, serial_connection
    if servo is not None:
        servo.value = 0
        servo.close()
        servo = None
    if serial_connection is not None and serial_connection.is_open:
        serial_connection.close()
        serial_connection = None

def main():
    global servo, serial_connection
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        serial_connection = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=1)
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
        sys.exit(1)

    try:
        servo = PWMOutputDevice(SERVO_PIN, frequency=50)
    except Exception as e:
        print(f"Error initializing GPIO: {e}")
        cleanup()
        sys.exit(1)

    try:
        while running:
            try:
                raw = serial_connection.readline()
                if not raw:
                    continue
                command = raw.decode('ascii', errors='replace').strip()
                if command:
                    try:
                        angle = int(command)
                        move_servo(angle)
                        print(f"Servo moved to {angle} degrees.")
                    except ValueError as e:
                        print(f"Invalid angle received: {e}")
            except serial.SerialException as e:
                print(f"Serial read error: {e}")
                break
            except Exception as e:
                print(f"Unexpected error: {e}")
                break
    finally:
        cleanup()

if __name__ == "__main__":
    main()

