import signal
import sys
import logging
import time
from typing import Dict, Any, Union, List, Optional

try:
    from pymodbus.client import ModbusSerialClient
    from pymodbus.exceptions import ModbusException, ModbusIOException
    _MODBUS_AVAILABLE = True
except ImportError:
    _MODBUS_AVAILABLE = False
    ModbusSerialClient = None
    ModbusException = Exception
    ModbusIOException = Exception

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)


class Servo:
    """
    A class to control a servo motor via Modbus RTU using a Raspberry Pi.
    """

    # Modbus register map dictionary
    _registers: Dict[str, Dict[str, Any]] = {
        "STATUS": {
            "R/W": "R",
            "Register": 0x3000,
            "functioncode": 3,
        },
        "CONTROL": {
            "R/W": "W",
            "Register": 0x3100,
            "functioncode": 6,
            "Value": {"Stop": 0x0006, "Start": 0x000F},
        },
        "OPMODE": {
            "R/W": "W",
            "Register": 0x3500,
            "functioncode": 6,
            "Value": {"Position": 1},
        },
        "VelocityCommand": {
            "R/W": "W",
            "Register": 0x6F00,
            "functioncode": 6,
        },
        "VelocityFeedback": {
            "R/W": "R",
            "Register": 0x3B00,
            "functioncode": 3,
            "read_length": 2,
        },
        "PositionCommand": {
            "R/W": "W",
            "Register": 0x4000,
            "functioncode": 6,
        },
        "PositionFeedback": {
            "R/W": "R",
            "Register": 0x3700,
            "functioncode": 3,
            "read_length": 2,
        },
    }

    def __init__(self, port: str = "/dev/serial0", baudrate: int = 115200, timeout: float = 1.0) -> None:
        """
        Initializes the Servo object.

        Args:
            port (str): The serial port to use (default: /dev/serial0).
            baudrate (int): The baud rate for serial communication (default: 115200).
            timeout (float): Timeout for Modbus operations in seconds (default: 1.0).
        """
        self._client = None
        self._running = True
        self._registers = self._registers.copy()

        if not _MODBUS_AVAILABLE:
            logger.warning("pymodbus not installed; running in degraded mode (no hardware I/O).")
            return

        try:
            self._client = ModbusSerialClient(
                port=port,
                baudrate=baudrate,
                bytesize=8,
