app = Flask(__name__)

RELAY_PIN = 23
relay = None


def init_relay():
    """Initialize the relay GPIO pin."""
    global relay
    try:
        relay = OutputDevice(RELAY_PIN, active_high=True, initial_value=False)
    except GPIOZeroError as e:
        print(f"Failed to initialize GPIO{RELAY_PIN}: {e}", file=sys.stderr)
        sys.exit(1)


def cleanup(signum=None, frame=None):
    """Release GPIO resources on exit."""
    global relay
    if relay is not None:
        try:
            relay.close()
        except Exception:
            pass
        relay = None
    if signum is not None:
        sys.exit(0)


@app.route('/relay', methods=['POST'])
def handle_relay_request():
    """Handle POST requests to control the relay."""
    try:
        request_data = request.get_json(silent=True)
        if not request_data or 'state' not in request_data:
