import sys
from flask import Flask, request, jsonify
from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError

app = Flask(__name__)

RELAY_PIN = 23
relay = None


def init_relay():
    """Initialize the relay GPIO pin."""
    global relay
    try:
        relay = OutputDevice(RELAY_PIN, active_high=True, initial_value=False)
    except GPIOZeroError as e:
        print(f"Failed to initialize GPIO{RELAY_PIN}: {e}", file=sys.stderr)
        sys.exit(1)


def cleanup(signum=None, frame=None):
    """Release GPIO resources on exit."""
    global relay
    if relay is not None:
        try:
            relay.close()
        except Exception:
            pass
        relay = None
    if signum is not None:
        sys.exit(0)


@app.route('/relay', methods=['POST'])
def handle_relay_request():
    """Handle POST requests to control the relay."""
    try:
        request_data = request.get_json(silent=True)
        if not request_data or 'state' not in request_data:
            return jsonify({'error': 'Invalid request: Missing or malformed JSON, "state" key required'}), 400

        relay_state = request_data['state']
        if relay_state == 'on':
            relay.on()
        elif relay_state == 'off':
            relay.off()
        else:
            return jsonify({'error': 'Invalid request: "state" must be "on" or "off"'}), 400

        return jsonify({'status': 'Relay state changed'}), 200

    except Exception as e:
        print(f"Error handling relay request: {e}", file=sys.stderr)
        return jsonify({'error': 'Internal server error'}), 500


if __name__ == '__main__':
    init_relay()
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)
    try:
        app.run(host='0.0.0.0', port=5000)
