import signal
import sys
from time import sleep
from gpiozero import OutputDevice

try:
    from servoblaster import ServoBlaster
except ImportError:
    print("Error: servoblaster library not found. Install with: pip install servoblaster", file=sys.stderr)
    sys.exit(1)


class AimingController:
    """Controls two servos via /dev/servoblaster and a laser via gpiozero."""

    def __init__(self, ld, hd, laser_pin=17):
        self.ld = ld
        self.hd = hd
        self.laser_pin = laser_pin
        self.laser = None
        self.sb = None
        self._shutting_down = False

        try:
            self.laser = OutputDevice(laser_pin, active_high=True, initial_value=False)
        except Exception as exc:
            print(f"Error initializing laser on BCM GPIO{laser_pin}: {exc}", file=sys.stderr)
            raise

        try:
            self.sb = ServoBlaster()
        except Exception as exc:
            print(f"Error opening servoblaster device: {exc}", file=sys.stderr)
            self._cleanup()
            raise

    def _cleanup(self):
        if self.laser is not None:
            try:
                self.laser.off()
                self.laser.close()
            except Exception:
                pass
            self.laser = None
        if self.sb is not None:
            try:
                self.sb.close()
            except Exception:
                pass
            self.sb = None

    def _signal_handler(self, signum, frame):
        print(f"\nSignal {signum} received; shutting down cleanly.")
        self._shutting_down = True
        self._cleanup()
        sys.exit(0)

    def _write_servo(self, channel, value):
        if self.sb is None:
            raise RuntimeError("ServoBlaster device is not open.")
        try:
            self.sb.set_servo(channel, value)
        except Exception as exc:
            print(f"Error writing to servo channel {channel}: {exc}", file=sys.stderr)
            raise

    def _move_servo(self, h_pos, v_pos):
        self._write_servo(0, h_pos)
        self._write_servo(1, v_pos)

    def aim_blocks(self, nums):
        if self.sb is None or self.laser is None:
            print("AimingController not initialized; cannot aim_blocks.", file=sys.stderr)
            return

        signal.signal(signal.SIGINT, self._signal_handler)
        signal.signal(signal.SIGTERM, self._signal_handler)

        hx = [133, 128, 122, 133, 128, 122, 133, 128, 122, 128]
        vy = [75, 75, 75, 72, 72, 72, 68, 68, 68, 90]

        if len(nums) != len(hx):
            print("Error: nums and hx/vy lists have different lengths.", file=sys.stderr)
            return

        ordered = sorted(range(len(nums)), key=lambda k: nums[k])

        for i in ordered:
            if self._shutting_down:
                break
            sleep(self.ld / 2)
            self._move_servo(hx[i], vy[i])
            sleep(self.ld / 2)
            self.laser.on()
            sleep(self.hd)
            self.laser.off()

    def shutdown(self):
        if self._shutting_down:
            return
        self._shutting_down = True
        self._cleanup()


if __name__ == "__main__":
    try:
        controller = AimingController(ld=0.5, hd=1.0, laser_pin=17)
        controller.aim_blocks([1, 2, 3, 4, 5, 6, 7, 8, 9, 0])
    except KeyboardInterrupt:
        pass
    except Exception as exc:
        print(f"Fatal error: {exc}", file=sys.stderr)
    finally:
        if 'controller' in locals():
            controller.shutdown()

