import time
import signal
import sys
import logging
import smbus2
from ina219 import INA219, DeviceRangeError

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

SUPPLY_INA219_ADDRESS = 0x40
BATTERY_INA219_ADDRESS = 0x45
UPS_PLUS_ADDRESS = 0x17
SHUNT_RESISTOR_SUPPLY = 0.00725
SHUNT_RESISTOR_BATTERY = 0.005
CALIBRATION_VALUE = 4096

running = True

def signal_handler(signum, frame):
    global running
    running = False

def read_register(bus, address, register):
    try:
        return bus.read_byte_data(address, register)
    except Exception as e:
        logger.error(f"Error reading register 0x{register:02X} from 0x{address:02X}: {e}")
        return None

def read_word_big_endian(bus, address, register):
    try:
        data = bus.read_i2c_block_data(address, register, 2)
        return (data[0] << 8) | data[1]
    except Exception as e:
        logger.error(f"Error reading word from 0x{address:02X} at register 0x{register:02X}: {e}")
        return None

def read_ups_data(bus):
    processor_voltage = read_register(bus, UPS_PLUS_ADDRESS, 1)
    if processor_voltage is None:
        return None, None, None
    if processor_voltage & 0x80:
        processor_voltage = (processor_voltage & 0x7F) * 2
    else:
        processor_voltage = processor_voltage * 2

    battery_capacity = read_register(bus, UPS_PLUS_ADDRESS, 19)
    if battery_capacity is None:
        return None, None, None
    if battery_capacity & 0x80:
        battery_capacity = (battery_capacity & 0x7F) * 2
    else:
        battery_capacity = battery_capacity * 2

    power_state = read_register(bus, UPS_PLUS_ADDRESS, 23)
    if power_state is None:
        return None, None, None
    return processor_voltage, battery_capacity, power_state

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    ina_supply = None
    ina_battery = None
    bus = None

    try:
        bus = smbus2.SMBus(1)
    except Exception as e:
        logger.error(f"Failed to open I2C bus 1: {e}")
        return

    try:
        try:
            ina_supply = INA219(SUPPLY_INA219_ADDRESS, busnum=1, shunt=SHUNT_RESISTOR_SUPPLY,
                                multiplier=CALIBRATION_VALUE)
            ina_supply.configure()
        except Exception as e:
            logger.warning(f"Could not configure supply INA219 at 0x{SUPPLY_INA219_ADDRESS:02X}: {e}")

        try:
            ina_battery = INA219(BATTERY_INA219_ADDRESS, busnum=1, shunt=SHUNT_RESISTOR_BATTERY,
                                 multiplier=CALIBRATION_VALUE)
            ina_battery.configure()
        except Exception as e:
            logger.warning(f"Could not configure battery INA219 at 0x{BATTERY_INA219_ADDRESS:02X}: {e}")

        if ina_supply is not None:
            try:
                ina_supply.wake()
            except DeviceRangeError:
                logger.warning("Supply INA219 current out of range after wake.")
            except Exception as e:
                logger.warning(f"Error waking supply INA219: {e}")

        if ina_battery is not None:
            try:
                ina_battery.wake()
            except DeviceRangeError:
                logger.warning("Battery INA219 current out of range after wake.")
            except Exception as e:
                logger.warning(f"Error waking battery INA219: {e}")

        while running:
            try:
                if ina_supply is not None:
                    supply_current = ina_supply.current / 1000.0
                    supply_power = ina_supply.power / 1000.0
                    logger.info(f"Raspberry Pi power supply: Current={supply_current:.3f} mA, Power={supply_power:.3f} mW")
                else:
                    logger.warning("Supply INA219 not available.")

                if ina_battery is not None:
                    battery_voltage = ina_battery.voltage / 1000.0
                    battery_current = ina_battery.current / 1000.0
                    battery_power = ina_battery.power / 1000.0
                    logger.info(f"Battery: Voltage={battery_voltage:.3f} V, Current={battery_current:.3f} mA, Power={battery_power:.3f} mW")
                else:
                    logger.warning("Battery INA219 not available.")

                processor_voltage, battery_capacity, power_state = read_ups_data(bus)
                if processor_voltage is not None and battery_capacity is not None and power_state is not None:
                    logger.info(f"UPS Plus: Processor Voltage={processor_voltage} mV, Battery Capacity={battery_capacity}%, Power State={power_state}")
                else:
                    logger.warning("Failed to read UPS Plus data.")

            except DeviceRangeError as e:
                logger.warning(f"INA219 DeviceRangeError: {e}")
            except Exception as e:
                logger.error(f"Error reading sensors: {e}")

            for _ in range(5):
                if not running:
                    break
                time.sleep(1)

    finally:
        if bus is not None:
            try:
                bus.close()
            except Exception:
                pass
        logger.info("Program terminated.")

if __name__ == "__main__":
    main()

