#!/usr/bin/env python3
"""Maxim DS1338 RTC driver for Raspberry Pi using smbus2 (I2C bus 1, address 0x68)."""

import smbus2
from datetime import datetime, timezone
from typing import Tuple, Optional


class DS1338:
    """Driver for the Maxim DS1338 I2C RTC (BCD registers 0x00-0x06)."""

    _REG_SECONDS = 0x00
    _REG_MINUTES = 0x01
    _REG_HOURS = 0x02
    _REG_DAY = 0x03
    _REG_DATE = 0x04
    _REG_MONTH = 0x05
    _REG_YEAR = 0x06

    _CH_BIT = 0x80          # Bit 7 of seconds register controls oscillator
    _HOUR_12_BIT = 0x40     # Bit 6 of hours register selects 12/24 mode
    _HOUR_24_MASK = 0x3F    # Mask for 24-hour mode

    def __init__(self, i2c_bus: int = 1, address: int = 0x68) -> None:
        """Open the SMBus and store the bus handle."""
        self._address = address
        try:
            self._bus = smbus2.SMBus(i2c_bus)
        except FileNotFoundError:
            raise IOError(
                f"I2C bus {i2c_bus} not found. Enable I2C with 'sudo raspi-config'."
            )
        except PermissionError:
            raise IOError(
                f"Permission denied opening /dev/i2c-{i2c_bus}. "
                "Add the user to the 'i2c' group or run with appropriate privileges."
            )
        except OSError as exc:
            raise IOError(f"Failed to open I2C bus {i2c_bus}: {exc}") from exc

    # -- context-manager support -------------------------------------------------

    def __enter__(self) -> "DS1338":
        return self

    def __exit__(self, exc_type, exc_val, exc_tb) -> None:
        self.close()

    def close(self) -> None:
        """Close the SMBus handle if open."""
        if getattr(self, "_bus", None) is not None:
            try:
                self._bus.close()
            except OSError:
                pass
            finally:
                self._bus = None

    # -- low-level register helpers ---------------------------------------------

    def _write_register(self, register: int, data: int) -> None:
        """Write a single BCD byte to a DS1338 register."""
        self._bus.write_byte_data(self._address, register, data)

    def _read_register(self, register: int) -> int:
        """Read a single byte from a DS1338 register."""
        return self._bus.read_byte_data(self._address, register)

