# co2_sensor_logging_rpi.py
# Reads CO2 concentration from a serial sensor on a Raspberry Pi Zero W.
# Logs readings with timestamps to a file and prints to the terminal.

import serial
import time
import signal
import sys
from datetime import datetime

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1
LOG_FILE = 'co2_readings_log.txt'
SAMPLE_INTERVAL = 5

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def read_co2_level(ser):
    try:
        data = ser.readline()
        if not data:
            print("Error: No data received (timeout or empty line).")
            return None
        decoded = data.decode('ascii', errors='replace').strip()
        if not decoded:
            print("Error: Received empty data line.")
            return None
        return int(decoded)
    except ValueError:
        print(f"Error: Could not convert data to an integer: '{decoded}'")
        return None
    except serial.SerialException as e:
        print(f"Serial communication error: {e}")
        return None
    except IOError as e:
        print(f"File I/O error: {e}")
        return None

def log_co2_reading(log_file, co2_level):
    timestamp = datetime.now().isoformat(timespec='seconds')
    if co2_level is not None:
        try:
            with open(log_file, 'a') as f:
                f.write(f"{timestamp}, {co2_level}\n")
            print(f"CO2 Level: {co2_level} ppm")
        except IOError as e:
            print(f"Error writing to log file: {e}")
    else:
        print("Skipping logging due to read error.")

def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    ser = None
    try:
        ser = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT)
        print(f"Opened {SERIAL_PORT} at {BAUD_RATE} baud.")

        while _running:
            co2_level = read_co2_level(ser)
            log_co2_reading(LOG_FILE, co2_level)
            time.sleep(SAMPLE_INTERVAL)

    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        if ser is not None and ser.is_open:
            ser.close()
            print("Serial port closed.")
        print("Program terminated.")

if __name__ == "__main__":
    main()

