        alert_pin = OutputDevice(ALERT_PIN)
        print(f"GPIO {ALERT_PIN} initialized as output.")
    except Exception as e:
        print(f"Failed to initialize GPIO pin {ALERT_PIN}: {e}")
        cleanup()
        sys.exit(1)

    try:
        while running:
