import signal
import sys

SERIAL_PORT = "/dev/serial0"
BAUD_RATE = 9600
TIMEOUT = 1

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def decode_coordinate(raw_value):
    if not raw_value:
        return None
    try:
        if raw_value.startswith("N") or raw_value.startswith("S"):
            degrees = int(raw_value[:-2])
            minutes = float(raw_value[-2:])
            decimal_degrees = degrees + (minutes / 60.0)
            if raw_value.startswith("S"):
                decimal_degrees = -decimal_degrees
            return decimal_degrees
        elif raw_value.startswith("E") or raw_value.startswith("W"):
            degrees = int(raw_value[:-2])
            minutes = float(raw_value[-2:])
            decimal_degrees = degrees + (minutes / 60.0)
            if raw_value.startswith("W"):
                decimal_degrees = -decimal_degrees
            return decimal_degrees
        return None
    except (ValueError, IndexError):
        return None

def parse_gprmc(nmea_sentence):
    if not nmea_sentence.startswith("$GPRMC"):
        return None, None
    parts = nmea_sentence.split(",")
    if len(parts) < 10:
        return None, None
    if parts[2] != "A":
        return None, None
    lat_raw = parts[3]
    lat_dir = parts[4]
    lon_raw = parts[5]
    lon_dir = parts[6]
    lat_decimal = decode_coordinate(lat_raw)
    lon_decimal = decode_coordinate(lon_raw)
    if lat_decimal is None or lon_decimal is None:
        return None, None
    return lat_decimal, lon_decimal

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)
    serial_port = None
    try:
        serial_port = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT)
        print(f"Opened {SERIAL_PORT} at {BAUD_RATE} baud.")
        while _running:
            try:
                raw_line = serial_port.readline()
                if not raw_line:
                    continue
                nmea_sentence = raw_line.decode("utf-8", errors="ignore").strip()
                if not nmea_sentence:
                    continue
                latitude, longitude = parse_gprmc(nmea_sentence)
                if latitude is not None and longitude is not None:
                    print(f"Latitude: {latitude:.6f}, Longitude: {longitude:.6f}")
                time.sleep(1)
            except serial.SerialException as e:
                print(f"Serial communication error: {e}")
                break
            except Exception as e:
                print(f"Unexpected error processing data: {e}")
                break
    except serial.SerialException as e:
        print(f"Failed to open serial port {SERIAL_PORT}: {e}")
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        if serial_port is not None and serial_port.is_open:
            serial_port.close()
            print("Serial port closed.")
        print("Exiting program.")

