logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class SimpleGPS:
    def __init__(self, port='/dev/serial0', baudrate=9600):
        self.port = port
        self.baudrate = baudrate
        self.serial_connection = None
        self._running = True

    def connect(self):
        try:
            self.serial_connection = serial.Serial(
                port=self.port,
                baudrate=self.baudrate,
                bytesize=serial.EIGHTBITS,
                parity=serial.PARITY_NONE,
                stopbits=serial.STOPBITS_ONE,
                timeout=1
            )
            logging.info(f"Connected to GPS on {self.port} at {self.baudrate} baud.")
            return True
        except serial.SerialException as e:
            logging.error(f"Serial connection error on {self.port}: {e}")
            self.serial_connection = None
            return False
        except OSError as e:
            logging.error(f"OS error opening {self.port}: {e}")
            self.serial_connection = None
            return False

    def read_data(self):
        if not self.serial_connection or not self.serial_connection.is_open:
            logging.warning("Serial connection is not open.")
            return None
        try:
            if self.serial_connection.in_waiting > 0:
                raw = self.serial_connection.readline()
                if raw:
                    return raw.decode('utf-8', errors='ignore').strip()
            return None
        except serial.SerialException as e:
            logging.error(f"Serial read error: {e}")
            return None
        except OSError as e:
            logging.error(f"OS read error: {e}")
            return None

    def parse_gga(self, nmea_data):
        if not nmea_data:
            return None
        try:
            parts = nmea_data.split(',')
            if len(parts) < 15:
                logging.warning(f"Malformed GGA sentence (too few fields): {nmea_data}")
                return None
            talker_id = parts[0][1:3]
            if talker_id not in ('GP', 'GN'):
                logging.debug(f"Non-GGA talker ID '{talker_id}' in sentence: {nmea_data}")
                return None
            utc_time = parts[1]
            lat_raw = parts[2]
            lat_dir = parts[3]
            lon_raw = parts[4]
            lon_dir = parts[5]
            fix_quality = parts[6]
            num_satellites = parts[7]
            if not lat_raw or not lon_raw:
                logging.warning("Empty latitude or longitude in GGA sentence.")
                return None
            latitude = self._nmea_to_decimal(lat_raw, lat_dir)
            longitude = self._nmea_to_decimal(lon_raw, lon_dir)
            if latitude is None or longitude is None:
                logging.warning("Failed to convert coordinate(s).")
                return None
            return {
                'utc_time': utc_time,
                'latitude': latitude,
                'longitude': longitude,
                'fix_quality': fix_quality,
                'num_satellites': num_satellites
            }
        except IndexError as e:
            logging.error(f"IndexError in parse_gga: {e}")
            return None
        except ValueError as e:
            logging.error(f"ValueError in parse_gga: {e}")
            return None
        except Exception as e:
            logging.error(f"Unexpected error in parse_gga: {e}")
            return None

    @staticmethod
    def _nmea_to_decimal(raw_value, direction):
        if not raw_value or not direction:
            return None
        try:
            degrees = int(raw_value[:-2])
            minutes = float(raw_value[-2:])
            decimal = degrees + (minutes / 60.0)
            if direction in ('S', 'W'):
                decimal = -decimal
            return decimal
        except ValueError as e:
            logging.error(f"ValueError converting NMEA coordinate '{raw_value}' to decimal: {e}")
            return None

    def close(self):
        if self.serial_connection and self.serial_connection.is_open:
            try:
                self.serial_connection.close()
                logging.info("Serial connection closed.")
            except serial.SerialException as e:
                logging.error(f"Error closing serial connection: {e}")
            except OSError as e:
                logging.error(f"OS error closing serial connection: {e}")
        self.serial_connection = None

    def stop(self):
        self._running = False

def main():
    gps = SimpleGPS()
    def signal_handler(sig, frame):
        logging.info("Signal received, stopping...")
        gps.stop()
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    if not gps.connect():
        sys.exit(1)
    try:
        while gps._running:
            line = gps.read_data()
            if line:
                parsed = gps.parse_gga(line)
                if parsed:
                    logging.info(f"GPS Fix: {parsed}")
    except KeyboardInterrupt:
        logging.info("KeyboardInterrupt received.")
    finally:
        gps.close()

if __name__ == '__main__':
    main()

