from flask import Flask, Response, request, jsonify
import serial

app = Flask(__name__)

SERIAL_PORT = '/dev/ttyUSB0'
SERIAL_BAUDRATE = 9600
SERIAL_TIMEOUT = 1

serial_lock = threading.Lock()
serial_communicator = None


class SerialCommunicator:
    def __init__(self, port, baudrate, timeout):
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self.ser = None

    def open(self):
        with serial_lock:
            if self.ser is not None and self.ser.is_open:
                return True
            try:
                self.ser = serial.Serial(
                    port=self.port,
                    baudrate=self.baudrate,
                    bytesize=serial.EIGHTBITS,
                    parity=serial.PARITY_NONE,
                    stopbits=serial.STOPBITS_ONE,
                    timeout=self.timeout,
                )
                return True
            except serial.SerialException as e:
                print(f"Error opening serial port {self.port}: {e}", file=sys.stderr)
                self.ser = None
                return False

    def send(self, cmd):
        if not self.ser or not self.ser.is_open:
            raise serial.SerialException("Serial port not open")
        payload = cmd.encode('ascii')
        try:
            self.ser.write(payload)
            self.ser.flush()
            return len(payload)
        except serial.SerialException as e:
            raise serial.SerialException(f"Write failed: {e}")

    def receive_line(self):
        if not self.ser or not self.ser.is_open:
            raise serial.SerialException("Serial port not open")
        try:
            raw = self.ser.readline()
            if not raw:
                return None
            return raw.decode('ascii', errors='replace').strip()
        except serial.SerialException as e:
            raise serial.SerialException(f"Read failed: {e}")

    def close(self):
        with serial_lock:
            if self.ser is not None:
                try:
                    if self.ser.is_open:
                        self.ser.close()
                except serial.SerialException as e:
                    print(f"Error closing serial port: {e}", file=sys.stderr)
                finally:
                    self.ser = None

    def __enter__(self):
        if not self.open():
            raise serial.SerialException(f"Failed to open {self.port}")
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        self.close()


def create_data(name, done):
    if not isinstance(name, str) or not name.strip():
        return Response("Name must be a non-empty string", status=400, mimetype='text/plain')
    if not isinstance(done, bool):
        return Response("Done must be a boolean", status=400, mimetype='text/plain')
    id_ = app.data_manager.next_id()
    item = {'id': id_, 'name': name, 'done': done}
    app.data_manager.add_item(item)
    return Response(jsonify(item), status=201, mimetype='application/json')


@app.route('/version', methods=['GET'])
def get_version():
    if not serial_communicator or not serial_communicator.open():
        return Response("Serial port not available", status=500, mimetype='text/plain')
    try:
        serial_communicator.send('*IDN?\n')
        line = serial_communicator.receive_line()
        if line is None:
            return Response("No response from device", status=504, mimetype='text/plain')
        return Response(line, mimetype='text/plain')
    except serial.SerialException as e:
        print(f"Serial error during version query: {e}", file=sys.stderr)
        return Response(f"Serial communication error: {e}", status=502, mimetype='text/plain')
    finally:
        serial_communicator.close()


@app.route('/data', methods=['GET'])
def get_all_data():
    return Response(jsonify(app.data_manager.get_all()), status=200, mimetype='application/json')


@app.route('/data/<int:item_id>', methods=['GET'])
def get_data_item(item_id):
    item = app.data_manager.get_by_id(item_id)
    if item is None:
        return Response("Item not found", status=404, mimetype='text/plain')
    return Response(jsonify(item), status=200, mimetype='application/json')


@app.route('/data', methods=['POST'])
def create_data_item():
    name = request.form.get('name', '')
    done = request.form.get('done', False)
    return create_data(name, done)


def init_serial():
    global serial_communicator
    serial_communicator = SerialCommunicator(SERIAL_PORT, SERIAL_BAUDRATE, SERIAL_TIMEOUT)


def shutdown(signum, frame):
    print(f"\nReceived signal {signum}, shutting down...", file=sys.stderr)
    if serial_communicator is not None:
        serial_communicator.close()
    sys.exit(0)


if __name__ == '__main__':
    signal.signal(signal.SIGINT, shutdown)
    signal.signal(signal.SIGTERM, shutdown)
    init_serial()
    try:
        app.run(host='0.0.0.0', port=5000, debug=False)
    finally:
        if serial_communicator is not None:
            serial_communicator.close()

