import serial
import time
import sys
import signal

SERIAL_PORT = '/dev/serial0'
BAUD_RATE = 9600
TIMEOUT = 1
LOG_FILE = 'power_consumption.log'

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def log_power(power_watts):
    timestamp = time.strftime('%Y-%m-%d %H:%M:%S')
    line = f'{timestamp} - Power: {power_watts} W'
    try:
        with open(LOG_FILE, 'a') as f:
            f.write(line + '\n')
        print(line)
    except OSError as e:
        sys.stderr.write(f'Error writing to log file: {e}\n')

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        ser = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT)
    except serial.SerialException as e:
        sys.stderr.write(f'Error opening serial port {SERIAL_PORT}: {e}\n')
        sys.exit(1)
    except OSError as e:
        sys.stderr.write(f'OS error opening {SERIAL_PORT}: {e}\n')
        sys.exit(1)

    try:
        while _running:
            try:
                raw = ser.readline()
            except serial.SerialException as e:
                sys.stderr.write(f'Serial read error: {e}\n')
                break
            except OSError as e:
                sys.stderr.write(f'OS read error: {e}\n')
                break

            if not raw:
                continue

            line = raw.decode('ascii', errors='replace').strip()
            if not line:
                continue

            try:
                power = float(line)
            except ValueError:
                sys.stderr.write(f'Invalid data received (not numeric): {line!r}\n')
                continue

            log_power(power)
    finally:
        if ser.is_open:
            ser.close()
            sys.stdout.write('Serial port closed.\n')

if __name__ == '__main__':
    main()

