from flask import Flask, Response, request, jsonify
import serial
import serial.tools.list_ports
import time
import json
import threading
import signal
import sys

app = Flask(__name__)

# In-memory data store
data_store = [
    {"id": 1, "name": "Item 1", "done": False},
    {"id": 2, "name": "Item 2", "done": False},
]

# Serial port configuration
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1

# Global flag for graceful shutdown
shutdown_event = threading.Event()


def signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for clean shutdown."""
    print(f"\nReceived signal {signum}, shutting down...")
    shutdown_event.set()


def get_serial_connection():
    """Open the serial port, returning a serial.Serial object or None on failure."""
    try:
        ser = serial.Serial(
            port=SERIAL_PORT,
            baudrate=BAUD_RATE,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=TIMEOUT,
        )
        print(f"Serial port {SERIAL_PORT} opened at {BAUD_RATE} baud.")
        return ser
    except serial.SerialException as e:
        print(f"Error opening serial port {SERIAL_PORT}: {e}")
        return None
    except Exception as e:
        print(f"Unexpected error opening serial port: {e}")
        return None


@app.route('/version', methods=['GET'])
def version():
    """Query the connected instrument for its identification string."""
    ser = get_serial_connection()
    if ser is None:
        return Response(
            "Serial port unavailable - cannot retrieve version information.",
            status=503,
            mimetype='text/html',
        )

    try:
        # Send the SCPI identification query
        ser.write(b'*IDN?\n')
        time.sleep(0.1)

        # Read all available bytes (readline() returns b'' on timeout)
        raw = ser.readline()
        if not raw:
            return Response(
                "No response received from the instrument (timeout or no data).",
                status=503,
                mimetype='text/html',
            )

        response = raw.decode('ascii', errors='replace').strip()
        if not response:
            return Response(
                "Empty response from the instrument.",
                status=503,
                mimetype='text/html',
            )

        return Response(response + '<br>', mimetype='text/html')

    except serial.SerialException as e:
        print(f"Serial communication error during /version: {e}")
        return Response(
            f"Serial communication error: {e}",
            status=503,
            mimetype='text/html',
        )
    except Exception as e:
        print(f"Unexpected error during /version: {e}")
        return Response(
            f"Unexpected error: {e}",
            status=500,
            mimetype='text/html',
        )
    finally:
        # Always close the serial port, even on error
        if ser and ser.is_open:
            try:
                ser.close()
                print("Serial port closed.")
            except Exception as e:
                print(f"Error closing serial port: {e}")


@app.route('/getdata', methods=['GET'])
def get_data():
    """Return all items in the data store as JSON."""
    return jsonify(data_store)


@app.route('/getset/<int:item_id>', methods=['GET'])
def get_item(item_id):
    """Return a single item from the data store, or 404 if not found."""
    item = next((it for it in data_store if it['id'] == item_id), None)
    if item is None:
        return Response(
            f"Item {item_id} not found.",
            status=404,
            mimetype='text/html',
        )
    return jsonify(item)


@app.route('/getpost/<int:item_id>/<name>', methods=['GET'])
def add_item(item_id, name):
    """Append a new item to the data store, ignoring existing id, defaulting done=False."""
    new_id = item_id
    if new_id in (it['id'] for it in data_store):
        new_id += 1

    new_item = {
        "id": new_id,
        "name": name,
        "done": False,
    }
    data_store.append(new_item)
    return jsonify(data_store)


@app.route('/postjson', methods=['POST', 'GET'])
def post_json():
    """Create a new item via JSON or form-encoded data, returning the updated list."""
    if request.method == 'POST':
        # Process form-encoded data
        if 'name' not in request.form:
            return Response(
                "Missing 'name' field in form data.",
                status=400,
                mimetype='text/html',
            )
        name = request.form['name']
        done = request.form.get('done', False)
        new_id = data_store[-1]['id'] + 1 if data_store else 1
    else:
        # Process application/json payload
        try:
            payload = request.get_json(silent=False)
            if not isinstance(payload, dict):
                return Response(
                    "JSON payload must be an object.",
                    status=400,
                    mimetype='text/html',
                )
            name = payload.get('name', '')
            done = payload.get('done', False)
            new_id = payload.get('id', data_store[-1]['id'] + 1 if data_store else 1)
        except (TypeError, ValueError):
            return Response(
                "Invalid JSON payload.",
                status=400,
                mimetype='text/html',
            )

    new_item = {
        "id": new_id,
        "name": name,
        "done": bool(done),
    }
    data_store.append(new_item)
    return jsonify(data_store)


@app.route('/')
def index():
    """Root route for basic access."""
    return Response("Welcome to the Flask app!", mimetype='text/html')


if __name__ == '__main__':
    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        # Start the Flask application
        app.run(host='0.0.0.0', debug=False)
    except Exception as e:
        print(f"Flask application error: {e}")
    finally:
        print("Shutting down Flask application.")

