import time
import sys

BLUETOOTH_DEVICE = "/dev/rfcomm4"
BLUETOOTH_BAUDRATE = 38400


def send_command(ser, command):
    """Sends a command over the serial connection with error handling."""
    try:
        command_with_prefix = 'X' + command + '\n'
        ser.write(command_with_prefix.encode('utf-8'))
        ser.flush()
        print(f"Sent: {command}")
        time.sleep(0.1)
    except serial.SerialException as e:
        raise RuntimeError(f"Serial communication error: {e}")
    except Exception as e:
        raise RuntimeError(f"Unexpected error during send: {e}")


def main():
    """Main function to handle user input and send commands."""
    bluetooth_serial = None
    try:
        bluetooth_serial = serial.Serial(
            port=BLUETOOTH_DEVICE,
            baudrate=BLUETOOTH_BAUDRATE,
            timeout=1
        )
        print(f"Connected to {BLUETOOTH_DEVICE} at {BLUETOOTH_BAUDRATE} baud.")

        while True:
            try:
                user_command = input("Enter command (or 'exit' to quit): ")
                if user_command.lower() == 'exit':
                    print("Exiting...")
                    break
                send_command(bluetooth_serial, user_command)
            except EOFError:
                print("\nEnd of input stream. Exiting.")
                break
            except RuntimeError as e:
                print(f"Error: {e}")
                break

    except serial.SerialException as e:
        print(f"Error: Could not open serial port {BLUETOOTH_DEVICE}. "
              f"Check if the device is connected and the baud rate is correct.")
        print(f"Details: {e}")
    except KeyboardInterrupt:
        print("\nInterrupted by user. Exiting...")
    finally:
        if bluetooth_serial is not None and bluetooth_serial.is_open:
            bluetooth_serial.close()
            print("Serial connection closed.")


if __name__ == "__main__":
    main()

